                )}

                {/* Desktop Navigation */}
                {!isMobile && (
                    <>
                        {/* Navigation Orb - shown when nav is collapsed */}
                        {isNavCollapsed && (
                            <Draggable
                                position={orbPosition}
                                onStart={() => { orbDragRef.current = false; }}
                                onDrag={() => { orbDragRef.current = true; }}
                                onStop={(e, data) => {
                                    const newPos = { x: data.x, y: data.y };
                                    setOrbPosition(newPos);
                                    orbPositionRef.current = newPos;
                                    try { localStorage.setItem('mythrill-nav-orb', JSON.stringify(newPos)); } catch {}
                                    if (!orbDragRef.current) {
                                        setIsNavCollapsed(false);
                                        try { localStorage.setItem('mythrill-nav-collapsed', 'false'); } catch {}
                                        setPosition({
                                            x: Math.max(0, newPos.x - size.width / 2),
                                            y: Math.max(0, newPos.y - size.height - 40)
                                        });
                                    }
                                }}
                                nodeRef={orbRef}
                            >
                                <div
                                    ref={orbRef}
                                    className="nav-orb"
                                    title="Expand Navigation (~)"
                                >
                                    <div className="nav-orb-inner">
                                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                            <path d="M6 15l6-6 6 6" />
                                        </svg>
                                    </div>
                                    <div className="nav-orb-pulse" />
                                </div>
                            </Draggable>
                        )}
                        <Draggable
                            handle=".wow-nav-grid"
                            position={position}
                            onStop={(e, data) => setPosition({ x: data.x, y: data.y })}
                            nodeRef={nodeRef}
                        >
                            <div
                                ref={nodeRef}
                                className={`nav-wrapper ${isNavCollapsed ? 'nav-wrapper--collapsed' : ''}`}
                                onMouseEnter={() => setIsNavHovered(true)}
                                onMouseLeave={() => setIsNavHovered(false)}
                            >
                            <Resizable
                                width={size.width}
                                height={size.height}
                                onResize={handleResize}
                                draggableOpts={{ grid: [10, 10] }}
                                minConstraints={[200, 50]}
                                maxConstraints={[800, 50]}
                                resizeHandles={['e']}
                                handle={<div className="custom-resize-handle" />}
                            >
                                <div className="wow-nav-container" style={{
                                    width: size.width,
                                    height: size.height,
                                }}>
                                    <div className="wow-nav-grid" ref={gridRef}>
                                        {NAV_CATEGORIES.map(cat => {
                                            const members = buttons.filter(b => b && b.id && (BUTTON_CATEGORY[b.id] || 'system') === cat.id);
                                            if (!members.length) return null;
                                            const isOpen = openCategory === cat.id;
                                            return (
                                                <div className="wow-nav-category" key={cat.id}>
                                                    <button
                                                        className={`wow-nav-category-header ${isOpen ? 'open' : ''}`}
                                                        onClick={(e) => { e.preventDefault(); e.stopPropagation(); toggleCategoryMenu(cat.id); }}
                                                        onTouchEnd={(e) => { e.preventDefault(); e.stopPropagation(); toggleCategoryMenu(cat.id); }}
                                                        title={`${cat.label} (${members.length})`}
                                                        style={{ pointerEvents: 'auto', cursor: 'pointer' }}
                                                    >
                                                        <svg viewBox="0 0 24 24" className="wow-nav-category-icon" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                                            {cat.svg}
                                                        </svg>
                                                        <span className="wow-nav-category-label">{cat.label}</span>
                                                        <span className="wow-nav-category-chevron" aria-hidden="true" />
                                                    </button>
                                                    {isOpen && (
                                                        <div className="wow-nav-flyout" onClick={(e) => e.stopPropagation()}>
                                                            <div className="wow-nav-flyout-title">{cat.label}</div>
                                                            {members.map(b => {
                                                                const bActive = b.id === 'leveleditor'
                                                                    ? isEditorMode
                                                                    : b.id === 'combat'
                                                                        ? (isSelectionMode || isInCombat)
                                                                        : openWindows.has(b.id);
                                                                return (
                                                                    <button
                                                                        key={b.id}
                                                                        className={`wow-nav-flyout-item ${bActive ? 'active' : ''} ${b.premium ? 'premium' : ''}`}
                                                                        onClick={(e) => { e.preventDefault(); e.stopPropagation(); handleButtonClick(b.id); setOpenCategory(null); }}
                                                                        onTouchEnd={(e) => { e.preventDefault(); e.stopPropagation(); handleButtonClick(b.id); setOpenCategory(null); }}
                                                                        title={`${b.title || b.id}${b.shortcut ? ' (' + b.shortcut + ')' : ''}${b.premium ? ' - Premium' : ''}`}
                                                                    >
                                                                        <svg viewBox="0 0 24 24" className="wow-nav-flyout-item-icon" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                                                            {b.svg}
                                                                        </svg>
                                                                        <span className="wow-nav-flyout-item-label">{b.title || b.id}</span>
                                                                        {b.shortcut && <em className="wow-nav-flyout-item-shortcut">{b.shortcut}</em>}
                                                                        {b.id === 'community' && totalCommunityUnread > 0 && (
                                                                            <span className="nav-notification-badge">{totalCommunityUnread > 99 ? '99+' : totalCommunityUnread}</span>
                                                                        )}
                                                                    </button>
                                                                );
                                                            })}
                                                        </div>
                                                    )}
                                                </div>
                                            );
                                        })}
                                        <span className="wow-nav-divider" aria-hidden="true" />
                                        {buttons.filter(b => b && b.id && (BUTTON_CATEGORY[b.id] || 'system') === 'system').map(renderWowNavButton)}

                                        {/* Back to Landing Page Button */}
                                        {onReturnToLanding && (
                                            <button
                                                onClick={onReturnToLanding}
                                                onTouchStart={(e) => {
                                                    e.preventDefault();
                                                    e.stopPropagation();
                                                }}
                                                onTouchEnd={(e) => {
                                                    e.preventDefault();
                                                    e.stopPropagation();
                                                    onReturnToLanding();
                                                }}
                                                className="wow-nav-button back-button"
                                                title="Return to Main Menu (ESC)"
                                                style={{ pointerEvents: 'auto', cursor: 'pointer', touchAction: 'manipulation' }}
                                            >
                                                <svg
                                                    viewBox="0 0 24 24"
                                                    className="wow-nav-icon"
                                                    fill="none"
                                                    stroke="currentColor"
                                                    strokeWidth="2"
                                                    strokeLinecap="round"
                                                    strokeLinejoin="round"
                                                >
                                                    <path d="M19 12H5M12 19l-7-7 7-7" />
                                                </svg>
                                                <div className="shortcut">
                                                    ESC
                                                </div>
                                            </button>
                                        )}

                                        <button
                                            onClick={(e) => { e.preventDefault(); e.stopPropagation(); handleToggleCollapse(); }}
                                            onTouchEnd={(e) => { e.preventDefault(); e.stopPropagation(); handleToggleCollapse(); }}
                                            className="wow-nav-button wow-nav-minimize"
                                            title="Minimize Navigation (~)"
                                            style={{ pointerEvents: 'auto', cursor: 'pointer', touchAction: 'manipulation' }}
                                        >
                                            <svg viewBox="0 0 24 24" className="wow-nav-icon" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                                <path d="M6 9l6 6 6-6" />
                                            </svg>
                                            <div className="shortcut">~</div>
                                        </button>

                                    </div>
                                </div>
                            </Resizable>
                        </div>
                    </Draggable>
                    </>
                )}

                {/* Grid Coordinates Display */}
                {(() => {
                    // Calculate grid coordinates with decimal precision
                    // Note: Negative sign accounts for coordinate system inversion
                    const gridX = -(cameraX || 0) / (gridSize || 50);
                    const gridY = -(cameraY || 0) / (gridSize || 50);

                    // Calculate a contrasting color based on background
                    const getContrastColor = (bgColor) => {
                        if (!bgColor) return '#5a3b2e'; // Default dark brown

                        // Parse hex color
                        const hex = bgColor.replace('#', '');
                        const r = parseInt(hex.substr(0, 2), 16);
                        const g = parseInt(hex.substr(2, 2), 16);
                        const b = parseInt(hex.substr(4, 2), 16);

                        // Calculate luminance
                        const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;

                        // Return dark color for light backgrounds, light color for dark backgrounds
                        // But make it a nice color, not pure black/white
                        if (luminance > 0.6) {
                            // Light background - use dark brown/rust color
                            return '#5a3b2e';
                        } else if (luminance > 0.4) {
                            // Medium background - use medium brown
                            return '#8b6f47';
                        } else {
                            // Dark background - use light beige
                            return '#d4c5b9';
                        }
                    };

                    const textColor = getContrastColor(gridBackgroundColor || '#d4c5b9');

                    return (
                        <div
                            className="grid-coordinates-display"
                            title="Click to center on origin (0, 0)"
                            onClick={() => setCameraPosition(0, 0)}
                            style={{
                                position: 'fixed',
                                top: '12px',
                                left: '12px',
                                color: textColor,
                                fontFamily: 'Courier New, Monaco, monospace',
                                fontSize: '14px',
                                fontWeight: '600',
                                zIndex: 99999,
                                visibility: 'visible',
                                opacity: 1,
                                display: 'flex',
                                alignItems: 'center',
                                gap: '6px',
                                pointerEvents: 'auto',
                                cursor: 'pointer',
                                userSelect: 'none'
                            }}
                        >
                            <i className="fas fa-crosshairs" style={{ marginRight: '6px', color: textColor, fontSize: '12px', opacity: 0.8 }}></i>
                            <span style={{ color: textColor, fontWeight: '600' }}>X: {gridX.toFixed(1)}</span>
                            <span style={{ margin: '0 8px', color: textColor, opacity: 0.6 }}>|</span>
                            <span style={{ color: textColor, fontWeight: '600' }}>Y: {gridY.toFixed(1)}</span>
                            <i
                                className="fas fa-map-marker-alt"
                                onClick={(e) => {
                                    e.stopPropagation();
                                    setInputX(gridX.toFixed(1));
                                    setInputY(gridY.toFixed(1));
                                    setShowCoordinatePopup(true);
                                }}
                                style={{
                                    marginLeft: '8px',
                                    color: textColor,
                                    fontSize: '14px',
                                    opacity: 0.8,
                                    cursor: 'pointer',
                                    transition: 'opacity 0.2s'
                                }}
                                onMouseEnter={(e) => e.target.style.opacity = '1'}
                                onMouseLeave={(e) => e.target.style.opacity = '0.8'}
                                title="Jump to coordinates"
                            ></i>
                        </div>
                    );
                })()}



                {/* Coordinate Input Popup */}
                {showCoordinatePopup && (
                    <div
                        style={{
                            position: 'fixed',
                            top: '50%',
                            left: '50%',
                            transform: 'translate(-50%, -50%)',
                            backgroundColor: '#2c1810',
                            border: '2px solid #8b6f47',
                            borderRadius: '8px',
                            padding: '20px',
                            zIndex: 100000,
                            boxShadow: '0 4px 20px rgba(0, 0, 0, 0.5)',
                            minWidth: '300px',
                            fontFamily: 'Bookman Old Style, Garamond, serif'
                        }}
                        onClick={(e) => e.stopPropagation()}
                    >
                        <div style={{ marginBottom: '15px', color: '#d4c5b9', fontSize: '16px', fontWeight: '600' }}>
                            Jump to Coordinates
                        </div>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                            <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                                <label style={{ color: '#d4c5b9', minWidth: '30px', fontFamily: 'Courier New, Monaco, monospace' }}>X:</label>
                                <input
                                    type="number"
                                    step="0.1"
                                    value={inputX}
                                    onChange={(e) => setInputX(e.target.value)}
                                    onKeyDown={(e) => {
                                        if (e.key === 'Enter') {
                                            e.preventDefault();
                                            const x = parseFloat(inputX) || 0;
                                            const y = parseFloat(inputY) || 0;
                                            // Convert grid coordinates to camera position
                                            // Reverse of: gridX = -(cameraX || 0) / (gridSize || 50)
                                            const cameraXPos = -(x * (gridSize || 50));
                                            const cameraYPos = -(y * (gridSize || 50));
                                            setCameraPosition(cameraXPos, cameraYPos);
                                            setShowCoordinatePopup(false);
                                        } else if (e.key === 'Escape') {
                                            setShowCoordinatePopup(false);
                                        }
                                    }}
                                    style={{
                                        flex: 1,
                                        padding: '8px',
                                        backgroundColor: '#1a1008',
                                        border: '1px solid #8b6f47',
                                        borderRadius: '4px',
                                        color: '#d4c5b9',
                                        fontFamily: 'Courier New, Monaco, monospace',
                                        fontSize: '14px'
                                    }}
                                    autoFocus
                                />
                            </div>
                            <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                                <label style={{ color: '#d4c5b9', minWidth: '30px', fontFamily: 'Courier New, Monaco, monospace' }}>Y:</label>
                                <input
                                    type="number"
                                    step="0.1"
                                    value={inputY}
                                    onChange={(e) => setInputY(e.target.value)}
                                    onKeyDown={(e) => {
                                        if (e.key === 'Enter') {
                                            e.preventDefault();
                                            const x = parseFloat(inputX) || 0;
                                            const y = parseFloat(inputY) || 0;
                                            // Convert grid coordinates to camera position
                                            const cameraXPos = -(x * (gridSize || 50));
                                            const cameraYPos = -(y * (gridSize || 50));
                                            setCameraPosition(cameraXPos, cameraYPos);
                                            setShowCoordinatePopup(false);
                                        } else if (e.key === 'Escape') {
                                            setShowCoordinatePopup(false);
                                        }
                                    }}
                                    style={{
                                        flex: 1,
                                        padding: '8px',
                                        backgroundColor: '#1a1008',
                                        border: '1px solid #8b6f47',
                                        borderRadius: '4px',
                                        color: '#d4c5b9',
                                        fontFamily: 'Courier New, Monaco, monospace',
                                        fontSize: '14px'
                                    }}
                                />
                            </div>
                            <div style={{ display: 'flex', gap: '10px', marginTop: '10px' }}>
                                <button
                                    onClick={() => {
                                        const x = parseFloat(inputX) || 0;
                                        const y = parseFloat(inputY) || 0;
                                        // Convert grid coordinates to camera position
                                        const cameraXPos = -(x * (gridSize || 50));
                                        const cameraYPos = -(y * (gridSize || 50));
                                        setCameraPosition(cameraXPos, cameraYPos);
                                        setShowCoordinatePopup(false);
                                    }}
                                    style={{
                                        flex: 1,
                                        padding: '10px',
                                        backgroundColor: '#8b6f47',
                                        border: 'none',
                                        borderRadius: '4px',
                                        color: '#f0e6d2',
                                        fontFamily: 'Bookman Old Style, Garamond, serif',
                                        fontSize: '14px',
                                        fontWeight: '600',
                                        cursor: 'pointer',
                                        transition: 'background-color 0.2s'
                                    }}
                                    onMouseEnter={(e) => e.target.style.backgroundColor = '#a08c70'}
                                    onMouseLeave={(e) => e.target.style.backgroundColor = '#8b6f47'}
                                >
                                    Jump
                                </button>
                                <button
                                    onClick={() => setShowCoordinatePopup(false)}
                                    style={{
                                        flex: 1,
                                        padding: '10px',
                                        backgroundColor: '#5a3b2e',
                                        border: 'none',
                                        borderRadius: '4px',
                                        color: '#d4c5b9',
                                        fontFamily: 'Bookman Old Style, Garamond, serif',
                                        fontSize: '14px',
                                        fontWeight: '600',
                                        cursor: 'pointer',
                                        transition: 'background-color 0.2s'
                                    }}
                                    onMouseEnter={(e) => e.target.style.backgroundColor = '#6b4a3a'}
                                    onMouseLeave={(e) => e.target.style.backgroundColor = '#5a3b2e'}
                                >
                                    Cancel
                                </button>
                            </div>
                        </div>
                    </div>
                )}

                {/* Backdrop to close popup when clicking outside */}
                {showCoordinatePopup && (
                    <div
                        style={{
                            position: 'fixed',
                            top: 0,
                            left: 0,
                            right: 0,
                            bottom: 0,
                            backgroundColor: 'rgba(0, 0, 0, 0.5)',
                            zIndex: 99999
                        }}
                        onClick={() => setShowCoordinatePopup(false)}
                    />
                )}

                {buttons.filter(button => button && button.id).map(button => (
                    <React.Fragment key={`window-${button.id}`}>
                        {getWindowContent(button)}
                    </React.Fragment>
                ))}
                {/* Exit Game Confirmation Dialog */}
                {showExitConfirm && (
                    <Suspense fallback={null}>
                        <ExitGameConfirmDialog
                            gameName="Mythrill"
                            onConfirm={() => {
                                setShowExitConfirm(false);
                                if (onReturnToLanding) {
                                    onReturnToLanding();
                                }
                            }}
                            onCancel={() => setShowExitConfirm(false)}
                        />
                    </Suspense>
                )}

                {/* Player Display Overlay - Shows GM-shared content */}
                <PlayerDisplayOverlay />
            </Fragment>
    );
}

import React, { useRef, useEffect, useCallback } from 'react';
import useGameStore from '../../store/gameStore';
import { getGridSystem } from '../../utils/InfiniteGridSystem';

/**
 * High-performance canvas-based grid renderer
 * Replaces DOM-based grid tiles with canvas rendering for massive performance improvements
 */
const CanvasGridRenderer = ({
    viewportSize,
    onGridInteraction,
    showGrid = true,
    gridLineColor = 'rgba(77, 155, 230, 0.3)', // Increased opacity for better visibility
    gridLineThickness = 1,
    isDraggingItem = false,
    isDraggingCharacterToken = false,
    isDraggingCamera = false
}) => {
    const canvasRef = useRef(null);
    const interactionCanvasRef = useRef(null);
    const animationFrameRef = useRef(null);
    const lastRenderParams = useRef(null);
    const renderRafRef = useRef(null);
    const isRenderingRef = useRef(false);
    // PERFORMANCE FIX: Throttle zoom renders to prevent excessive re-renders
    const zoomRenderRafRef = useRef(null);
    const lastZoomRenderRef = useRef(0);
    

    
    // Game store state
    const {
        gridSize,
        gridType,
        cameraX,
        cameraY,
        zoomLevel,
        playerZoom,
        gridOffsetX,
        gridOffsetY,
        showGrid: globalShowGrid,
        gridLineThickness: storeGridLineThickness,
        gridLineOpacity: storeGridLineOpacity,
        gridLineColor: storeGridLineColor
    } = useGameStore();
    
    const effectiveZoom = zoomLevel * playerZoom;
    const gridSystem = getGridSystem();

    // Use store values with fallbacks to props
    const finalGridLineColor = storeGridLineColor || gridLineColor;
    const finalGridLineThickness = storeGridLineThickness || gridLineThickness;
    const finalGridLineOpacity = storeGridLineOpacity || 0.8;
    
    // Simplified LOD system - no grid combining, only opacity changes
    const getLODLevel = useCallback((zoom) => {
        if (zoom < 0.6) return 0; // No grid - too zoomed out (much higher threshold)
        return 1; // Always show normal grid without combining boxes
    }, []);

    // Simplified grid properties - no grid combining, only opacity scaling
    const getGridProperties = useCallback((lodLevel, baseSpacing, zoom) => {
        switch (lodLevel) {
            case 0:
                return { spacing: 0, opacity: 0, lineWidth: 0, skipFactor: 1 }; // No grid
            case 1:
                return {
                    spacing: baseSpacing,
                    opacity: Math.min(0.8, Math.max(0.3, zoom * 1.2)), // Scale opacity with zoom
                    lineWidth: Math.max(0.5, Math.min(2.0, zoom * 1.5)), // Scale line width with zoom
                    skipFactor: 1 // NEVER combine grid boxes
                }; // Always normal grid
            default:
                return { spacing: baseSpacing, opacity: 0.7, lineWidth: 1, skipFactor: 1 };
        }
    }, []);
    
    // Optimized grid rendering function - reads camera position directly from store for real-time updates
    const renderGrid = useCallback(() => {
        const canvas = canvasRef.current;
        if (!canvas || !showGrid || !globalShowGrid) return;
        
        // Read current camera position directly from store to avoid stale values during drag
        const currentState = useGameStore.getState();
        const currentCameraX = currentState.cameraX;
        const currentCameraY = currentState.cameraY;
        const currentEffectiveZoom = currentState.zoomLevel * currentState.playerZoom;
        
        const ctx = canvas.getContext('2d');
        const { width, height } = canvas;
        
        // Decide whether we will draw BEFORE clearing to avoid blinking to blank
        const lodLevel = getLODLevel(currentEffectiveZoom);
        const gridProps = getGridProperties(lodLevel, gridSize * currentEffectiveZoom, currentEffectiveZoom);

        if (lodLevel === 0 || gridProps.spacing < 1) {
            // Keep previous frame visible instead of clearing to prevent invisibility during drag
            return; // Skip drawing at very low zoom or tiny spacing
        }

        // Clear canvas only when we're about to draw
        ctx.clearRect(0, 0, width, height);
        
        // Calculate viewport bounds in world coordinates using current camera position
        const viewportBounds = {
            left: currentCameraX - (width / 2) / currentEffectiveZoom,
            right: currentCameraX + (width / 2) / currentEffectiveZoom,
            top: currentCameraY - (height / 2) / currentEffectiveZoom,
            bottom: currentCameraY + (height / 2) / currentEffectiveZoom
        };

        // Check grid type
        const currentGridType = currentState.gridType || 'square';
        
        if (currentGridType === 'hex') {
            // Render hex grid
            ctx.strokeStyle = finalGridLineColor;
            ctx.lineWidth = Math.max(gridProps.lineWidth, finalGridLineThickness);
            ctx.globalAlpha = gridProps.opacity * finalGridLineOpacity;
            
            // Calculate hex dimensions
            // For flat-top hexagons: if gridSize is the width (flat side to flat side),
            // then the radius (center to corner) is gridSize / sqrt(3)
            const sqrt3 = Math.sqrt(3);
            const hexRadius = gridSize / sqrt3; // Radius for proper tiling (no gaps)
            const hexHeight = gridSize * sqrt3 / 2; // Height (point to point)
            
            // Calculate visible hex bounds by converting viewport corners to hex coordinates
            const topLeftHex = gridSystem.worldToHex(viewportBounds.left, viewportBounds.top);
            const topRightHex = gridSystem.worldToHex(viewportBounds.right, viewportBounds.top);
            const bottomLeftHex = gridSystem.worldToHex(viewportBounds.left, viewportBounds.bottom);
            const bottomRightHex = gridSystem.worldToHex(viewportBounds.right, viewportBounds.bottom);
            
            // Find min/max q and r values with generous padding to ensure full coverage
            const hexStartQ = Math.min(topLeftHex.q, topRightHex.q, bottomLeftHex.q, bottomRightHex.q) - 3;
