      const worldPos = gridSystem.screenToWorld(screenX, screenY, viewportWidth, viewportHeight);

      // Handle expensive operations with simple time-based throttling (no RAF)
      const now = Date.now();

      // PERFORMANCE: Update DOM position immediately for smooth dragging (batched via RAF internally)
      updateDOMPosition(screenX, screenY);

      // PERFORMANCE: Batch React state updates to reduce re-renders
      scheduleStateUpdate(worldPos);

      // CRITICAL FIX: ALWAYS track the pending position during drag for ALL tokens
      // This ensures mouseup has the accurate final position regardless of React state batching
      // Previously this only ran for isViewingFrom tokens, causing snap-back for regular tokens
      pendingWorldPosRef.current = worldPos;

      // PERFORMANCE: Don't update viewing token position during drag - only on drop
      // This prevents expensive fog calculations from running during drag
      if (isViewingFrom) {
        // The fog calculations will run once when the drag ends, which is what we want
        // Position is already tracked in pendingWorldPosRef above
      }

      // FIXED: Update local character token position in store during drag (throttled)
      // This prevents the token from reverting when other parts of the UI re-render
      // but DOES NOT broadcast to other players (that happens only on drop)
      if (now - lastNetworkUpdate > 50) { // 20fps for store updates
        const gridCoords = gridSystem.worldToGrid(worldPos.x, worldPos.y);
        const snappedPos = gridSystem.gridToWorld(gridCoords.x, gridCoords.y);

        updateCharacterTokenPosition(tokenId, {
          ...snappedPos,
          isSyncEvent: false // This marks it as a local movement for echo prevention
        });

        // Standardized tracking for echo prevention
        if (!window.recentTokenMovements) window.recentTokenMovements = new Map();
        window.recentTokenMovements.set(`token_${tokenId}`, {
          position: { x: snappedPos.x, y: snappedPos.y },
          timestamp: now,
          isLocal: true
        });

        lastNetworkUpdate = now;
      }

      // FIXED: Removed real-time movement updates during drag to ensure more stable placement on other players' screens
      // Token position will now only broadcast on drop (handleMouseUp) as requested by users
      /*
      if (isInMultiplayer && multiplayerSocket && multiplayerSocket.connected) {
        if (now - lastNetworkUpdate > 100) {
          const gridCoords = gridSystem.worldToGrid(worldPos.x, worldPos.y);
          const snappedPos = gridSystem.gridToWorld(gridCoords.x, gridCoords.y);
  
          multiplayerSocket.emit('character_moved', {
            tokenId: tokenId,
            characterId: tokenPlayerId,
            position: { x: Math.round(snappedPos.x), y: Math.round(snappedPos.y) },
            isDragging: true
          });
          lastNetworkUpdate = now;
        }
      }
      */

      // CRITICAL FIX: Update movement visualization and distance calculation during drag
      if (dragStartPosition && now - lastCombatUpdate > 100) { // 10fps for combat updates (reduced for performance)
        // Calculate grid coordinates for snapping
        const gridCoords = gridSystem.worldToGrid(worldPos.x, worldPos.y);
        const snappedPos = gridSystem.gridToWorld(gridCoords.x, gridCoords.y);

        // Update movement visualization if enabled - use SNAPPED position for clean line
        if (showMovementVisualization && activeMovement?.tokenId === tokenId) {
          updateMovementVisualization({ x: snappedPos.x, y: snappedPos.y });
        }

        // Calculate and update temporary movement distance for tooltip
        // CRITICAL FIX: Use snapped positions for tile-based distance calculation
        const dx = snappedPos.x - dragStartPosition.x;
        const dy = snappedPos.y - dragStartPosition.y;
        const worldDistance = Math.sqrt(dx * dx + dy * dy);
        const tileDistance = worldDistance / gridSystem.getGridState().gridSize;
        const distance = tileDistance * feetPerTile;
        updateTempMovementDistance(tokenId, distance);

        lastCombatUpdate = now;
      }
    };

    const handleMouseUp = (e) => {
      // Removed excessive logging for performance

      // Handle mouse up for both dragging and non-dragging cases
      if (e.button !== 0) return; // Only handle left mouse button

      // If we're not dragging, check if this should be treated as a click
      if (!isDragging) {
        // Check if this was a click (very little movement) vs a drag that never started
        const wasClick = totalDragDistanceRef.current < 3; // 3 pixels threshold for click vs drag

        if (wasClick) {
          // This was a click, not a drag
          // Removed excessive logging for performance
          setIsMouseDown(false);
          isMouseDownRef.current = false;
          setMouseDownPosition(null);
          setDragStartPosition(null);
          return;
        } else {
          // Movement was significant but dragging never started - this shouldn't happen
          // but handle it gracefully by doing nothing (reset state)
          setIsMouseDown(false);
          setMouseDownPosition(null);
          setDragStartPosition(null);
          return;
        }
      }



      e.preventDefault();
      e.stopPropagation();

      // CRITICAL FIX: Reset drag refs IMMEDIATELY at the start of mouseup
      // This prevents any queued mousemove events from updating the store
      // while we're processing the final drop position
      isDraggingRef.current = false;
      isMouseDownRef.current = false;

      // CRITICAL FIX: Set grace period timestamp BEFORE any position updates
      // This protects the final position from useEffect overwriting it
      lastPositionUpdateRef.current = Date.now();

      // CRITICAL FIX: Use the last tracked position instead of recalculating from mouse event
      // When dragging fast, e.clientX/clientY can be stale or represent an intermediate position
      // The pendingWorldPosRef or localPosition contains the actual last rendered position
      let finalWorldPos;

      // Priority 1: Use pending position from last mousemove (most accurate)
      if (pendingWorldPosRef.current) {
        finalWorldPos = { ...pendingWorldPosRef.current };
      }
      // Priority 2: Use current local position (fallback)
      else {
        finalWorldPos = { ...localPosition };
      }

      // Snap to grid for final placement
      const gridCoords = gridSystem.worldToGrid(finalWorldPos.x, finalWorldPos.y);
      const snappedWorldPos = gridSystem.gridToWorld(gridCoords.x, gridCoords.y);

      // Log final position for debugging
      console.log('CharacterToken MouseUp Final Pos (using last tracked):', snappedWorldPos);

      // Capture afterimage and explored area from old position before moving
      const levelEditorStore = useLevelEditorStore.getState();
      if (dragStartPosition && characterData) {
        levelEditorStore.captureTokenMovementAfterimage(
          tokenId,
          characterData,
          dragStartPosition,
          snappedWorldPos
        );
      }

      // Update final position with grid snapping
      updateCharacterTokenPosition(tokenId, { x: snappedWorldPos.x, y: snappedWorldPos.y });

      // Update local position immediately to prevent visual jumps
      setLocalPosition({ x: snappedWorldPos.x, y: snappedWorldPos.y });

      // CRITICAL FIX: Update lastPositionUpdateRef to enable the grace period
      // This prevents the useEffect from accepting external updates for 1000ms
      lastPositionUpdateRef.current = Date.now();

      // PERFORMANCE: If this is the viewing token, update its position ONLY on drop (not during drag)
      // This ensures fog calculations run once when drag ends, not continuously during drag
      // FIXED: Force visibility recalculation when token is dropped
      if (isViewingFrom) {
        const levelEditorStore = useLevelEditorStore.getState();
        const currentViewingToken = levelEditorStore.viewingFromToken;
        if (currentViewingToken) {
          // Update position - this will trigger visibility recalculation
          // The StaticFogOverlay will detect the drag end and clear cache
          levelEditorStore.setViewingFromToken({
            ...currentViewingToken,
            position: { x: snappedWorldPos.x, y: snappedWorldPos.y }
          });
        }
      }

      // Note: Drag refs already reset at start of mouseup handler

      // CRITICAL FIX: Handle combat movement validation if in combat
      if (isInCombat && dragStartPosition) {
        // Validate movement - combatStore handles character tokens internally
        const validation = validateMovement(tokenId, dragStartPosition, snappedWorldPos, [], feetPerTile);

        if (validation.needsConfirmation) {
          // Movement requires confirmation - show dialog
          const combatant = useCombatStore.getState().turnOrder.find(c => c.tokenId === tokenId);
          setPendingMovementConfirmation({
            tokenId,
            startPosition: dragStartPosition,
            finalPosition: snappedWorldPos,
            requiredAP: validation.additionalAPNeeded,
            totalDistance: validation.totalMovementAfterThis,
            baseMovement: validation.creatureSpeed,
            currentAP: combatant?.currentActionPoints || 0,
            creatureName: characterData.name || 'Character',
            movementUsedThisTurn: validation.movementUsedThisTurn,
            feetPerTile: feetPerTile,
            currentMovementDistance: validation.currentMovementFeet
          });
        } else if (validation.isValid) {
          // Movement is valid - auto-confirm
          // CRITICAL FIX: Pass totalMovementAfterThis (cumulative) instead of currentMovementFeet (just this move)
          // This ensures movement tracking accumulates properly instead of resetting
          confirmMovement(tokenId, validation.additionalAPNeeded, validation.totalMovementAfterThis);

          // Send to multiplayer
          if (isInMultiplayer && multiplayerSocket && multiplayerSocket.connected) {
            // Standardized tracking for echo prevention
            if (!window.recentTokenMovements) window.recentTokenMovements = new Map();
            window.recentTokenMovements.set(`token_${tokenId}`, {
              position: { x: snappedWorldPos.x, y: snappedWorldPos.y },
              timestamp: Date.now(),
              isLocal: true
            });
            multiplayerSocket.emit('character_moved', {
              tokenId: tokenId, // Pass actual token UUID for store identification
              characterId: tokenPlayerId, // Keep for backward compatibility
              position: { x: Math.round(snappedWorldPos.x), y: Math.round(snappedWorldPos.y) },
              isDragging: false
            });
          }
        }
      } else {
        // Not in combat - send final position to multiplayer
        console.log('­ƒöÀ CharacterToken drop - checking multiplayer:', {
          isInMultiplayer,
          hasSocket: !!multiplayerSocket,
          connected: multiplayerSocket?.connected,
          tokenId,
          position: snappedWorldPos
        });
        if (isInMultiplayer && multiplayerSocket && multiplayerSocket.connected) {
          // Standardized tracking for echo prevention
          if (!window.recentTokenMovements) window.recentTokenMovements = new Map();
          window.recentTokenMovements.set(`token_${tokenId}`, {
            position: { x: snappedWorldPos.x, y: snappedWorldPos.y },
            timestamp: Date.now(),
            isLocal: true
          });
          console.log('­ƒôñ Emitting character_moved to server:', {
            tokenId,
            characterId: tokenPlayerId,
            position: { x: Math.round(snappedWorldPos.x), y: Math.round(snappedWorldPos.y) }
          });
          multiplayerSocket.emit('character_moved', {
            tokenId: tokenId, // Pass actual token UUID for store identification
            characterId: tokenPlayerId, // Keep for backward compatibility
            position: { x: Math.round(snappedWorldPos.x), y: Math.round(snappedWorldPos.y) },
            isDragging: false
          });
        }
      }

      // CRITICAL FIX: Clear movement visualization when drag ends
      clearMovementVisualization();

      // End dragging and reset all states
      setIsDragging(false);
      setIsMouseDown(false);
      setMouseDownPosition(null);
      setDragStartPosition(null);
      // PERFORMANCE: Clear global token drag flag
      window._isDraggingToken = false;

      // CRITICAL FIX: Clear global token interaction flag
      window.tokenInteractionActive = false;
      window.tokenInteractionTimestamp = null;

      // CRITICAL FIX: Clear pending position ref AFTER mouseup has used it
      // This ensures mouseup always gets the accurate final drop position
      pendingWorldPosRef.current = null;

      // Clear drag state globally to allow network updates again
      if (window.multiplayerDragState) {
        window.multiplayerDragState.delete('character');
        // Removed excessive logging for performance
      }

      // Clear the drag timeout since we successfully handled mouse up
      if (dragTimeoutId) {
        clearTimeout(dragTimeoutId);
        dragTimeoutId = null;
      }
    };

    // CRITICAL FIX: Handle mouse leaving window during drag
    const handleMouseLeave = (e) => {
      // Only trigger if we're actively dragging
      if (isDragging) {
        // Trigger mouseup to properly finalize the position
        handleMouseUp(e);
      }
    };

    const handlePointerMove = (e) => {
      if (e.pointerType === 'touch') {
        handleMouseMove(e);
      }
    };

    const handlePointerUp = (e) => {
      if (e.pointerType === 'touch') {
        handleMouseUp(e);
      }
    };

    if (isDragging || isMouseDown) {
      // Add the event listeners to the document to ensure they work even if the cursor moves outside the token
      // Use passive: false for both mousemove and mouseup to allow preventDefault
      document.addEventListener('mousemove', handleMouseMove, { passive: false });
      document.addEventListener('mouseup', handleMouseUp, { passive: false });
      document.addEventListener('pointermove', handlePointerMove, { passive: false });
      document.addEventListener('pointerup', handlePointerUp, { passive: false });
      document.addEventListener('pointercancel', handlePointerUp, { passive: false });

      // CRITICAL FIX: Handle mouse leaving the window to prevent position jumps
      document.addEventListener('mouseleave', handleMouseLeave, { passive: false });

      // Safety timeout to reset dragging state if mouse up is missed (e.g., cursor leaves window)
      // CRITICAL FIX: Increased from 5s to 30s to prevent interrupting long drags
      // This is now a last resort since we handle mouseleave properly
      dragTimeoutId = setTimeout(() => {
        console.warn('ÔÅ░ Character drag timeout triggered after 30s - this should rarely happen');
        setIsDragging(false);
        setIsMouseDown(false);
        setMouseDownPosition(null);
        setDragStartPosition(null);
        // PERFORMANCE: Clear global token drag flag
        window._isDraggingToken = false;
        if (window.multiplayerDragState) {
          window.multiplayerDragState.delete('character');
        }
        window.tokenInteractionActive = false;
        window.tokenInteractionTimestamp = null;
      }, 30000); // 30 second timeout (safety net only)
    }

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
      document.removeEventListener('mouseleave', handleMouseLeave);
      document.removeEventListener('pointermove', handlePointerMove);
      document.removeEventListener('pointerup', handlePointerUp);
      document.removeEventListener('pointercancel', handlePointerUp);
      if (dragTimeoutId) {
        clearTimeout(dragTimeoutId);
      }
      // PERFORMANCE: Cancel any pending RAF updates
      if (rafIdRef.current !== null) {
        cancelAnimationFrame(rafIdRef.current);
        rafIdRef.current = null;
      }
      // NOTE: Do NOT clear pendingWorldPosRef here!
      // This cleanup runs every time dependencies change (isDragging, position, etc.)
      // which would wipe the tracked position during drag.
      // pendingWorldPosRef is cleared by mouseup handler after reading it.
    };
  }, [
    isDragging,
    isMouseDown,
    isInMultiplayer,
    multiplayerSocket,
    position,
    dragOffset,
    mouseDownPosition,
    gridSystem,
    tokenId,
    showMovementVisualization,
    startMovementVisualization,
    updateMovementVisualization,
    clearMovementVisualization,
    updateTempMovementDistance,
    activeMovement,
    dragStartPosition,
    feetPerTile
  ]);

  // Handle context menu
  const handleContextMenu = (e) => {
    e.preventDefault();
    e.stopPropagation();

    setContextMenuPosition({ x: e.clientX, y: e.clientY });
    setShowContextMenu(true);
  };

  // Close context menu when clicking outside and cleanup tooltip timeout
  useEffect(() => {
    const handleClickOutside = (e) => {
      // Don't close if clicking on context menu or its children
      if (contextMenuRef.current && !contextMenuRef.current.contains(e.target)) {
        // Use a small delay to allow onClick handlers to execute first
        setTimeout(() => {
          setShowContextMenu(false);
        }, 10);
      }
    };

    if (showContextMenu) {
      // Use click instead of mousedown to allow onClick handlers to execute first
      document.addEventListener('click', handleClickOutside, true);
    }

    return () => {
      document.removeEventListener('click', handleClickOutside, true);
    };
  }, [showContextMenu]);

  // Cleanup tooltip timeout on unmount
  useEffect(() => {
    return () => {
      if (tooltipTimeoutRef.current) {
        clearTimeout(tooltipTimeoutRef.current);
      }
    };
  }, []);

  // Handle targeting
  const handleTarget = () => {
    if (isTargeted) {
      clearTarget();
    } else {
      // Use the same structure as PartyHUD for consistency
      const targetData = {
        id: 'current-player', // Use consistent ID for current player
        name: characterData.name,
        type: 'party_member', // Use party_member type for consistency
        data: {
          id: 'current-player',
          name: characterData.name,
          role: 'member',
          status: 'online',
          character: {
            level: characterData.level,
            race: characterData.race,
            class: characterData.class,
            alignment: characterData.alignment || 'Neutral',
            exhaustionLevel: characterData.exhaustionLevel || 0,
            health: characterData.health,
            mana: characterData.mana,
            actionPoints: characterData.actionPoints,
            classResource: characterData.classResource
          }
        }
      };
      setTarget(targetData, 'party_member');
    }
    setShowContextMenu(false);
  };

  // Handle inspect
  const handleInspectCharacter = () => {
    if (onInspect) {
      // Check if this is another player's token
      const currentPlayer = useGameStore.getState().currentPlayer;
      const myId = currentPlayer?.id || 'current-player';
      const isSelf = tokenPlayerId === 'current-player' || (myId && tokenPlayerId === myId);
      const isOtherPlayer = tokenPlayerId && !isSelf && isInMultiplayer;
      onInspect(characterData, isSelf); // true if it's our own token
    }

    setShowContextMenu(false);
  };

  // Handle remove token
  const handleRemoveToken = () => {
    if (onRemove) {
      onRemove(tokenId);
    }
    setShowContextMenu(false);
  };

  // Handle duplicate token
  const handleDuplicateToken = () => {
    console.log('Duplicating character token:', tokenId);
    // For character tokens, we might want to create a new token at a nearby position
    // This would need to be implemented in the character token store
    setShowContextMenu(false);
  };

  // Unified resource update handler with multiplayer sync
  const handleResourceUpdate = (resourceType, newValue, adjustment, asTemporary = false) => {
    const currentPlayer = useGameStore.getState().currentPlayer;
    const myId = currentPlayer?.id || 'current-player';
    // FIX: Also check socket ID since tokenPlayerId might be a socket ID
    const mySocketId = multiplayerSocket?.id;
    // FIX: Include check for local player tokens
    const isSelf = tokenPlayerId === 'current-player' || 
            (myId && tokenPlayerId === myId) || 
            (mySocketId && tokenPlayerId === mySocketId) ||
            (token?.isPlayerToken && !isInMultiplayer);

    if (isSelf) {
      // Update characterStore for the current player
      const charState = useCharacterStore.getState();
      const tempField = `temp${resourceType.charAt(0).toUpperCase() + resourceType.slice(1)}`;
      const currentTemp = charState[tempField] || 0;
      const maxValue = charState[resourceType]?.max || 0;

      if (asTemporary && adjustment > 0) {
        // Add as temporary resource (overheal)
        const overhealAmount = adjustment - (maxValue - (charState[resourceType]?.current || 0));
        charState.updateResource(resourceType, maxValue, undefined, undefined, true);
        charState.updateTempResource(resourceType, currentTemp + overhealAmount);
      } else if (adjustment < 0) {
        // Taking damage/draining - reduce temporary resources first
        const absAdjustment = Math.abs(adjustment);
        let remainingAdjustment = absAdjustment;
        let newTemp = currentTemp;
        let newValue = charState[resourceType]?.current || 0;

        // First, reduce temporary resources
        if (currentTemp > 0) {
          if (absAdjustment <= currentTemp) {
            // All damage absorbed by temporary resources
            newTemp = currentTemp - absAdjustment;
            remainingAdjustment = 0;
          } else {
            // Temporary resources exhausted, remaining damage goes to actual resource
            remainingAdjustment = absAdjustment - currentTemp;
            newTemp = 0;
          }
        }

        // Apply remaining damage to actual resource
        if (remainingAdjustment > 0) {
          newValue = Math.max(0, newValue - remainingAdjustment);
        }

        // Update both resource and temporary resource in character store
        charState.updateResource(resourceType, newValue, undefined, undefined, true);
        if (newTemp !== currentTemp) {
          charState.updateTempResource(resourceType, newTemp);
        }
      } else {
        charState.updateResource(resourceType, newValue, undefined);
      }
      
      // CRITICAL FIX: Also update partyStore so PartyHUD sees the change
      const partyState = usePartyStore.getState();
      const selfMember = partyState.partyMembers.find(m => 
        m.id === 'current-player' || 
        m.id === myId || 
        m.socketId === mySocketId ||
        m.userId === myId
      );
      let finalValue = newValue;
      let finalTemp = 0;
      if (selfMember && selfMember.character) {
        const currentValue = selfMember.character[resourceType]?.current || 0;
        finalValue = newValue;
        finalTemp = selfMember.character[tempField] || 0;

        if (asTemporary && adjustment > 0) {
          const overhealAmount = adjustment - (maxValue - currentValue);
          finalValue = maxValue;
          finalTemp += overhealAmount;
        } else if (adjustment < 0) {
          const absAdjustment = Math.abs(adjustment);
          let remainingAdjustment = absAdjustment;
          
          if (finalTemp > 0) {
            if (absAdjustment <= finalTemp) {
              finalTemp -= absAdjustment;
              remainingAdjustment = 0;
            } else {
              remainingAdjustment = absAdjustment - finalTemp;
              finalTemp = 0;
            }
          }
          if (remainingAdjustment > 0) {
            finalValue = Math.max(0, currentValue - remainingAdjustment);
          }
        }

        usePartyStore.getState().updatePartyMember(selfMember.id, {
          character: {
            ...selfMember.character,
            [resourceType]: {
              ...selfMember.character[resourceType],
              current: finalValue
            },
            [tempField]: finalTemp
          }
        });
      }
      
      // Sync via socket if in multiplayer
      if (isInMultiplayer && multiplayerSocket && multiplayerSocket.connected) {
        const gameStore = useGameStore.getState();
        const roomId = gameStore.multiplayerRoom?.id;
        
        multiplayerSocket.emit('character_resource_updated', {
          roomId: roomId,
          playerId: selfMember?.id || myId,
          userId: selfMember?.userId,
          socketId: selfMember?.socketId || mySocketId,
          playerName: selfMember?.name || 'Player',
          resource: resourceType,
          current: newValue,
          max: selfMember?.character?.[resourceType]?.max || 0,
          temp: finalTemp,
          adjustment: adjustment,
          timestamp: Date.now()
        });
      }
    } else if (isGMMode && (tokenPlayerId || token?.isPlayerToken)) {
      // Update party store for GM adjustments on other players
      // FIX: Removed isInMultiplayer requirement - partyStore should update regardless
      const partyState = usePartyStore.getState();
      // FIX: Use multi-field matching like updatePartyMember does
      const member = partyState.partyMembers.find(m => 
        (tokenPlayerId && (
          m.id === tokenPlayerId || 
          m.userId === tokenPlayerId || 
          m.socketId === tokenPlayerId ||
          m.uid === tokenPlayerId
        )) || 
        (token?.isPlayerToken && !tokenPlayerId && (m.id === 'current-player' || m.id === myId))
      );
      if (member && member.character) {
        const max = member.character[resourceType]?.max || 0;
        const tempField = `temp${resourceType.charAt(0).toUpperCase() + resourceType.slice(1)}`;
        const currentTemp = member.character[tempField] || 0;
        const currentValue = member.character[resourceType]?.current || 0;
        let finalValue = newValue;
        let finalTemp = currentTemp;

        if (asTemporary && adjustment > 0) {
          const overhealAmount = adjustment - (max - currentValue);
          finalValue = max;
          finalTemp = currentTemp + overhealAmount;
        } else if (adjustment < 0) {
          const absAdjustment = Math.abs(adjustment);
          let remainingAdjustment = absAdjustment;

          if (currentTemp > 0) {
            if (absAdjustment <= currentTemp) {
              finalTemp = currentTemp - absAdjustment;
              remainingAdjustment = 0;
            } else {
              remainingAdjustment = absAdjustment - currentTemp;
              finalTemp = 0;
            }
          }
          if (remainingAdjustment > 0) {
            finalValue = Math.max(0, currentValue - remainingAdjustment);
          }
        }

        usePartyStore.getState().updatePartyMember(member.id, {
          character: {
            ...member.character,
            [resourceType]: {
              ...member.character[resourceType],
              current: finalValue
            },
            [tempField]: finalTemp
          }
        });

        // Sync via socket only if in multiplayer
        if (isInMultiplayer && multiplayerSocket && multiplayerSocket.connected) {
          const gameStore = useGameStore.getState();
          const roomId = gameStore.multiplayerRoom?.id;
          
          multiplayerSocket.emit('character_resource_updated', {
            roomId: roomId,
            playerId: member.id,
            userId: member.userId || member.uid,
            socketId: member.socketId,
            playerName: member.name,
            resource: resourceType,
            current: finalValue,
            max: max,
            temp: finalTemp,
            adjustment: adjustment,
            timestamp: Date.now()
          });
        }
      } else {
        console.warn('handleResourceUpdate: Member not found for tokenPlayerId:', tokenPlayerId);
      }
    } else {
      console.warn('handleResourceUpdate: Conditions not met', {
        isGMMode, tokenPlayerId, isPlayerToken: token?.isPlayerToken, resourceType, newValue
      });
    }

    // Sync to combat
    if (isInCombat) {
      const combatStore = useCombatStore.getState();
      if (resourceType === 'health') combatStore.updateCombatantHP(tokenId, newValue);
      if (resourceType === 'mana') combatStore.updateCombatantMana(tokenId, newValue);
      if (resourceType === 'actionPoints') combatStore.updateCombatantAP(tokenId, newValue);
    }
  };

  // Handle damage token
  const handleDamageToken = (amount) => {
    const currentHp = characterData.health.current;
    const tempHp = characterData.tempHealth || 0;
    const newHp = Math.max(0, (currentHp + tempHp) - amount);

    handleResourceUpdate('health', newHp, -amount);

    // Floating combat text removed from context menu per user request
    setShowContextMenu(false);
  };

  // Handle heal token
  const handleHealToken = (amount) => {
    const currentHp = characterData.health.current;
    const maxHp = characterData.health.max;
    
    if (currentHp + amount > maxHp) {
      setOverhealData({
        resourceType: 'health',
        adjustment: amount,
        overhealAmount: (currentHp + amount) - maxHp,
        currentValue: currentHp,
        maxValue: maxHp
      });
      setShowOverhealModal(true);
      setShowContextMenu(false); // Close context menu when showing modal
      return;
    }

    const newHp = Math.min(maxHp, currentHp + amount);
    handleResourceUpdate('health', newHp, amount);

    // Floating combat text removed from context menu per user request
  };

  // Handle custom amount damage/heal
  const handleCustomAmount = (type) => {
    setCustomAmountType(type);
    setShowCustomAmountModal(true);
    setShowContextMenu(false);
  };

  // Handle custom amount submission
  const handleCustomAmountSubmit = (amount) => {
    const numAmount = parseInt(amount);
    if (isNaN(numAmount) || numAmount <= 0) return;

    switch (customAmountType) {
      case 'damage':
        handleDamageToken(numAmount);
        break;
      case 'heal':
        handleHealToken(numAmount);
        break;
      case 'mana-damage':
        handleManaDamage(numAmount);
        break;
      case 'mana-heal':
        handleManaHeal(numAmount);
        break;
      case 'ap-spend':
        handleAPSpend(numAmount);
        break;
      case 'ap-restore':
        handleAPRestore(numAmount);
        break;
    }
    setShowCustomAmountModal(false);
    setCustomAmountType('');
  };

  // Handle mana damage
  const handleManaDamage = (amount) => {
    const currentMp = characterData.mana.current;
    const tempMp = characterData.tempMana || 0;
    const newMp = Math.max(0, (currentMp + tempMp) - amount);

    handleResourceUpdate('mana', newMp, -amount);

    // Floating combat text removed from context menu per user request
  };

  // Handle mana heal
  const handleManaHeal = (amount) => {
    const currentMp = characterData.mana.current;
    const maxMp = characterData.mana.max;

    if (currentMp + amount > maxMp) {
      setOverhealData({
        resourceType: 'mana',
        adjustment: amount,
        overhealAmount: (currentMp + amount) - maxMp,
        currentValue: currentMp,
        maxValue: maxMp
      });
      setShowOverhealModal(true);
      setShowContextMenu(false);
      return;
    }

    const newMp = Math.min(maxMp, currentMp + amount);
    handleResourceUpdate('mana', newMp, amount);

    // Floating combat text removed from context menu per user request
  };

  // Handle full heal
  const handleFullHeal = () => {
    const maxHp = characterData.health.max;
    const maxMp = characterData.mana.max;

    handleResourceUpdate('health', maxHp, maxHp - characterData.health.current);
    handleResourceUpdate('mana', maxMp, maxMp - characterData.mana.current);

    // Floating combat text removed from context menu per user request
    setShowContextMenu(false);
  };

  // Handle kill (set health to 0)
  const handleKill = () => {
    const currentHp = characterData.health.current;
    const tempHp = characterData.tempHealth || 0;
    handleResourceUpdate('health', 0, -(currentHp + tempHp));

    // Floating combat text removed from context menu per user request
    setShowContextMenu(false);
  };

  // Handle drain mana (set mana to 0)
  const handleDrainMana = () => {
    const currentMp = characterData.mana.current;
    const tempMp = characterData.tempMana || 0;
    handleResourceUpdate('mana', 0, -(currentMp + tempMp));

    // Floating combat text removed from context menu per user request
    setShowContextMenu(false);
  };

  // Handle AP spend
  const handleAPSpend = (amount) => {
    const currentAP = characterData.actionPoints.current;
    const tempAP = characterData.tempActionPoints || 0;
    const newAP = Math.max(0, (currentAP + tempAP) - amount);
    handleResourceUpdate('actionPoints', newAP, -amount);
    
    // Floating combat text removed from context menu per user request
  };

  // Handle AP restore
  const handleAPRestore = (amount) => {
    const currentAP = characterData.actionPoints.current;
    const maxAP = characterData.actionPoints.max;

    if (currentAP + amount > maxAP) {
      setOverhealData({
        resourceType: 'actionPoints',
        adjustment: amount,
        overhealAmount: (currentAP + amount) - maxAP,
        currentValue: currentAP,
        maxValue: maxAP
      });
      setShowOverhealModal(true);
      setShowContextMenu(false);
      return;
    }

    const newAP = Math.min(maxAP, currentAP + amount);
    handleResourceUpdate('actionPoints', newAP, amount);

    // Floating combat text removed from context menu per user request
  };

  // Handle full AP restore
  const handleFullAPRestore = () => {
    const maxAP = characterData.actionPoints.max;
    handleAPRestore(maxAP);
    setShowContextMenu(false);
  };

  // Handle drain all AP
  const handleDrainAllAP = () => {
    const currentAP = characterData.actionPoints.current;
    const tempAP = characterData.tempActionPoints || 0;
    handleAPSpend(currentAP + tempAP);
    setShowContextMenu(false);
  };

  // State for conditions window
  const [showConditionsWindow, setShowConditionsWindow] = useState(false);

  // State for buff/debuff creator modal
  const [showBuffDebuffCreator, setShowBuffDebuffCreator] = useState(false);
  const [buffDebuffInitialType, setBuffDebuffInitialType] = useState(null);

  // Handle opening conditions window
  const handleOpenConditions = useCallback(() => {
    console.log('Opening conditions window for token:', tokenId);
    setShowConditionsWindow(true);
    setShowContextMenu(false);
  }, [tokenId]);

  // Handle opening buff/debuff creator
  const handleOpenBuffDebuffCreator = useCallback((type = null) => {
    console.log('Opening buff/debuff creator for token:', tokenId, 'type:', type);
    setBuffDebuffInitialType(type);
    setShowBuffDebuffCreator(true);
    setShowContextMenu(false);
  }, [tokenId]);

  // Active condition effects mapped to visual overlays (token state + condition store)
  const activeBuffs = useConditionStore(state => state.activeBuffs);
  const activeDebuffs = useConditionStore(state => state.activeDebuffs);

  const conditionEffects = useMemo(() => {
    const supported = new Set([
      'burning',
      'poisoned',
      'cursed',
      'diseased',
      'hexed',
      'frightened',
      'stunned',
      'paralyzed',
      'blinded',
      'invisible',
      'restrained',
      'grappled',
      'petrified',
      'hastened',
      'hasted',
      'slowed',
      'bleeding',
      'blessed',
      'defending',
      'silenced',
      'dispelled',
      'charmed',
      'confused',
      'exhausted'
    ]);

    const normalize = (value) =>
      (value || '')
        .toString()
        .toLowerCase()
        .replace(/[^a-z]/g, '');

    const aliases = {
      burning: 'burning',
      burn: 'burning',
      fire: 'burning',
      poisoned: 'poisoned',
      poison: 'poisoned',
      cursed: 'cursed',
      curse: 'cursed',
      diseased: 'diseased',
      disease: 'diseased',
      hexed: 'hexed',
      hex: 'hexed',
      hastened: 'hastened',
      hasted: 'hastened',
      haste: 'hastened',
      quickened: 'hastened',
      accelerated: 'hastened',
      slowed: 'slowed',
      slow: 'slowed',
      bleeding: 'bleeding',
      bleed: 'bleeding',
      blessed: 'blessed',
      bless: 'blessed',
      defending: 'defending',
      defend: 'defending',
      silenced: 'silenced',
      silence: 'silenced',
      dispelled: 'dispelled',
      dispel: 'dispelled',
      charmed: 'charmed',
      charm: 'charmed',
      confused: 'confused',
      confuse: 'confused',
      exhausted: 'exhausted',
      exhaust: 'exhausted',
      frightened: 'frightened',
      fear: 'frightened',
      terrified: 'frightened',
      stunned: 'stunned',
      stun: 'stunned',
      paralyzed: 'paralyzed',
      paralyse: 'paralyzed',
      blinded: 'blinded',
      blind: 'blinded',
      invisible: 'invisible',
      invisibility: 'invisible',
      restrained: 'restrained',
      restraint: 'restrained',
      grappled: 'grappled',
      grapple: 'grappled',
      petrified: 'petrified',
      petrify: 'petrified',
    };

    const mapName = (raw) => {
      const norm = normalize(raw);
      if (aliases[norm]) return aliases[norm];
      return supported.has(norm) ? norm : null;
    };

    const collect = [];

    const pushCondition = (key, label) => {
      if (!key) return;
      collect.push({ key, label: label || key.toUpperCase() });
    };

    // Only from token state (authoritative) - conditions only, not buffs/debuffs
    (token.state?.conditions || []).forEach(c => {
      const key = mapName(c.id || c.name) || normalize(c.id || c.name);
      const label = c.name || c.id || key;
      pushCondition(key, label);
    });

    const seen = new Set();
    const unique = [];
    for (const item of collect) {
      if (item.key && !seen.has(item.key)) {
        seen.add(item.key);
        unique.push(item);
      }
    }

    return unique;
  }, [token.state?.conditions, tokenId]);

  // Calculate health percentage for health bar
  const healthPercentage = (characterData.health.current / characterData.health.max) * 100;

  // Get health bar color based on percentage
  const getHealthBarColor = (percentage) => {
    if (percentage > 75) return '#506e30';
    if (percentage > 50) return '#7a6812';
    if (percentage > 25) return '#9a5e15';
    return '#8b3a2a';
  };

  // Don't render if not visible (unless in GM mode or not viewing from a token)
  if (!isTokenVisible) {
    return null;
  }

  return (
    <>
      <div
        ref={tokenRef}
        className={`character-token ${isDragging ? 'dragging' : ''} ${isTargeted ? 'targeted' : ''} ${isMyTurn ? 'my-turn' : ''} ${isViewingFrom ? 'viewing-from' : ''}`}
        style={{
          // CRITICAL: Use transform3d for GPU-accelerated positioning
          left: 0,
          top: 0,
          width: `${tokenSize}px`,
          height: `${tokenSize}px`,
          borderColor: isViewingFrom ? '#4a6a8a' : (isMyTurn ? '#FFD700' : isTargeted ? '#9a5e15' : characterData.tokenSettings.borderColor),
          zIndex: isDragging ? 1000 : 150, // Higher z-index to be above ObjectSystem canvas (20) and grid tiles (10)
          position: 'absolute',
          transform: `translate3d(${screenPosition.x}px, ${screenPosition.y}px, 0) translate(-50%, -50%)`,
          willChange: 'transform',
          borderRadius: '50%',
          border: `3px solid ${isViewingFrom ? '#4a6a8a' : (isMyTurn ? '#FFD700' : isSelectedForCombat ? '#506e30' : isTargeted ? '#9a5e15' : characterData.tokenSettings.borderColor)}`,
          overflow: 'visible',
          boxShadow: isViewingFrom
            ? '0 0 25px rgba(0, 191, 255,1), 0 0 15px rgba(0, 191, 255, 0.8), 0 2px 8px rgba(0, 0, 0, 0.3)'
            : isMyTurn
              ? '0 0 20px rgba(255, 215, 0, 0.8), 0 2px 8px rgba(0, 0, 0, 0.3)'
              : isSelectedForCombat
                ? '0 0 15px rgba(0, 255, 0, 0.6), 0 2px 8px rgba(0, 0, 0, 0.3)'
                : isTargeted
                  ? '0 0 15px rgba(255, 152, 0, 0.6), 0 2px 8px rgba(0, 0, 0, 0.3)'
                  : '0 2px 8px rgba(0, 0, 0, 0.3)',
          backgroundColor: 'rgba(0, 0, 0, 0.1)',
          cursor: isSelectionMode ? 'pointer' : (isInCombat && !isMyTurn) ? 'not-allowed' : isDragging ? 'grabbing' : 'grab',
          pointerEvents: 'all', // Ensure it can receive mouse events
          userSelect: 'none',
          touchAction: 'none'
        }}
        onContextMenu={handleContextMenu}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        onMouseDown={handleMouseDown}
        onPointerDown={(e) => {
          lastPointerTypeRef.current = e.pointerType || 'mouse';
          longPressHandlers.onPointerDown(e);
          if (e.pointerType === 'touch') {
            handleMouseDown(e);
          }
        }}
        onPointerMove={longPressHandlers.onPointerMove}
        onPointerUp={longPressHandlers.onPointerUp}
        onPointerCancel={longPressHandlers.onPointerCancel}
        onClick={handleTokenClick}
      >
        {/* Condition rings with text - staggered outward for multiple conditions */}
        {conditionEffects.map((effect, index) => {
          const pathId = `${tokenId}-${effect.key}-ring-path`;
          const label = (effect.label || effect.key || '').toString().toUpperCase();
          const separator = ' \u2022 ';

          // Calculate ring radius - each subsequent ring is pushed outward
          // Base radius starts at 52 (in a 140x140 viewBox), increment by 14 per ring
          const baseRadius = 52;
          const radiusIncrement = 14;
          const radius = baseRadius + (index * radiusIncrement);
          const startY = 70 - radius; // Center is at 70,70

          // Calculate circumference and how many times to repeat text
          // Circumference = 2 * PI * radius
          const circumference = 2 * Math.PI * radius;
          // Estimate text width per repetition (label + separator)
          // Each char is roughly 6px with letter-spacing at font-size 10px
          const labelWithSep = label + separator;
          const estCharWidth = 6;
          const estTextWidth = labelWithSep.length * estCharWidth;
          // Calculate exact fit - use floor to avoid overlap, minimum 3 repetitions
          const repeatCount = Math.max(3, Math.floor(circumference / estTextWidth));
          const wrappedText = Array(repeatCount).fill(labelWithSep).join('');

          // Animation delay for visual variety (stagger rotation start)
          const animationDelay = index * -5; // seconds offset

          // Calculate percentage-based sizing so rings scale with token zoom
          // Base extension is 30% beyond token, each ring adds 20% more
          const baseExtension = 30 + (index * 20);

          return (
            <div
              className={`condition-ring-wrapper condition-ring-${index}`}
              key={effect.key}
              style={{
                '--ring-index': index,
                '--ring-radius': radius,
                animationDelay: `${animationDelay}s`,
                // Use percentage-based sizing so rings scale with token
                inset: `${-baseExtension}%`,
                width: `${100 + (baseExtension * 2)}%`,
                height: `${100 + (baseExtension * 2)}%`,
              }}
            >
              <svg
                className={`condition-ring-svg ${effect.key}`}
                viewBox="0 0 140 140"
                aria-hidden="true"
                style={{ overflow: 'visible' }}
              >
                <defs>
                  <path
                    id={pathId}
                    d={`M70,${startY} a${radius},${radius} 0 1,1 0,${radius * 2} a${radius},${radius} 0 1,1 0,-${radius * 2}`}
                  />
                </defs>
                <text
                  className={`condition-ring-text condition-text-${effect.key}`}
                  textLength={circumference * 0.98}
                  lengthAdjust="spacing"
                >
                  <textPath href={`#${pathId}`} startOffset="0%">
                    {wrappedText}
                  </textPath>
                </text>
              </svg>
            </div>
          );
        })}

        {/* Portrait background (iconBackgroundImage/color): mirrors the PartyHUD/Lore styling */}
        <div
          className="token-portrait-bg"
          style={{
            position: 'absolute',
            inset: 0,
            zIndex: 0,
            borderRadius: '50%',
            backgroundColor: characterData.lore?.iconBackgroundColor || 'transparent',
            backgroundImage: characterData.lore?.iconBackgroundImage
              ? `url(/assets/backgrounds/${encodeURIComponent(characterData.lore.iconBackgroundImage)})`
              : 'none',
            backgroundSize: characterData.lore?.iconBackgroundImage
              ? `${(characterData.lore.iconBackgroundScale || 2.5) * 100}%`
              : 'cover',
            backgroundPosition: characterData.lore?.iconBackgroundImage
              ? `calc(50% + ${characterData.lore.iconBackgroundOffsetX || 0}px) calc(50% + ${characterData.lore.iconBackgroundOffsetY || 0}px)`
              : 'center',
            backgroundRepeat: 'no-repeat'
          }}
        ></div>

        {/* Character Image with Transformations */}
        <div
          className="token-icon"
          style={{
            position: 'relative',
            zIndex: 1,
            backgroundImage: getCharacterImage() ? `url(${getCharacterImage()})` : 'none',
            width: '100%',
            height: '100%',
            backgroundSize: characterData.lore?.imageTransformations
              ? `${(characterData.lore.imageTransformations.scale || 1) * 120}%`
              : 'cover',
            backgroundPosition: characterData.lore?.imageTransformations
              ? `${50 + (characterData.lore.imageTransformations.positionX || 0) / 2}% ${50 - (characterData.lore.imageTransformations.positionY || 0) / 2}%`
              : 'center center',
            backgroundRepeat: 'no-repeat',
            borderRadius: '50%',
            transform: characterData.lore?.imageTransformations
              ? `rotate(${characterData.lore.imageTransformations.rotation || 0}deg)`
              : 'none'
          }}
        ></div>

        {/* Health bar removed - health is visible in HUD and hover tooltip */}

        {/* Character Name Label */}
        <div className="token-name-label" style={{
          position: 'absolute',
          bottom: '-20px',
          left: '50%',
          transform: 'translateX(-50%)',
          fontSize: '10px',
          color: '#fff',
          textShadow: '1px 1px 2px rgba(0, 0, 0, 0.8)',
          whiteSpace: 'nowrap',
          pointerEvents: 'none'
        }}>
          {characterData.name}
        </div>
      </div>

      {/* Advanced Context Menu */}
      {showContextMenu && (() => {
        // Build context menu items
        const menuItems = [];

        // Token Actions submenu
        const tokenActionsSubmenu = [
          {
            icon: <i className="fas fa-search"></i>,
            label: 'Inspect',
            onClick: (e) => {
              e.preventDefault();
              e.stopPropagation();
              setShowContextMenu(false);
              handleInspectCharacter();
            }
          },
          {
            icon: <i className="fas fa-crosshairs"></i>,
            label: isTargeted ? 'Clear Target' : 'Target',
            onClick: (e) => {
              e.preventDefault();
              e.stopPropagation();
              setShowContextMenu(false);
              handleTarget();
            },
            className: isTargeted ? 'active' : ''
          }
        ];

        // Add GM/Owner actions to Token Actions
        if (isGMMode) {
          tokenActionsSubmenu.push(
            {
              icon: <i className="fas fa-copy"></i>,
              label: 'Duplicate',
              onClick: (e) => {
                e.preventDefault();
                e.stopPropagation();
                setShowContextMenu(false);
                handleDuplicateToken();
              }
            },
            {
              icon: <i className="fas fa-eye"></i>,
              label: isViewingFrom ? 'Deselect View from Token' : 'View from Token',
              onClick: (e) => {
                e.preventDefault();
                e.stopPropagation();
                setShowContextMenu(false);
                const levelEditorStore = useLevelEditorStore.getState();
                if (isViewingFrom) {
                  // Deselect view from token
                  levelEditorStore.setViewingFromToken(null);
                } else if (position) {
                  // Enable dynamic fog if not already enabled
                  const { dynamicFogEnabled, setDynamicFogEnabled } = levelEditorStore;
                  if (!dynamicFogEnabled) {
                    setDynamicFogEnabled(true);
                  }
                  // Reset the disabled flag since player is explicitly enabling it
                  levelEditorStore.playerViewFromTokenDisabled = false;
                  // Set this token as the viewing token (restricts fog reveal to token's vision)
                  const tokenData = {
                    type: 'character',
                    id: tokenId,
                    characterId: tokenId,
                    position: position
                  };
                  levelEditorStore.setViewingFromToken(tokenData);
                  // Center camera on token initially (but don't lock it)
                  setCameraPosition(position.x, position.y);
                }
              },
              className: isViewingFrom ? 'active' : ''
            },
            {
              icon: <i className="fas fa-trash"></i>,
              label: 'Remove',
              onClick: (e) => {
                e.preventDefault();
                e.stopPropagation();
                setShowContextMenu(false);
                handleRemoveToken();
              },
              className: 'danger'
            }
          );
        }

        // Allow players to remove their own character token
        if (!isGMMode && isSelf) {
          tokenActionsSubmenu.push({
            icon: <i className="fas fa-trash"></i>,
            label: 'Remove Token',
            onClick: (e) => {
              e.preventDefault();
              e.stopPropagation();
              setShowContextMenu(false);
              handleRemoveToken();
            },
            className: 'danger'
          });
        }

        menuItems.push({
          icon: <i className="fas fa-cog"></i>,
          label: 'Token Actions',
          submenu: tokenActionsSubmenu
        });

        // Health, Mana, and Status submenus - GM can modify any token, players can modify their own
        if (isGMMode || isSelf) {
          // Health submenu
          menuItems.push({
            icon: <i className="fas fa-heart"></i>,
            label: 'Health',
            submenu: [
              {
                icon: <i className="fas fa-minus-circle"></i>,
                label: 'Damage (5)',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  setShowContextMenu(false);
                  handleDamageToken(5);
                }
              },
              {
                icon: <i className="fas fa-minus-circle"></i>,
                label: 'Damage (10)',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  setShowContextMenu(false);
                  handleDamageToken(10);
                }
              },
              {
                icon: <i className="fas fa-edit"></i>,
                label: 'Custom Damage',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  setShowContextMenu(false);
                  handleCustomAmount('damage');
                }
              },
              { type: 'separator' },
              {
                icon: <i className="fas fa-plus-circle"></i>,
                label: 'Heal (5)',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  setShowContextMenu(false);
                  handleHealToken(5);
                }
              },
              {
                icon: <i className="fas fa-plus-circle"></i>,
                label: 'Heal (10)',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  setShowContextMenu(false);
                  handleHealToken(10);
                }
              },
              {
                icon: <i className="fas fa-edit"></i>,
                label: 'Custom Heal',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  setShowContextMenu(false);
                  handleCustomAmount('heal');
                }
              },
              { type: 'separator' },
              {
                icon: <i className="fas fa-heart"></i>,
                label: 'Full Heal',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  setShowContextMenu(false);
                  handleFullHeal();
                },
                className: 'heal'
              },
              {
                icon: <i className="fas fa-skull"></i>,
                label: 'Kill',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  setShowContextMenu(false);
                  handleKill();
                },
                className: 'danger'
              }
            ]
          });

          // Mana submenu
          menuItems.push({
            icon: <i className="fas fa-magic"></i>,
            label: 'Mana',
            submenu: [
              {
                icon: <i className="fas fa-minus-circle"></i>,
                label: 'Drain (5)',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  setShowContextMenu(false);
                  handleManaDamage(5);
                }
              },
              {
                icon: <i className="fas fa-minus-circle"></i>,
                label: 'Drain (10)',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  setShowContextMenu(false);
                  handleManaDamage(10);
                }
              },
              {
                icon: <i className="fas fa-edit"></i>,
                label: 'Custom Drain',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  setShowContextMenu(false);
                  handleCustomAmount('mana-damage');
                }
              },
              { type: 'separator' },
              {
                icon: <i className="fas fa-plus-circle"></i>,
                label: 'Restore (5)',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  setShowContextMenu(false);
                  handleManaHeal(5);
                }
              },
              {
                icon: <i className="fas fa-plus-circle"></i>,
                label: 'Restore (10)',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  setShowContextMenu(false);
                  handleManaHeal(10);
                }
              },
              {
                icon: <i className="fas fa-edit"></i>,
                label: 'Custom Restore',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  setShowContextMenu(false);
                  handleCustomAmount('mana-heal');
                }
              },
              { type: 'separator' },
              {
                icon: <i className="fas fa-battery-empty"></i>,
                label: 'Drain All',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  setShowContextMenu(false);
                  handleDrainMana();
                },
                className: 'danger'
              }
            ]
          });

          // Action Points submenu
