          <div ref={tooltipRef} style={{
            position: 'fixed',
            left: adjustedPosition.x,
            top: adjustedPosition.y,
            zIndex: 9999,
            pointerEvents: 'none'
          }}>
            <ItemTooltip item={item} />
          </div>
        </TooltipPortal>
      )}
    </>
  );
};

