import React from 'react';
import ReactDOM from 'react-dom';

const HexbreakerChargesResourceBar = ({
  hexbreakerState,
  setHexbreakerState,
  uiState,
  setUiState,
  finalClassResource,
  finalConfig,
  character,
  isOwner,
  onClassResourceUpdate,
