                        const iconBgScale = member.character?.lore?.iconBackgroundScale || 2.5;
                        const iconBgOffsetX = member.character?.lore?.iconBackgroundOffsetX || 0;
                        const iconBgOffsetY = member.character?.lore?.iconBackgroundOffsetY || 0;

