                            onStop={(e, data) => {
                                // Final position update on drag end
                                setMemberPosition(member.id, { x: data.x, y: data.y });
                            }}
                            enableUserSelectHack={true} // Enable user select hack to prevent text selection during drag
                            disabled={false} // Ensure dragging is always enabled
                            scale={1} // Fixed scale to prevent transform calculations
                            cancel=".resource-bar, .buff-icon, .debuff-icon, button, input, select, textarea"
                        >
                            <div ref={memberNodeRef} className={`party-frame-${member.id}`} style={{ display: 'flex', flexDirection: 'column' }}>
                                <PartyMemberFrame
                                    member={member}
                                    isCurrentPlayer={
                                        isSelfId(member.userId, member.userId, myIds) ||
                                        isSelfId(member.id, member.userId, myIds) ||
                                        isSelfId(member.socketId, member.userId, myIds)
                                    }
                                    leaderId={leaderId}
                                    onContextMenu={handleContextMenu}
                                    onResourceAdjust={handleResourceAdjust}
                                    onBuffContextMenu={handleBuffContextMenu}
                                    onClassResourceUpdate={handleClassResourceUpdate}
                                    onRegisterRefs={handleRegisterRefs}
                                />
                            </div>
                        </Draggable>
                    );
                })}
            </div>

            {/* Context Menu - Outside draggable containers */}
            {showContextMenu && (() => {
                const menuItems = [];

                const isSelf = isSelfId(contextMenuMember?.id, contextMenuMember?.userId, myIds);
                const leaderId = usePartyStore.getState().leaderId;
                const isLeader = contextMenuMember?.id === leaderId || contextMenuMember?.userId === leaderId;
                const currentUserIsLeader = isSelfId(leaderId, undefined, myIds);
                const leaderInSession = isLeader && isInMultiplayer && multiplayerRoom;
                const currentUserInSession = isInMultiplayer && multiplayerRoom;

                // Party Management Options (always visible, context-dependent)
                if (isSelf && isInParty) {
                    menuItems.push({
                        icon: <i className="fas fa-sign-out-alt"></i>,
                        label: 'Leave Party',
                        onClick: () => {
                            console.log('­ƒÜ¬ Leaving party');
                            usePartyStore.getState().leaveParty();
                            setShowContextMenu(false);
                        },
                        className: 'danger'
                    });
                    menuItems.push({ type: 'separator' });
                } else if (!isSelf) {
                    // Join Session option (when leader is in session)
                    if (leaderInSession) {
                        menuItems.push({
                            icon: <i className="fas fa-door-open"></i>,
                            label: 'Join Session',
                            onClick: () => {
                                console.log('­ƒÄ» Requesting to join session:', multiplayerRoom.id);
                                usePresenceStore.getState().requestToJoinSession(
                                    leaderId,
                                    multiplayerRoom.id,
                                    myId,
                                    currentPlayerData?.name || 'Player'
                                );
                                setShowContextMenu(false);
                            },
                            className: 'heal'
                        });
                    }

                    // Invite to Session option (when current user is leader in session)
                    if (currentUserIsLeader && currentUserInSession && !isLeader) {
                        menuItems.push({
                            icon: <i className="fas fa-user-plus"></i>,
                            label: 'Invite to Session',
                            onClick: () => {
                                console.log('­ƒô¿ Inviting member to session:', contextMenuMember?.id);
                                usePresenceStore.getState().sendSessionInvitation(
                                    contextMenuMember?.userId || contextMenuMember?.id,
                                    multiplayerRoom.id
                                );
                                setShowContextMenu(false);
                            },
                            className: 'heal'
                        });
                    }

                    // Whisper option
                    menuItems.push({
                        icon: <i className="fas fa-comment"></i>,
                        label: 'Whisper',
                        onClick: () => {
                            console.log('­ƒÆ¼ Opening whisper for:', contextMenuMember?.name);
                            usePresenceStore.getState().openWhisperTab({
                                userId: contextMenuMember?.userId || contextMenuMember?.id,
                                name: contextMenuMember?.name,
                                characterName: contextMenuMember?.name
                            });
                            setShowContextMenu(false);
                        }
                    });

                    menuItems.push({ type: 'separator' });
                }

                // GM/Player View Toggle - Add at the top
                menuItems.push({
                    icon: <i className={`fas ${isGMMode ? 'fa-crown' : 'fa-user'}`}></i>,
                    label: isGMMode ? 'Switch to Player View' : 'Switch to GM View',
                    onClick: handleToggleGMView,
                    disabled: isInMultiplayer,
                    title: isInMultiplayer
                        ? 'GM mode determined by room creator status'
                        : (isGMMode ? 'Switch to Player View (fog blocks visibility)' : 'Switch to GM View (see through fog)')
                });

                menuItems.push({ type: 'separator' });

                // Target/Clear Target
                menuItems.push({
                    icon: <i className="fas fa-crosshairs"></i>,
                    label: currentTarget?.id === contextMenuMember?.id ? 'Clear Target' : 'Target',
                    onClick: handleTargetMember
                });

                // Inspect
                menuItems.push({
                    icon: <i className="fas fa-search"></i>,
                    label: 'Inspect',
                    onClick: handleInspectMember
                });

                // Only show create token for current player
                if (contextMenuMember?.name === currentPlayerData.name || isSelfId(contextMenuMember?.id, contextMenuMember?.userId, myIds)) {

                    menuItems.push({
                        icon: <i className="fas fa-plus-circle"></i>,
                        label: 'Create Token',
                        onClick: handleCreateToken
                    });
                }

                // Summon Token Bar - show only for classes/races that have summonable tokens
                {
                    const charClass = contextMenuMember?.character?.class || contextMenuMember?.characterClass;
                    const charRace = contextMenuMember?.character?.race || contextMenuMember?.characterRace;
                    const charSubrace = contextMenuMember?.character?.subrace;
                    const charLevel = contextMenuMember?.character?.level || contextMenuMember?.characterLevel || 1;
                    if (charClass || charRace) {
                        const { getTokensForClass, getTokensForRace, resolveClassId } = require('../../data/summonableTokens');
                        const resolvedClassId = resolveClassId(charClass);
                        const classTokens = resolvedClassId ? getTokensForClass(charClass) : [];
                        const raceTokens = charRace ? getTokensForRace(charRace, charSubrace) : [];
                        const hasTokens = classTokens.length > 0 || raceTokens.length > 0;
                        if (hasTokens) {
                            menuItems.push({
                                icon: <i className="fas fa-dragon" style={{ color: '#a78bfa' }}></i>,
                                label: 'Summon Tokens',
                                onClick: () => {
                                    setSummonTokenBarCharacter({
                                        ...contextMenuMember,
                                        characterClass: charClass,
                                        race: charRace,
                                        subrace: charSubrace || charRace,
                                        level: charLevel,
                                        name: contextMenuMember?.name,
                                    });
                                    setShowSummonTokenBar(true);
                                    setShowContextMenu(false);
                                },
                                className: 'summon-token-bar-item',
                            });
                        }
                    }
                }

                // Health adjustment options - show for GM on anyone, or for self on own character
                if (isGMMode || isSelf) {
                    menuItems.push({ type: 'separator' });

                    // Full Restore All button (restores HP, mana, and AP)
                    menuItems.push({
                        icon: <i className="fas fa-redo"></i>,
                        label: 'Full Restore All',
                        onClick: handleFullRestoreAll,
                        className: 'heal'
                    });

                    // Full Drain All button (drains HP, mana, and AP including temporary)
                    menuItems.push({
                        icon: <i className="fas fa-battery-empty"></i>,
                        label: 'Full Drain All',
                        onClick: handleFullDrainAll,
                        className: 'danger'
                    });

                    menuItems.push({ type: 'separator' });

                    // Health submenu
                    menuItems.push({
                        icon: <i className="fas fa-heart"></i>,
                        label: 'Health',
                        submenu: [
                            {
                                icon: <i className="fas fa-minus-circle"></i>,
                                label: 'Damage (5)',
                                onClick: () => handleResourceAdjust(contextMenuMember.id, 'health', -5)
                            },
                            {
                                icon: <i className="fas fa-minus-circle"></i>,
                                label: 'Damage (10)',
                                onClick: () => handleResourceAdjust(contextMenuMember.id, 'health', -10)
                            },
                            {
                                icon: <i className="fas fa-edit"></i>,
                                label: 'Custom Damage',
                                onClick: () => handleCustomAmount('damage')
                            },
                            { type: 'separator' },
                            {
                                icon: <i className="fas fa-plus-circle"></i>,
                                label: 'Heal (5)',
                                onClick: () => handleResourceAdjust(contextMenuMember.id, 'health', 5)
                            },
                            {
                                icon: <i className="fas fa-plus-circle"></i>,
                                label: 'Heal (10)',
                                onClick: () => handleResourceAdjust(contextMenuMember.id, 'health', 10)
                            },
                            {
                                icon: <i className="fas fa-edit"></i>,
                                label: 'Custom Heal',
                                onClick: () => handleCustomAmount('heal')
                            },
                            { type: 'separator' },
                            {
                                icon: <i className="fas fa-heart"></i>,
                                label: 'Full Heal',
                                onClick: handleFullHeal,
                                className: 'heal'
                            },
                            {
                                icon: <i className="fas fa-skull"></i>,
                                label: 'Kill',
                                onClick: handleKill,
                                className: 'danger'
                            }
                        ]
                    });

                    // Mana submenu
                    menuItems.push({
                        icon: <i className="fas fa-magic"></i>,
                        label: 'Mana',
                        submenu: [
                            {
                                icon: <i className="fas fa-minus-circle"></i>,
                                label: 'Drain (5)',
                                onClick: () => handleResourceAdjust(contextMenuMember.id, 'mana', -5)
                            },
                            {
                                icon: <i className="fas fa-minus-circle"></i>,
                                label: 'Drain (10)',
                                onClick: () => handleResourceAdjust(contextMenuMember.id, 'mana', -10)
                            },
                            {
                                icon: <i className="fas fa-edit"></i>,
                                label: 'Custom Drain',
                                onClick: () => handleCustomAmount('mana-damage')
                            },
                            { type: 'separator' },
                            {
                                icon: <i className="fas fa-plus-circle"></i>,
                                label: 'Restore (5)',
                                onClick: () => handleResourceAdjust(contextMenuMember.id, 'mana', 5)
                            },
                            {
                                icon: <i className="fas fa-plus-circle"></i>,
                                label: 'Restore (10)',
                                onClick: () => handleResourceAdjust(contextMenuMember.id, 'mana', 10)
                            },
                            {
                                icon: <i className="fas fa-edit"></i>,
                                label: 'Custom Restore',
                                onClick: () => handleCustomAmount('mana-heal')
                            },
                            { type: 'separator' },
                            {
                                icon: <i className="fas fa-magic"></i>,
                                label: 'Full Restore',
                                onClick: handleFullRestoreMana,
                                className: 'heal'
                            },
                            {
                                icon: <i className="fas fa-battery-empty"></i>,
                                label: 'Drain All',
                                onClick: handleDrainMana,
                                className: 'danger'
                            }
                        ]
                    });

                    // Action Points submenu
                    menuItems.push({
                        icon: <i className="fas fa-bolt"></i>,
                        label: 'Action Points',
                        submenu: [
                            {
                                icon: <i className="fas fa-minus-circle"></i>,
                                label: 'Spend (1)',
                                onClick: () => handleResourceAdjust(contextMenuMember.id, 'actionPoints', -1)
                            },
                            {
                                icon: <i className="fas fa-minus-circle"></i>,
                                label: 'Spend (2)',
                                onClick: () => handleResourceAdjust(contextMenuMember.id, 'actionPoints', -2)
                            },
                            {
                                icon: <i className="fas fa-minus-circle"></i>,
                                label: 'Spend (3)',
                                onClick: () => handleResourceAdjust(contextMenuMember.id, 'actionPoints', -3)
                            },
                            {
                                icon: <i className="fas fa-edit"></i>,
                                label: 'Custom Spend',
                                onClick: () => handleCustomAmount('ap-spend')
                            },
                            { type: 'separator' },
                            {
                                icon: <i className="fas fa-plus-circle"></i>,
                                label: 'Restore (1)',
                                onClick: () => handleResourceAdjust(contextMenuMember.id, 'actionPoints', 1)
                            },
                            {
                                icon: <i className="fas fa-plus-circle"></i>,
                                label: 'Restore (2)',
                                onClick: () => handleResourceAdjust(contextMenuMember.id, 'actionPoints', 2)
                            },
                            {
                                icon: <i className="fas fa-plus-circle"></i>,
                                label: 'Restore (3)',
                                onClick: () => handleResourceAdjust(contextMenuMember.id, 'actionPoints', 3)
                            },
                            {
                                icon: <i className="fas fa-edit"></i>,
                                label: 'Custom Restore',
                                onClick: () => handleCustomAmount('ap-restore')
                            },
                            { type: 'separator' },
                            {
                                icon: <i className="fas fa-bolt"></i>,
                                label: 'Full Restore',
                                onClick: () => {
                                    if (!contextMenuMember) return;
                                    const memberId = contextMenuMember.id;
                                    if (memberId === 'current-player') {
                                        const maxAp = currentPlayerData.actionPoints?.max || 0;
                                        const currentAp = currentPlayerData.actionPoints?.current || 0;
                                        handleResourceAdjust(memberId, 'actionPoints', maxAp - currentAp);
                                    } else {
                                        const member = findMemberById(memberId);
                                        if (member) {
                                            const maxAp = member.character?.actionPoints?.max || 0;
                                            const currentAp = member.character?.actionPoints?.current || 0;
                                            handleResourceAdjust(memberId, 'actionPoints', maxAp - currentAp);
                                        }
                                    }
                                    setShowContextMenu(false);
                                },
                                className: 'heal'
                            },
                            {
                                icon: <i className="fas fa-battery-empty"></i>,
                                label: 'Drain All',
                                onClick: handleDrainAP,
                                className: 'danger'
                            }
                        ]
                    });
                }

                // GM-only options: Experience and Level adjustments
                if (isGMMode) {
                    menuItems.push({ type: 'separator' });

                    // Experience submenu
                    menuItems.push({
                        icon: <i className="fas fa-star"></i>,
                        label: 'Experience',
                        submenu: [
                            {
                                icon: <i className="fas fa-plus-circle"></i>,
                                label: 'Award 50 XP',
                                onClick: () => handleAwardXP(contextMenuMember.id, 50)
                            },
                            {
                                icon: <i className="fas fa-plus-circle"></i>,
                                label: 'Award 100 XP',
                                onClick: () => handleAwardXP(contextMenuMember.id, 100)
                            },
                            {
                                icon: <i className="fas fa-plus-circle"></i>,
                                label: 'Award 250 XP',
                                onClick: () => handleAwardXP(contextMenuMember.id, 250)
                            },
                            {
                                icon: <i className="fas fa-plus-circle"></i>,
                                label: 'Award 500 XP',
                                onClick: () => handleAwardXP(contextMenuMember.id, 500)
                            },
                            { type: 'separator' },
                            {
                                icon: <i className="fas fa-minus-circle"></i>,
                                label: 'Remove 50 XP',
                                onClick: () => handleAwardXP(contextMenuMember.id, -50)
                            },
                            {
                                icon: <i className="fas fa-minus-circle"></i>,
                                label: 'Remove 100 XP',
                                onClick: () => handleAwardXP(contextMenuMember.id, -100)
                            },
                            {
                                icon: <i className="fas fa-minus-circle"></i>,
                                label: 'Remove 250 XP',
                                onClick: () => handleAwardXP(contextMenuMember.id, -250)
                            },
                            {
                                icon: <i className="fas fa-minus-circle"></i>,
                                label: 'Remove 500 XP',
                                onClick: () => handleAwardXP(contextMenuMember.id, -500)
                            },
                            { type: 'separator' },
                            {
                                icon: <i className="fas fa-edit"></i>,
                                label: 'Custom Amount',
                                onClick: () => handleCustomAmount('xp')
                            }
                        ]
                    });

                    // Level adjustment submenu
                    menuItems.push({
                        icon: <i className="fas fa-level-up-alt"></i>,
                        label: 'Level',
                        submenu: [
                            {
                                icon: <i className="fas fa-arrow-up"></i>,
                                label: 'Add 1 Level',
                                onClick: () => handleLevelAdjust(contextMenuMember.id, 1)
                            },
                            {
                                icon: <i className="fas fa-arrow-up"></i>,
                                label: 'Add 5 Levels',
                                onClick: () => handleLevelAdjust(contextMenuMember.id, 5)
                            },
                            { type: 'separator' },
                            {
                                icon: <i className="fas fa-arrow-down"></i>,
                                label: 'Remove 1 Level',
                                onClick: () => handleLevelAdjust(contextMenuMember.id, -1)
                            },
                            {
                                icon: <i className="fas fa-arrow-down"></i>,
                                label: 'Remove 5 Levels',
                                onClick: () => handleLevelAdjust(contextMenuMember.id, -5)
                            }
                        ]
                    });
                }

                // Leadership transfer - show options if current player is actual GM
                const currentMember = partyMembers.find(m => isSelfId(m.id, m.userId, myIds));

                const isActualGM = currentMember?.isGM;


                if (isActualGM) {
                    menuItems.push({ type: 'separator' });

                    if (isSelfId(contextMenuMember?.id, contextMenuMember?.userId, myIds)) {
                        // Current player (GM) context menu
                        if (!isSelfId(leaderId, undefined, myIds)) {
                            menuItems.push({
                                icon: <i className="fas fa-crown"></i>,
                                label: 'Regain Leadership',
                                onClick: handleRegainLeadership,
                                className: 'leadership'
                            });
                        }
                    } else if (leaderId !== contextMenuMember?.id) {
                        // Other player context menu
                        menuItems.push({
                            icon: <i className="fas fa-crown"></i>,
                            label: 'Make Leader',
                            onClick: handleTransferLeadership,
                            className: 'leadership'
                        });
                    }
                }

                return (
                    <div
                        ref={contextMenuRef}
                        className="context-menu-container"
                        style={{
                            position: 'fixed',
                            left: contextMenuPosition.x,
                            top: contextMenuPosition.y,
                            zIndex: 10000,
                            backgroundColor: '#f0e6d2',
                            border: '2px solid #a08c70',
                            borderRadius: '8px',
                            boxShadow: '0 4px 12px rgba(0, 0, 0, 0.3)',
                            fontFamily: "'Bookman Old Style', 'Garamond', serif",
                            color: '#7a3b2e',
                            padding: '8px',
                            display: 'flex',
                            gap: '0',
                            minWidth: hoveredMenuItem !== null && menuItems[hoveredMenuItem]?.submenu ? '280px' : '160px'
                        }}
                        onMouseLeave={() => {
                            // Close menu when mouse leaves entire container
                            setHoveredMenuItem(null);
                        }}
                        onClick={(e) => e.stopPropagation()}
                    >
                        {/* Main menu items */}
                        <div style={{ display: 'flex', flexDirection: 'column', flex: 1 }}>
                            {menuItems.map((item, index) => (
                                <React.Fragment key={index}>
                                    {item.type === 'separator' ? (
                                        <hr style={{
                                            border: 'none',
                                            borderTop: '1px solid #a08c70',
                                            margin: '4px 0',
                                            width: '100%'
                                        }} />
                                    ) : (
                                        <button
                                            className="context-menu-button"
                                            style={{
                                                pointerEvents: 'auto',
                                                display: 'flex',
                                                alignItems: 'center',
                                                gap: '8px',
                                                padding: '6px 12px',
                                                border: '1px solid #a08c70',
                                                borderRadius: '4px',
                                                backgroundColor: hoveredMenuItem === index ? '#e8dcc0' : (item.className === 'danger' ? '#ffebee' : '#d4c4a8'),
                                                color: '#7a3b2e',
                                                cursor: 'pointer',
                                                fontSize: '12px',
                                                fontFamily: "'Bookman Old Style', 'Garamond', serif",
                                                width: '100%',
                                                textAlign: 'left',
                                                margin: '2px 0',
                                                minWidth: '140px'
                                            }}
                                            onMouseEnter={() => {
                                                setHoveredMenuItem(index);
                                            }}
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                if (item.submenu) {
                                                    // Don't close on submenu items, just keep submenu open
                                                    return;
                                                }
                                                if (item.onClick) {
                                                    item.onClick(e);
                                                }
                                            }}
                                            disabled={item.disabled}
                                            title={item.title}
                                        >
                                            {item.icon}
                                            <span>{item.label}</span>
                                            {item.submenu && <i className="fas fa-chevron-right" style={{ marginLeft: 'auto', fontSize: '10px' }} />}
                                        </button>
                                    )}
                                </React.Fragment>
                            ))}
                        </div>

                        {/* Submenu - always rendered but only visible when hovering */}
                        {menuItems[hoveredMenuItem]?.submenu && (
                            <div
                                style={{
                                    display: 'flex',
                                    flexDirection: 'column',
                                    backgroundColor: '#f0e6d2',
                                    border: '1px solid #a08c70',
                                    borderLeft: 'none',
                                    borderRadius: '0 4px 4px 0',
                                    padding: '8px 4px',
                                    minWidth: '130px',
                                    marginLeft: '4px',
                                    opacity: hoveredMenuItem !== null ? 1 : 0,
                                    visibility: hoveredMenuItem !== null ? 'visible' : 'hidden',
                                    transition: 'opacity 0.1s ease, visibility 0.1s ease'
                                }}
                            >
                                {menuItems[hoveredMenuItem].submenu.map((subItem, subIndex) => (
                                    <React.Fragment key={subIndex}>
                                        {subItem.type === 'separator' ? (
                                            <hr style={{
                                                border: 'none',
                                                borderTop: '1px solid #a08c70',
                                                margin: '2px 0',
                                                width: '100%'
                                            }} />
                                        ) : (
                                            <button
                                                className="context-menu-button"
                                                style={{
                                                    pointerEvents: 'auto',
                                                    display: 'flex',
                                                    alignItems: 'center',
                                                    gap: '6px',
                                                    padding: '4px 8px',
                                                    border: '1px solid #a08c70',
                                                    borderRadius: '3px',
                                                    backgroundColor: subItem.className === 'danger' ? '#ffebee' : '#d4c4a8',
                                                    color: '#7a3b2e',
                                                    cursor: 'pointer',
                                                    fontSize: '11px',
                                                    fontFamily: "'Bookman Old Style', 'Garamond', serif",
                                                    width: '100%',
                                                    textAlign: 'left',
                                                    margin: '1px 0'
                                                }}
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    if (subItem.onClick) {
                                                        subItem.onClick(e);
                                                    }
                                                }}
                                            >
                                                {subItem.icon}
                                                <span>{subItem.label}</span>
                                            </button>
                                        )}
                                    </React.Fragment>
                                ))}
                            </div>
                        )}
                    </div>
                );
            })()}

            {/* Buff/Debuff Context Menu - Rendered via Portal to avoid transform issues */}
            {showBuffContextMenu && createPortal(
                <>
                    <div
                        className="context-menu-overlay"
                        onClick={() => {
                            setShowBuffContextMenu(false);
                            setContextMenuBuff(null);
                        }}
                    />
                    <div
                        className={`unified-context-menu small buff-context-menu ${contextMenuBuff?.type === 'debuff' ? 'debuff-context-menu' : ''}`}
                        style={{
                            position: 'fixed',
                            left: buffContextMenuPosition.x,
                            top: buffContextMenuPosition.y,
                            zIndex: 10000
                        }}
                        onClick={(e) => e.stopPropagation()}
                    >
                        <div className="context-menu-main">
                            <div
                                className="context-menu-item"
                                onClick={(e) => {
                                    e.stopPropagation();
                                    handleAdjustBuffDuration();
                                }}
                            >
                                <i className="fas fa-clock" style={{ marginRight: '8px' }}></i>
                                Adjust Duration
                            </div>
                            <div
                                className="context-menu-item danger"
                                onClick={(e) => {
                                    e.stopPropagation();
                                    handleDismissBuff();
                                }}
                            >
                                <i className="fas fa-times" style={{ marginRight: '8px' }}></i>
                                Dismiss {contextMenuBuff?.name || (contextMenuBuff?.type === 'debuff' ? 'Debuff' : 'Buff')}
                            </div>
                        </div>
                    </div>
                </>,
                document.body
            )}

            {/* Duration Modal */}
            {showDurationModal && durationModalCondition && (
                <ConditionDurationModal
                    show={showDurationModal}
                    onClose={() => {
                        setShowDurationModal(false);
                        setDurationModalCondition(null);
                    }}
                    onApply={handleDurationModalApplyMain}
                    conditionName={durationModalCondition.name || durationModalCondition.title || ''}
                    initialDurationType={durationModalCondition.initialDurationType || 'minutes'}
                    initialDurationValue={durationModalCondition.initialDurationValue || 10}
                />
            )}

            {/* Custom Amount Modal */}
            {showCustomAmountModal && (
                <div
                    className="modal-overlay"
                    style={{
                        position: 'fixed',
                        top: 0,
                        left: 0,
                        right: 0,
                        bottom: 0,
                        backgroundColor: 'rgba(0, 0, 0, 0.5)',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        zIndex: 10001
                    }}
                    onClick={() => {
                        setShowCustomAmountModal(false);
                        setCustomAmountType('');
                    }}
                >
                    <div
                        className="custom-amount-modal"
                        style={{
                            backgroundColor: '#f0e6d2',
                            border: '2px solid #a08c70',
                            borderRadius: '8px',
                            padding: '20px',
                            boxShadow: '0 4px 12px rgba(0, 0, 0, 0.3)',
                            fontFamily: "'Bookman Old Style', 'Garamond', serif",
                            color: '#7a3b2e',
                            minWidth: '300px',
                            textAlign: 'center'
                        }}
                        onClick={(e) => e.stopPropagation()}
                    >
                        <h3 style={{ margin: '0 0 15px 0', fontSize: '16px' }}>
                            {customAmountType === 'damage' && 'Custom Damage Amount'}
                            {customAmountType === 'heal' && 'Custom Heal Amount'}
                            {customAmountType === 'mana-damage' && 'Custom Mana Drain Amount'}
                            {customAmountType === 'mana-heal' && 'Custom Mana Restore Amount'}
                            {customAmountType === 'ap-spend' && 'Custom Action Points Spend Amount'}
                            {customAmountType === 'ap-restore' && 'Custom Action Points Restore Amount'}
                            {customAmountType === 'xp' && 'Award Experience Points'}
                        </h3>
                        <input
                            type="number"
                            min={customAmountType === 'xp' ? undefined : "1"}
                            placeholder={customAmountType === 'xp' ? 'Enter amount (+ or -)...' : 'Enter amount...'}
                            style={{
                                width: '100%',
                                padding: '8px',
                                border: '1px solid #a08c70',
                                borderRadius: '4px',
                                fontSize: '14px',
                                marginBottom: '15px',
                                textAlign: 'center'
                            }}
                            autoFocus
                            onKeyDown={(e) => {
                                if (e.key === 'Enter') {
                                    handleCustomAmountSubmit(e.target.value);
                                } else if (e.key === 'Escape') {
                                    setShowCustomAmountModal(false);
                                    setCustomAmountType('');
                                }
                            }}
                        />
                        <div style={{ display: 'flex', gap: '10px', justifyContent: 'center' }}>
                            <button
                                style={{
                                    padding: '8px 16px',
                                    border: '1px solid #a08c70',
                                    borderRadius: '4px',
                                    backgroundColor: '#d4c4a8',
                                    color: '#7a3b2e',
                                    cursor: 'pointer',
                                    fontSize: '12px'
                                }}
                                onClick={(e) => {
                                    const input = e.target.parentElement.parentElement.querySelector('input');
                                    handleCustomAmountSubmit(input.value);
                                }}
                            >
                                Apply
                            </button>
                            <button
                                style={{
                                    padding: '8px 16px',
                                    border: '1px solid #a08c70',
                                    borderRadius: '4px',
                                    backgroundColor: '#e8dcc0',
                                    color: '#7a3b2e',
                                    cursor: 'pointer',
                                    fontSize: '12px'
                                }}
                                onClick={() => {
                                    setShowCustomAmountModal(false);
                                    setCustomAmountType('');
                                }}
                            >
                                Cancel
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Overheal Confirmation Modal */}
            {showOverhealModal && overhealData && (
                <div
                    className="modal-overlay"
                    style={{
                        position: 'fixed',
                        top: 0,
                        left: 0,
                        right: 0,
                        bottom: 0,
                        backgroundColor: 'rgba(0, 0, 0, 0.5)',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        zIndex: 10001
                    }}
                    onClick={() => {
                        setShowOverhealModal(false);
                        setOverhealData(null);
                    }}
                >
                    <div
                        className="overheal-modal"
                        style={{
                            backgroundColor: '#f0e6d2',
                            backgroundImage: 'url("https://www.transparenttextures.com/patterns/parchment.png")',
                            border: '3px solid #8b4513',
                            borderRadius: '12px',
                            padding: '24px',
                            boxShadow: '0 10px 30px rgba(0, 0, 0, 0.5), inset 0 0 60px rgba(139, 69, 19, 0.1)',
                            fontFamily: "'Cinzel', serif",
                            color: '#1a0f08',
                            minWidth: '400px',
                            maxWidth: '500px',
                            textAlign: 'center',
                            position: 'relative'
                        }}
                        onClick={(e) => e.stopPropagation()}
                    >
                        <h3 style={{ 
                            margin: '0 0 20px 0', 
                            fontSize: '22px', 
                            color: '#7a3b2e',
                            borderBottom: '2px solid #8b4513',
                            paddingBottom: '10px',
                            textTransform: 'uppercase',
                            letterSpacing: '1px'
                        }}>
                            Overheal Detected
                        </h3>
                        <p style={{ margin: '0 0 15px 0', fontSize: '16px', color: '#4a3728' }}>
                            This would restore <strong>{overhealData.adjustment}</strong> {overhealData.resourceType === 'health' ? 'HP' : overhealData.resourceType === 'mana' ? 'Mana' : 'AP'},
                            but the current value is {overhealData.currentValue}/{overhealData.maxValue}.
                            <br />
                            <strong style={{ color: '#7a3b2e' }}>{overhealData.overhealAmount}</strong> would exceed the maximum.
                        </p>
                        
                        <div style={{ 
                            display: 'flex', 
                            gap: '12px', 
                            justifyContent: 'center', 
                            marginTop: '25px',
                            paddingTop: '20px',
                            borderTop: '1px solid rgba(139, 69, 19, 0.2)'
                        }}>
                            <Button
                                variant="game-secondary"
                                onClick={() => {
                                    setShowOverhealModal(false);
                                    setOverhealData(null);
                                }}
                            >
                                Cancel
                            </Button>
                            <Button
                                variant="game-secondary"
                                onClick={() => {
                                    applyResourceAdjustment(overhealData.memberId, overhealData.resourceType, overhealData.maxValue - overhealData.currentValue, false);
                                    setShowOverhealModal(false);
                                    setOverhealData(null);
                                }}
                            >
                                Cap at Max
                            </Button>
                            <Button
                                variant="game-primary"
                                onClick={() => {
                                    applyResourceAdjustment(overhealData.memberId, overhealData.resourceType, overhealData.adjustment, true);
                                    setShowOverhealModal(false);
                                    setOverhealData(null);
                                }}
                            >
                                Add Temporary
                            </Button>
                        </div>
                    </div>
                </div>
            )}

            <SummonTokenBar
                isOpen={showSummonTokenBar}
                onClose={() => setShowSummonTokenBar(false)}
                character={summonTokenBarCharacter}
            />
        </>
    );
};

export default PartyHUD;

import React from 'react';
import ReactDOM from 'react-dom';

const PropheticVisionsResourceBar = ({
  visionsState,
  setVisionsState,
  uiState,
  setUiState,
  finalClassResource,
  finalConfig,
  character,
  isOwner,
  onClassResourceUpdate,
  size,
  context,
  visionsBarRef,
  renderStatusFlavor,
  logClassResourceChange,
}) => {
  const {
      localVisions,
      oracleSpec,
      showVisionsMenu
  } = visionsState;

  const {} = uiState;

  const setShowTooltip = (value) => setUiState(prev => ({ ...prev, showTooltip: value }));
  const setTooltipPosition = (value) => setUiState(prev => ({ ...prev, tooltipPosition: value }));
  const setTooltipPlacement = (value) => setUiState(prev => ({ ...prev, tooltipPlacement: value }));
  const setLocalVisions = (value) => setVisionsState(prev => ({ ...prev, localVisions: value }));
  const setOracleSpec = (value) => setVisionsState(prev => ({ ...prev, oracleSpec: value }));
  const setPredictionAccuracy = (value) => setVisionsState(prev => ({ ...prev, predictionAccuracy: typeof value === 'function' ? value(prev.predictionAccuracy) : value }));
  const setLastVisionGain = (value) => setVisionsState(prev => ({ ...prev, lastVisionGain: typeof value === 'function' ? value(prev.lastVisionGain) : value }));
  const setShowVisionsMenu = (value) => setVisionsState(prev => ({ ...prev, showVisionsMenu: value }));
  const setVisionsHoverSection = (value) => setVisionsState(prev => ({ ...prev, visionsHoverSection: value }));

        const specs = finalConfig.visual || {};
        const currentSpec = specs[oracleSpec] || specs['seer'];
        const maxVisions = specs.max || 10;
        const visionsValue = Math.min(localVisions, maxVisions);
        const specColor = currentSpec.activeColor || '#9370DB';
        const specGlow = currentSpec.glowColor || '#DDA0DD';
        const specIcon = currentSpec.icon || 'fa-eye';
        const specName = currentSpec.name || 'Seer';

        // Calculate visual state based on Vision count
        const getVisionState = () => {
            if (visionsValue >= 8) return 'clarity'; // 8-10: Fully aligned
            if (visionsValue >= 4) return 'stable'; // 4-7: Stable flow
            return 'murky'; // 0-3: Murky foresight
        };

        const visionState = getVisionState();

        // Get opacity based on state
        const getSegmentOpacity = (index) => {
            if (index >= visionsValue) return 0.15; // Empty
            if (visionState === 'clarity') return 1.0;
            if (visionState === 'stable') return 0.85;
            return 0.6; // murky
        };

        const handleBarClick = () => {
            if (!showVisionsMenu) {
                setVisionsHoverSection(null);
                setShowTooltip(false);
            }
            setShowVisionsMenu(!showVisionsMenu);
        };

        const handleVisionsBarEnter = (e) => {
            if (showVisionsMenu) return;

            setVisionsHoverSection('visions');
            const rect = visionsBarRef.current.getBoundingClientRect();
            const viewportHeight = window.innerHeight;
            const spaceBelow = viewportHeight - rect.bottom;
            const spaceAbove = rect.top;

            setTooltipPosition({ x: rect.left + rect.width / 2, y: rect.top });
            setTooltipPlacement(spaceBelow > 400 ? 'below' : (spaceAbove > 400 ? 'above' : 'below'));
            setShowTooltip(true);
        };

        const handleVisionsBarLeave = () => {
            if (showVisionsMenu) return;
            setVisionsHoverSection(null);
            setShowTooltip(false);
        };

        const handleVisionsAdjust = (delta) => {
            const newValue = Math.max(0, Math.min(maxVisions, localVisions + delta));
            const actualAmount = Math.abs(newValue - localVisions);
            setLocalVisions(newValue);
            if (actualAmount > 0) {
                logClassResourceChange('Vision', actualAmount, delta > 0, 'visions');
                if (onClassResourceUpdate) onClassResourceUpdate('current', newValue);
            }
        };

        const handlePredictionSuccess = (type) => {
            const gains = { simple: 1, moderate: 2, complex: 3 };
            const gain = gains[type] || 1;
            const bonusGain = oracleSpec === 'seer' ? 1 : 0; // Seer gets +1
            const totalGain = gain + bonusGain;

            setLocalVisions(Math.min(maxVisions, localVisions + totalGain));
            setPredictionAccuracy(prev => ({
                total: prev.total + 1,
                correct: prev.correct + 1,
                chain: prev.chain + 1
            }));

            // Update last vision gain
            setLastVisionGain(prev => [
                { source: `Correct Prediction (${type})${bonusGain > 0 ? ' +Seer Bonus' : ''}`, amount: totalGain },
                ...prev.slice(0, 2)
            ]);
        };

        const handlePredictionFailure = () => {
            setPredictionAccuracy(prev => ({
                total: prev.total + 1,
                correct: prev.correct,
                chain: 0 // Break the chain
            }));

            // Add visual feedback for failed prediction
            setLastVisionGain(prev => [
                { source: 'Failed Prediction', amount: 0 },
                ...prev.slice(0, 2)
            ]);
        };

        const handleRevelation = () => {
            const gain = 1;
            const newValue = Math.min(maxVisions, localVisions + gain);
            setLocalVisions(newValue);
            if (gain > 0) {
                logClassResourceChange('Vision', gain, true, 'visions');
                if (onClassResourceUpdate) onClassResourceUpdate('current', newValue);
            }
            setLastVisionGain(prev => [
                { source: 'Revelation', amount: gain },
                ...prev.slice(0, 2)
            ]);
        };


        return (
            <div className={`class-resource-bar prophetic-visions-bar ${size}`}>
                <div className="oracle-container">
                    {/* Prophetic Visions Bar */}
                    <div
                        className="visions-bar-wrapper"
                        ref={visionsBarRef}
                    >
                        {/* Vision count display - centered over bar */}
                        <div className="visions-count-overlay" style={{ color: specGlow }}>
                            {visionsValue}/{maxVisions}
                        </div>

                        {/* Segmented Visions */}
                        <div
                            className={`visions-segments visions-${visionState}`}
                            onClick={handleBarClick}
                            onMouseEnter={handleVisionsBarEnter}
                            onMouseLeave={handleVisionsBarLeave}
                        >
                            {Array.from({ length: maxVisions }, (_, index) => (
                                <div
                                    key={index}
                                    className={`vision-segment ${index < visionsValue ? 'filled' : 'empty'} ${visionState}`}
                                    style={{
                                        backgroundColor: index < visionsValue ? specColor : specs.emptyColor || '#0D0718',
                                        borderColor: specs.segmentBorder || '#2E1A5E',
                                        opacity: getSegmentOpacity(index),
                                        boxShadow: index < visionsValue ? `0 0 6px ${specGlow}` : 'none',
                                        transition: 'all 0.3s ease'
                                    }}
                                >
                                    {index < visionsValue && visionState === 'clarity' && (
                                        <i className={`fas ${specIcon}`} style={{
                                            color: '#FFF',
                                            fontSize: '10px',
                                            filter: 'drop-shadow(0 0 2px rgba(255,255,255,0.8))'
                                        }}></i>
                                    )}
                                </div>
                            ))}
                        </div>

                    </div>

                    {/* Visions Adjustment Menu */}
                    {showVisionsMenu && visionsBarRef.current && ReactDOM.createPortal(
                        <div
                            className={`unified-context-menu compact context-menu-container ${context === 'party' ? 'chronarch-party' : ''}`}
                            onMouseDown={(e) => { e.stopPropagation(); if (e.nativeEvent && e.nativeEvent.stopImmediatePropagation) { e.nativeEvent.stopImmediatePropagation(); } }}
                                onClick={(e) => { e.stopPropagation(); if (e.nativeEvent && e.nativeEvent.stopImmediatePropagation) { e.nativeEvent.stopImmediatePropagation(); } }}
                            style={{
                                position: 'fixed',
                                top: (() => {
                                    if (!visionsBarRef.current) return '50%';
                                    const rect = visionsBarRef.current.getBoundingClientRect();
                                    let hudContainer = visionsBarRef.current.closest('.party-hud, .party-member-frame, .character-portrait-hud');
                                    let hudBottom = rect.bottom;
                                    if (hudContainer) {
                                        const hudRect = hudContainer.getBoundingClientRect();
                                        hudBottom = hudRect.bottom;
                                    }
                                    return hudBottom + 8;
                                })(),
                                left: (() => {
                                    if (!visionsBarRef.current) return '50%';
                                    const rect = visionsBarRef.current.getBoundingClientRect();
                                    return rect.left + (rect.width / 2);
                                })(),
                                transform: 'translateX(-50%)',
                                zIndex: 100000
                            }}
                        >
                            <div className="context-menu-main">
                                <div className="menu-title">Visions: {visionsValue}/{maxVisions}</div>
                                {renderStatusFlavor()}

                                <div className="oracle-specs">
                                    {['seer', 'truthseeker', 'fateseer'].map((spec) => {
                                        const specConfig = specs[spec];
                                        const isSelected = oracleSpec === spec;
                                        return (
                                            <button
                                                key={spec}
                                                className={`oracle-spec-btn ${isSelected ? 'active' : ''}`}
                                                onClick={() => setOracleSpec(spec)}
                                                title={`${specConfig.name}: ${specConfig.theme}`}
                                            >
                                                <i className={`fas ${specConfig.icon}`}></i>
                                            </button>
                                        );
                                    })}
                                </div>

                                <div className="oracle-adjust-controls">
                                    <div className="oracle-adjust-row">
                                        <button
                                            className="context-menu-button decrease"
                                            onClick={() => handleVisionsAdjust(-1)}
                                            disabled={visionsValue === 0}
                                            title="Decrease Visions (-1)"
                                        >
                                            <i className="fas fa-minus"></i>
                                            <span>-1</span>
                                        </button>
                                        <button
                                            className="context-menu-button increase"
                                            onClick={() => handleVisionsAdjust(1)}
                                            disabled={visionsValue === maxVisions}
                                            title="Increase Visions (+1)"
                                        >
                                            <i className="fas fa-plus"></i>
                                            <span>+1</span>
                                        </button>
                                    </div>
                                    <div className="oracle-quick-adjust-row">
                                        <button
                                            className="context-menu-button"
                                            onClick={() => {
                                                const resetAmount = visionsValue;
                                                setLocalVisions(0);
                                                if (resetAmount > 0) {
                                                    logClassResourceChange('Vision', resetAmount, false, 'visions');
                                                    if (onClassResourceUpdate) onClassResourceUpdate('current', 0);
                                                }
                                            }}
                                            title="Clear (0)"
                                        >
                                            <i className="fas fa-eraser"></i>
                                        </button>
                                        <button
                                            className="context-menu-button"
                                            onClick={() => {
                                                const newValue = 3;
                                                const amount = Math.abs(newValue - visionsValue);
                                                setLocalVisions(newValue);
                                                if (amount > 0) {
                                                    logClassResourceChange('Vision', amount, newValue > visionsValue, 'visions');
                                                    if (onClassResourceUpdate) onClassResourceUpdate('current', newValue);
                                                }
                                            }}
                                            title="Reset (3)"
                                        >
                                            <i className="fas fa-undo"></i>
                                        </button>
                                        <button
                                            className="context-menu-button"
                                            onClick={() => {
                                                const gainAmount = maxVisions - visionsValue;
                                                setLocalVisions(maxVisions);
                                                if (gainAmount > 0) {
                                                    logClassResourceChange('Vision', gainAmount, true, 'visions');
                                                    if (onClassResourceUpdate) onClassResourceUpdate('current', maxVisions);
                                                }
                                            }}
                                            title={`Max (${maxVisions})`}
                                        >
                                            <i className="fas fa-crown"></i>
                                        </button>
                                    </div>
                                </div>

                                <div className="oracle-predictions">
                                    <div className="oracle-prediction-row">
                                        <button
                                            className="context-menu-button success"
                                            onClick={() => handlePredictionSuccess('simple')}
                                            title={`Simple (+1${oracleSpec === 'seer' ? '+1' : ''})`}
                                        >
                                            <i className="fas fa-check"></i>
                                            <span>+1</span>
                                        </button>
                                        <button
                                            className="context-menu-button success"
                                            onClick={() => handlePredictionSuccess('moderate')}
                                            title={`Moderate (+2${oracleSpec === 'seer' ? '+1' : ''})`}
                                        >
                                            <i className="fas fa-check-double"></i>
                                            <span>+2</span>
                                        </button>
                                    </div>
                                    <div className="oracle-prediction-row">
                                        <button
                                            className="context-menu-button success"
                                            onClick={() => handlePredictionSuccess('complex')}
                                            title={`Complex (+3${oracleSpec === 'seer' ? '+1' : ''})`}
                                        >
                                            <i className="fas fa-star"></i>
                                            <span>+3</span>
                                        </button>
                                        <button
                                            className="context-menu-button danger"
                                            onClick={handlePredictionFailure}
                                            title="Failed Prediction"
                                        >
                                            <i className="fas fa-times"></i>
                                            <span>Fail</span>
                                        </button>
                                    </div>
                                </div>

                                <div className="oracle-other-actions">
                                    <button
                                        className="context-menu-button special"
                                        onClick={handleRevelation}
                                        title="Revelation (+1 Vision)"
                                    >
                                        <i className="fas fa-lightbulb"></i>
                                        <span>+1</span>
                                    </button>
                                </div>

                                <div className="oracle-quick-actions">
                                    <button
                                        onClick={() => setShowVisionsMenu(false)}
                                        className="context-menu-button"
                                        title="Close"
                                    >
                                        <i className="fas fa-times"></i>
                                    </button>
                                </div>
                            </div>
                        </div>,
                        document.body
                    )}
                </div>
            </div>
        );

};

export default PropheticVisionsResourceBar;

import React from 'react';
import ReactDOM from 'react-dom';

const QuarryMarksResourceBar = ({
  huntressState,
  setHuntressState,
  uiState,
  setUiState,
  finalClassResource,
  finalConfig,
  character,
  isOwner,
  onClassResourceUpdate,
  size,
  context,
  qmBarRef,
  renderStatusFlavor,
  logClassResourceChange,
}) => {
  const {
      localQuarryMarks,
      companionHP,
      companionMaxHP,
      showQMMenu
  } = huntressState;

  const {} = uiState;

  const setShowTooltip = (value) => setUiState(prev => ({ ...prev, showTooltip: value }));
  const setTooltipPosition = (value) => setUiState(prev => ({ ...prev, tooltipPosition: value }));
  const setTooltipPlacement = (value) => setUiState(prev => ({ ...prev, tooltipPlacement: value }));
  const setLocalQuarryMarks = (value) => setHuntressState(prev => ({ ...prev, localQuarryMarks: value }));
  const setLocalCompanionHP = (value) => setHuntressState(prev => ({ ...prev, companionHP: value }));
  const setShowQMMenu = (value) => setHuntressState(prev => ({ ...prev, showQMMenu: value }));
  const setHuntressHoverSection = (value) => setHuntressState(prev => ({ ...prev, huntressHoverSection: value }));

        const specs = finalConfig.visual?.quarryMarks || {};
        const maxQM = finalClassResource.max ?? 5;
        const qmValue = Math.min(finalClassResource.current ?? localQuarryMarks, maxQM);
        const specColor = '#DC143C';
        const specGlow = '#FF6B6B';
        const specIcon = 'fa-khanda';

        // Companion info
        const companionHPValue = finalClassResource.companionHP ?? companionHP;
        const companionMaxHPValue = finalClassResource.companionMaxHP ?? companionMaxHP;
        const companionHPPercent = (companionHPValue / companionMaxHPValue) * 100;

        // Get companion HP bar color
        const getCompanionHPColor = () => {
            if (companionHPPercent > 60) return '#2E7D32'; // Green
            if (companionHPPercent > 30) return '#C67100'; // Dark Yellow/Gold
            return '#C62828'; // Red
        };

        const handleBarClick = () => {
            if (!showQMMenu) {
                // Hide tooltip when opening menu
                setHuntressHoverSection(null);
                setShowTooltip(false);
            }
            setShowQMMenu(!showQMMenu);
        };

        return (
            <div className={`class-resource-bar quarry-marks-companion ${size}`}>
                <div className="huntress-single-bar" style={{ display: 'flex', alignItems: 'center', width: '100%', gap: '4px' }}>
                    {/* Quarry Marks Bar (Left) */}
                    <div
                        className="qm-bar-wrapper"
                        ref={qmBarRef}
                        onClick={handleBarClick}
                        onMouseEnter={(e) => {
                            if (!showQMMenu) {
                                setHuntressHoverSection('marks');
                                const rect = e.currentTarget.getBoundingClientRect();
                                setTooltipPosition({ x: rect.left + rect.width / 2, y: rect.top });
                                setShowTooltip(true);
                            }
                        }}
                        onMouseLeave={() => {
                            setHuntressHoverSection(null);
                            setShowTooltip(false);
                        }}
                        style={{ cursor: isOwner ? 'pointer' : 'default', flex: 1 }}
                    >
                        {/* Segmented Quarry Marks */}
                        <div
                            className="qm-segments"
                            style={{ display: 'flex', gap: '2px', width: '100%' }}
                        >
                            {Array.from({ length: maxQM }, (_, index) => (
                                <div
                                    key={index}
                                    className={`qm-segment ${index < qmValue ? 'filled' : 'empty'}`}
                                    style={{
                                        flex: 1,
                                        height: size === 'large' ? '18px' : '12px',
                                        backgroundColor: index < qmValue ? specColor : 'rgba(26, 15, 8, 0.15)',
                                        border: '1px solid #4A2C1A',
                                        borderRadius: '3px',
                                        boxShadow: index < qmValue ? `0 0 6px ${specGlow}` : 'none',
                                        display: 'flex',
                                        alignItems: 'center',
                                        justifyContent: 'center'
                                    }}
                                >
                                    {index < qmValue && (
                                        <i className="fas fa-khanda" style={{ color: '#FFF', fontSize: '8px' }}></i>
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>

