  currentStance,
  selectedSpecialization,
  chronarchTimeShards,
  chronarchTemporalStrain,
  covenbaneHexbreakerCharges,
  covenbaneAttackCounter,
  localAscensionPaths,
  localBloodTokens,
  resilienceHoverSection,
  localDRP,
  selectedResistanceType,
  dominanceHoverSection,
  boundDemons,
  selectedDemonIndex,
  localDominanceDie,
  localMadness,
