  companionHP,
  companionMaxHP,
  phylacteryHoverSection,
  lichborneSpec,
  localPhylacteryHP,
  currentLunarPhase,
  roundsInPhase,
  lunarchSpec,
  localNotes,
  visionsHoverSection,
  oracleSpec,
  localVisions,
  berserkerRage,
}) => {
  const isArcanoneer = finalConfig.visual.type === 'elemental-spheres';
