                                </div>
                                {sphereCount > 0 && (
                                    <div style={{ fontSize: '0.85rem', marginTop: '4px' }}>
                                        {Object.entries(sphereBreakdown).map(([name, count]) => (
                                            <div key={name}>{name}: {count}</div>
