           );
           isCharacterToken = true;
         }
       }
 
       if (targetToken?.state?.conditions) {
         const updatedConditions = targetToken.state.conditions.map(c => {
           if (c.id === condition.id || c.name === condition.name) {
             return {
               ...c,
               durationValue: duration,
               durationType: durationType,
               remainingRounds: durationType === 'rounds' ? duration : undefined,
               // If it's time-based, the endpoint will be calculated by the store upon sync,
               // but we can update the core fields here.
             };
           }
           return c;
         });
 
         if (isCharacterToken) {
          const { updateCharacterTokenState } = useCharacterTokenStore.getState();
          updateCharacterTokenState(targetToken.id, { conditions: updatedConditions });
         } else {
           updateTokenState(targetToken.id, { conditions: updatedConditions });
         }
       }
    }

    setShowDurationModal(false);
    setDurationModalCondition(null);
  };





  // Check if target has a class resource bar to add appropriate styling
  const hasClassResource = targetData?.class && targetData?.classResource;
  const classResourceType = targetData?.class?.toLowerCase().replace(/\s+/g, '-');

  return (
    <>
      <div className="target-hud-frame">
        <Draggable
          handle=".target-frame"
          position={targetHUDPosition}
          onDrag={handleDrag}
          nodeRef={nodeRef}
          enableUserSelectHack={true} // Enable user select hack to prevent text selection during drag
          scale={1} // Fixed scale to prevent transform calculations
          disabled={false} // Ensure dragging is always enabled
        >
          <div ref={nodeRef} className="target-frame" style={{ position: 'relative' }}>
            <div
              className={`party-member-frame target-frame-style ${hasClassResource ? 'has-class-resource' : ''} ${hasClassResource ? `class-${classResourceType}` : ''}`}
              onContextMenu={handleRightClick}
            >
              {/* Portrait */}
              <div className="party-portrait">
                {(() => {
                  const lore = (targetType === 'party_member' || targetType === 'player') ? (
                    currentTarget.id === 'current-player' 
                      ? characterState.lore 
                      : partyMembers.find(m => m.id === currentTarget.id || m.userId === currentTarget.id || m.socketId === currentTarget.id)?.character?.lore
                  ) : null;
                  
                  const hasCustomStyling = !!(lore?.iconBackgroundImage || lore?.iconBackgroundColor || lore?.iconBorderColor);
                  const transformations = getImageTransformations();
                  const imageUrl = getTargetImage();
                  
                  return (
                    <>
                      {/* Backdrop Ring Layer */}
                      {hasCustomStyling && (
                        <div 
                          className="portrait-backdrop-ring"
                          style={{
                            position: 'absolute',
                            top: '0',
                            left: '0',
                            right: '0',
                            bottom: '0',
                            borderRadius: '8px',
                            backgroundColor: lore?.iconBackgroundColor || '#f8f5eb',
                            borderColor: 'transparent',
                            borderWidth: '0',
                            backgroundImage: lore?.iconBackgroundImage ? `url(/assets/backgrounds/${encodeURIComponent(lore.iconBackgroundImage)})` : 'none',
                            backgroundSize: lore?.iconBackgroundImage ? `${(lore?.iconBackgroundScale || 2.5) * 100}%` : 'cover',
                            backgroundPosition: lore?.iconBackgroundImage ? `calc(50% + ${lore?.iconBackgroundOffsetX || 0}px) calc(50% + ${lore?.iconBackgroundOffsetY || 0}px)` : 'center',
                            backgroundRepeat: 'no-repeat',
                            zIndex: 0
                          }}
                        />
                      )}
                      
                      <div 
                        className="portrait-image"
                        style={{
                          ...(hasCustomStyling ? { 
                            background: 'none', 
                            backgroundColor: 'transparent', 
                            borderColor: 'transparent', 
                            borderRadius: '8px' 
                          } : {}),
                          overflow: 'hidden',
                          position: 'relative',
                          zIndex: 1
                        }}
                      >
                        {imageUrl ? (
                          <img 
                            src={imageUrl} 
                            alt="Target Portrait" 
                            style={{
                              width: '100%',
                              height: '100%',
                              display: 'block',
                              objectFit: 'cover',
                              transform: transformations ? 
                                `scale(${(transformations.scale || (transformations.isCharacterImage ? 1.2 : 1)) * (transformations.iconScale || 1)}) rotate(${transformations.rotation || 0}deg) translate(${(transformations.positionX || 0) + (transformations.iconOffsetX || 0)}px, ${(transformations.positionY || 0) + (transformations.iconOffsetY || 0)}px)` : 
                                'scale(1.2)',
                              transition: 'transform 0.2s ease-out'
                            }}
                            draggable={false}
                          />
                        ) : (
                          <div className="portrait-placeholder-icon">
                            <i className="fas fa-crosshairs"></i>
                          </div>
                        )}
                      </div>
                    </>
                  );
                })()}
              </div>

              {/* Info Section */}
              <div className="party-member-info">
                <div className="member-header">
                  <div className="member-name">{targetData.name}</div>
                  <div className="member-details">
                    {targetData.isCreature ? (
                      <div className="member-race-class">
                        {targetData.race}
                      </div>
                    ) : (
                      <>
                        {/* Line 1: Race */}
                        <div className="member-race">
                          {targetData.race || 'Unknown Race'}
                        </div>
                        {/* Line 2: Background Class (Discipline) */}
                        {(() => {
                          const classParts = [];
                          if (targetData.background) {
                            classParts.push(targetData.background);
                          }
                          if (targetData.class) {
                            classParts.push(targetData.class);
                          }
                          if (targetData.path) {
                            classParts.push(`(${targetData.path})`);
                          }
                          const classLine = classParts.join(' ');
                          return classLine ? (
                            <div className="member-class-background">
                              {classLine}
                            </div>
                          ) : null;
                        })()}
                      </>
                    )}
                    {/* Line 3: Alignment */}
                    <div className="member-alignment">
                      <span className="alignment">{targetData.alignment}</span>
                      {targetData.exhaustionLevel > 0 && (
                        <span className="exhaustion">Exhausted {targetData.exhaustionLevel}</span>
                      )}
                    </div>
                  </div>
                </div>

                {/* Resource Bars */}
                <div className="resource-bars-container">
                  {/* Health Bar */}
                  <div
                    className="resource-bar health-bar"
                  >
                    <div
                      className="resource-fill"
                      style={{
                        width: `${healthPercent}%`,
                        backgroundColor: getHealthColor(healthPercent)
                      }}
                    />
                    {targetData.tempHealth > 0 && safeHealth.max > 0 && (
                      <div
                        className="temp-resource-fill health-temp"
                        style={{
                          position: 'absolute',
                          top: 0,
                          left: `${healthPercent}%`,
                          height: '100%',
                          width: `${Math.min(100 - healthPercent, (targetData.tempHealth / safeHealth.max) * 100)}%`,
                          backgroundColor: 'rgba(255, 255, 255, 0.4)',
                          transition: 'width 0.3s ease, left 0.3s ease',
                          zIndex: 1,
                          pointerEvents: 'none'
                        }}
                      />
                    )}
                    <div className="resource-text">
                      {(() => {
                        const current = safeHealth.current;
                        const max = safeHealth.max;
                        const temp = targetData.tempHealth || 0;
                        return temp > 0
                          ? `${current}/${max} +${temp} Temporary HP`
                          : `${current}/${max}`;
                      })()}
                    </div>
                  </div>

                  {/* Mana Bar */}
                  {showCreatureManaBar && safeMana.max > 0 && (
                    <div className="resource-bar mana-bar">
                      <div
                        className="resource-fill"
                        style={{
                          width: `${manaPercent}%`,
                          backgroundColor: 'var(--my-mana)'
                        }}
                      />
                      {targetData.tempMana > 0 && safeMana.max > 0 && (
                        <div
                          className="temp-resource-fill mana-temp"
                          style={{
                            position: 'absolute',
                            top: 0,
                            left: `${manaPercent}%`,
                            height: '100%',
                            width: `${Math.min(100 - manaPercent, (targetData.tempMana / safeMana.max) * 100)}%`,
                            backgroundColor: 'rgba(255, 255, 255, 0.4)',
                            transition: 'width 0.3s ease, left 0.3s ease',
                            zIndex: 1,
                            pointerEvents: 'none'
                          }}
                        />
                      )}
                      <div className="resource-text">
                        {(() => {
                          const current = safeMana.current;
                          const max = safeMana.max;
                          const temp = targetData.tempMana || 0;
                          return temp > 0
                            ? `${current}/${max} +${temp} Temporary Mana`
                            : `${current}/${max}`;
                        })()}
                      </div>
                    </div>
                  )}

                  {/* Action Points Bar */}
                  {showCreatureAPBar && safeActionPoints.max > 0 && (
                    <div className="resource-bar ap-bar">
                      <div
                        className="resource-fill"
                        style={{
                          width: `${apPercent}%`,
                          backgroundColor: 'var(--my-health-low)'
                        }}
                      />
                      {targetData.tempActionPoints > 0 && safeActionPoints.max > 0 && (
                        <div
                          className="temp-resource-fill ap-temp"
                          style={{
                            position: 'absolute',
                            top: 0,
                            left: `${apPercent}%`,
                            height: '100%',
                            width: `${Math.min(100 - apPercent, (targetData.tempActionPoints / safeActionPoints.max) * 100)}%`,
                            backgroundColor: 'rgba(255, 255, 255, 0.4)',
                            transition: 'width 0.3s ease, left 0.3s ease',
                            zIndex: 1,
                            pointerEvents: 'none'
                          }}
                        />
                      )}
                      <div className="resource-text">
                        {(() => {
                          const current = safeActionPoints.current;
                          const max = safeActionPoints.max;
                          const temp = targetData.tempActionPoints || 0;
                          return temp > 0
                            ? `${current}/${max} AP +${temp} Temporary AP`
                            : `${current}/${max} AP`;
                        })()}
                      </div>
                    </div>
                  )}

                  {/* Class Resource Bar - Only show if character has a class and class resource */}
                  {targetData?.class && targetData?.classResource && (
                    <ClassResourceBar
                      characterClass={targetData.class}
                      classResource={targetData.classResource}
                      isGMMode={isGMMode}
                      isOwner={false}
                      onClassResourceUpdate={null}
                      size="small"
                    />
                  )}
                </div>
              </div>

              {/* Status Indicators */}
              <div className="member-status-indicators">
                <div className="status-dot online"></div>
              </div>
            </div>

            {/* Target Conditions - positioned beneath the HUD */}
            {(() => {
              // Get target token conditions
              let targetConditions = [];
              if (targetType === 'creature') {
                const targetToken = tokens.find(t => t.id === currentTarget.id);
                targetConditions = targetToken?.state?.conditions || [];
              } else if (targetType === 'party_member' || targetType === 'player') {
                if (currentTarget.id === 'current-player') {
                  const playerToken = characterTokens.find(t => t.isPlayerToken);
                  targetConditions = playerToken?.state?.conditions || [];
                } else {
                  // For other party members, try to find their character token
                  const memberToken = characterTokens.find(t => t.playerId === currentTarget.id);
                  targetConditions = memberToken?.state?.conditions || [];
                }
              }

              // Format time helper for conditions
              const formatConditionTime = (condition) => {
                if (!condition.duration && !condition.durationType) return 'Ôê×';
                if (condition.durationType === 'rounds') {
                  const rounds = condition.remainingRounds ?? condition.durationValue ?? 0;
                  return `${rounds}r`;
                }
                if (condition.appliedAt && condition.duration) {
                  const remaining = Math.max(0, Math.floor((condition.appliedAt + condition.duration - Date.now()) / 1000));
                  const mins = Math.floor(remaining / 60);
                  const secs = remaining % 60;
                  return mins > 0 ? `${mins}:${secs.toString().padStart(2, '0')}` : `${secs}s`;
                }
                return 'Ôê×';
              };

              return (targetBuffs.length > 0 || targetDebuffs.length > 0 || targetConditions.length > 0) && (
                <div
                  className="target-conditions-beneath"
                  style={{
                    position: 'absolute',
                    top: '100%',
                    left: '0',
                    width: '100%',
                    marginTop: '4px',
                    display: 'flex',
                    flexDirection: 'column',
                    gap: '8px',
                    pointerEvents: 'none'
                  }}
                >
                  {/* Buffs Row */}
                  {targetBuffs.length > 0 && (
                    <div className="target-buffs" style={{ display: 'flex', gap: '4px' }}>
                      {targetBuffs.map((buff) => {
                        const remainingTime = buff.__isTokenDerived ? getFallbackConditionRemainingSeconds(buff, currentTime) : getRemainingTime('buff', buff.id);
                        
                        // Dynamic effect summary from effects object
                        const formattedEffects = formatBuffEffects(buff.effects);
                        const effectSummary = formattedEffects || buff.effectSummary;

                        const tooltipContent = {
                          title: buff.name,
                          type: 'buff',
                          color: buff.color || '#32CD32',
                          effectSummary: effectSummary,
                          description: buff.description,
                          effects: buff.effects,
                          duration: formatTime(remainingTime, buff.durationType),
                          durationType: buff.durationType,
                          remainingSeconds: remainingTime,
                        };
                        return (
                          <div
                            key={buff.id}
                            style={{
                              display: 'flex',
                              flexDirection: 'column',
                              alignItems: 'center',
                              pointerEvents: 'auto'
                            }}
                          >
                            <div
                              className="buff-icon"
                              style={{
                                backgroundColor: buff.color || '#32CD32'
                              }}
                              onMouseEnter={(e) => handleTooltipShow(e, tooltipContent)}
                              onMouseLeave={handleTooltipHide}
                              onContextMenu={(e) => handleConditionRightClick(e, buff, 'buff')}
                            >
                              {buff.icon && buff.icon.startsWith('/assets/') ? (
                                <img
                                  src={buff.icon}
                                  alt={buff.name}
                                  onError={(e) => {
                                    e.target.style.display = 'none';
                                  }}
                                />
                              ) : (
                                <i className={buff.icon || 'fas fa-plus'}></i>
                              )}
                            </div>
                            <div style={{
                              fontSize: '10px',
                              color: '#ffffff !important',
                              fontWeight: 'bold',
                              textShadow: '1px 1px 2px rgba(0, 0, 0, 0.9)',
                              marginTop: '2px',
                              fontFamily: 'Cinzel, serif'
                            }}>
                              {formatTime(remainingTime, buff.durationType)}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  )}

                  {/* Debuffs Row */}
                  {targetDebuffs.length > 0 && (
                    <div className="target-debuffs" style={{ display: 'flex', gap: '4px' }}>
                      {targetDebuffs.map((debuff) => {
                        const remainingTime = debuff.__isTokenDerived ? getFallbackConditionRemainingSeconds(debuff, currentTime) : getRemainingTime('debuff', debuff.id);
                        
                        const formattedEffects = formatDebuffEffects(debuff.effects);
                        const effectSummary = formattedEffects || debuff.effectSummary;

                        const tooltipContent = {
                          title: debuff.name,
                          type: 'debuff',
                          color: debuff.color || '#DC143C',
                          effectSummary: effectSummary,
                          description: debuff.description,
                          effects: debuff.effects,
                          duration: formatTime(remainingTime, debuff.durationType),
                          durationType: debuff.durationType,
                          remainingSeconds: remainingTime,
                        };
                        return (
                          <div
                            key={debuff.id}
                            style={{
                              display: 'flex',
                              flexDirection: 'column',
                              alignItems: 'center',
                              pointerEvents: 'auto'
                            }}
                          >
                            <div
                              className="debuff-icon"
                              style={{
                                backgroundColor: debuff.color || '#DC143C'
                              }}
                              onMouseEnter={(e) => handleTooltipShow(e, tooltipContent)}
                              onMouseLeave={handleTooltipHide}
                              onContextMenu={(e) => handleConditionRightClick(e, debuff, 'debuff')}
                            >
                              {debuff.icon && debuff.icon.startsWith('/assets/') ? (
                                <img
                                  src={debuff.icon}
                                  alt={debuff.name}
                                  onError={(e) => {
                                    e.target.style.display = 'none';
                                  }}
                                />
                              ) : (
                                <i className={debuff.icon || 'fas fa-minus'}></i>
                              )}
                            </div>
                            <div style={{
                              fontSize: '10px',
                              color: '#ffffff !important',
                              fontWeight: 'bold',
                              textShadow: '1px 1px 2px rgba(0, 0, 0, 0.9)',
                              marginTop: '2px',
                              fontFamily: 'Cinzel, serif'
                            }}>
                              {formatTime(remainingTime, debuff.durationType)}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  )}

                  {/* Conditions Row merged into buffs/debuffs row above */}
                </div>
              );
            })()}
          </div>
        </Draggable>
      </div>
      {/* Context Menu - Outside draggable container */}
      {showContextMenu && (() => {
        const menuItems = [];

        // Inspect - Only show for creatures if GM, otherwise show for players/party members
        const showInspect = targetType !== 'creature' || isGMMode;

        if (showInspect) {
          menuItems.push({
            icon: <i className="fas fa-search"></i>,
            label: 'Inspect',
            onClick: (e) => {
              e.preventDefault();
              e.stopPropagation();
              setShowContextMenu(false);
              handleInspectTarget();
            }
          });
        }

        // Clear Target
        menuItems.push({
          icon: <i className="fas fa-times"></i>,
          label: 'Clear Target',
          onClick: (e) => {
            e.preventDefault();
            e.stopPropagation();
            setShowContextMenu(false);
            handleClearTarget();
          }
        });

        // Resource adjustment options - show if GM mode for all target types
        if (isGMMode) {
          menuItems.push({ type: 'separator' });

          // Full Restore All
          menuItems.push({
            icon: <i className="fas fa-redo"></i>,
            label: 'Full Restore All',
            onClick: (e) => {
              e.preventDefault();
              e.stopPropagation();
              handleFullRestoreAll();
            },
            className: 'heal'
          });

          // Full Drain All
          menuItems.push({
            icon: <i className="fas fa-battery-empty"></i>,
            label: 'Full Drain All',
            onClick: (e) => {
              e.preventDefault();
              e.stopPropagation();
              handleFullDrainAll();
            },
            className: 'danger'
          });

          menuItems.push({ type: 'separator' });

          // Health submenu
          menuItems.push({
            icon: <i className="fas fa-heart"></i>,
            label: 'Health',
            submenu: [
              {
                icon: <i className="fas fa-minus-circle"></i>,
                label: 'Damage (5)',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  handleResourceAdjust('health', -5);
                  setShowContextMenu(false);
                }
              },
              {
                icon: <i className="fas fa-minus-circle"></i>,
                label: 'Damage (10)',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  handleResourceAdjust('health', -10);
                  setShowContextMenu(false);
                }
              },
              { type: 'separator' },
              {
                icon: <i className="fas fa-plus-circle"></i>,
                label: 'Heal (5)',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  handleResourceAdjust('health', 5);
                  setShowContextMenu(false);
                }
              },
              {
                icon: <i className="fas fa-plus-circle"></i>,
                label: 'Heal (10)',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  handleResourceAdjust('health', 10);
                  setShowContextMenu(false);
                }
              },
              { type: 'separator' },
              {
                icon: <i className="fas fa-heart"></i>,
                label: 'Full Heal',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  handleFullHeal();
                },
                className: 'heal'
              },
              {
                icon: <i className="fas fa-skull"></i>,
                label: 'Kill',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  handleKill();
                },
                className: 'danger'
              }
            ]
          });

          // Mana submenu
          menuItems.push({
            icon: <i className="fas fa-magic"></i>,
            label: 'Mana',
            submenu: [
              {
                icon: <i className="fas fa-minus-circle"></i>,
                label: 'Drain (5)',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  handleResourceAdjust('mana', -5);
                  setShowContextMenu(false);
                }
              },
              {
                icon: <i className="fas fa-minus-circle"></i>,
                label: 'Drain (10)',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  handleResourceAdjust('mana', -10);
                  setShowContextMenu(false);
                }
              },
              { type: 'separator' },
              {
                icon: <i className="fas fa-plus-circle"></i>,
                label: 'Restore (5)',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  handleResourceAdjust('mana', 5);
                  setShowContextMenu(false);
                }
              },
              {
                icon: <i className="fas fa-plus-circle"></i>,
                label: 'Restore (10)',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  handleResourceAdjust('mana', 10);
                  setShowContextMenu(false);
                }
              },
              { type: 'separator' },
              {
                icon: <i className="fas fa-magic"></i>,
                label: 'Full Restore',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  handleFullRestoreMana();
                },
                className: 'heal'
              },
              {
                icon: <i className="fas fa-battery-empty"></i>,
                label: 'Drain All',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  handleDrainMana();
                },
                className: 'danger'
              }
            ]
          });

          // Action Points submenu
          menuItems.push({
            icon: <i className="fas fa-bolt"></i>,
            label: 'Action Points',
            submenu: [
              {
                icon: <i className="fas fa-minus-circle"></i>,
                label: 'Spend (1)',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  handleResourceAdjust('actionPoints', -1);
                  setShowContextMenu(false);
                }
              },
              {
                icon: <i className="fas fa-minus-circle"></i>,
                label: 'Spend (2)',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  handleResourceAdjust('actionPoints', -2);
                  setShowContextMenu(false);
                }
              },
              {
                icon: <i className="fas fa-minus-circle"></i>,
                label: 'Spend (3)',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  handleResourceAdjust('actionPoints', -3);
                  setShowContextMenu(false);
                }
              },
              { type: 'separator' },
              {
                icon: <i className="fas fa-plus-circle"></i>,
                label: 'Restore (1)',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  handleResourceAdjust('actionPoints', 1);
                  setShowContextMenu(false);
                }
              },
              {
                icon: <i className="fas fa-plus-circle"></i>,
                label: 'Restore (2)',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  handleResourceAdjust('actionPoints', 2);
                  setShowContextMenu(false);
                }
              },
              {
                icon: <i className="fas fa-plus-circle"></i>,
                label: 'Restore (3)',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  handleResourceAdjust('actionPoints', 3);
                  setShowContextMenu(false);
                }
              },
              { type: 'separator' },
              {
                icon: <i className="fas fa-bolt"></i>,
                label: 'Full Restore',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  if (!currentTarget || !targetData) return;

                  if (targetType === 'party_member' || targetType === 'player') {
                    const memberId = currentTarget.id;

                    if (memberId === 'current-player') {
                      const characterState = useCharacterStore.getState();
                      const maxAp = characterState.actionPoints?.max || 0;
                      const currentAp = characterState.actionPoints?.current || 0;
                      handleResourceAdjust('actionPoints', maxAp - currentAp);
                    } else {
                      const partyState = usePartyStore.getState();
                      const member = partyState.partyMembers.find(m => m.id === memberId);
                      if (member && member.character) {
                        const maxAp = member.character.actionPoints?.max || 0;
                        const currentAp = member.character.actionPoints?.current || 0;
                        handleResourceAdjust('actionPoints', maxAp - currentAp);
                      }
                    }
                  } else if (targetType === 'creature') {
                    const tokenId = currentTarget.id;
                    const token = tokens.find(t => t.id === tokenId);
                    if (token) {
                      // Use modified stats from targetData (includes buff/debuff effects)
                      const modifiedStats = targetData?.modifiedStats || currentTarget.stats || {};
                      const maxAp = modifiedStats.maxActionPoints || 0;
                      const currentAp = token.state?.currentActionPoints || 0;
                      handleResourceAdjust('actionPoints', maxAp - currentAp);
                    }
                  }
                  setShowContextMenu(false);
                },
                className: 'heal'
              },
              {
                icon: <i className="fas fa-battery-empty"></i>,
                label: 'Drain All',
                onClick: (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  handleDrainAP();
                },
                className: 'danger'
              }
            ]
          });
        }

        return (
          <div
            ref={contextMenuRef}
            className="context-menu-container"
            style={{
              position: 'fixed',
              left: contextMenuPosition.x,
              top: contextMenuPosition.y,
              zIndex: 10000,
              backgroundColor: '#f0e6d2',
              border: '2px solid #a08c70',
              borderRadius: '8px',
              boxShadow: '0 4px 12px rgba(0, 0, 0, 0.3)',
              fontFamily: "'Bookman Old Style', 'Garamond', serif",
              color: '#7a3b2e',
              padding: '8px',
              display: 'flex',
              gap: '0',
              minWidth: hoveredMenuItem !== null && menuItems[hoveredMenuItem]?.submenu ? '280px' : '160px'
            }}
            onMouseLeave={() => {
              // Close menu when mouse leaves entire container
              setHoveredMenuItem(null);
            }}
            onClick={(e) => e.stopPropagation()}
          >
            {/* Main menu items */}
            <div style={{ display: 'flex', flexDirection: 'column', flex: 1 }}>
              {menuItems.map((item, index) => (
                <React.Fragment key={index}>
                  {item.type === 'separator' ? (
                    <hr style={{
                      border: 'none',
                      borderTop: '1px solid #a08c70',
                      margin: '4px 0',
                      width: '100%'
                    }} />
                  ) : (
                    <button
                      className="context-menu-button"
                      style={{
                        pointerEvents: 'auto',
                        display: 'flex',
                        alignItems: 'center',
                        gap: '8px',
                        padding: '6px 12px',
                        border: '1px solid #a08c70',
                        borderRadius: '4px',
                        backgroundColor: hoveredMenuItem === index ? '#e8dcc0' : (item.className === 'danger' ? '#ffebee' : item.className === 'heal' ? '#e8f5e9' : '#d4c4a8'),
                        color: '#7a3b2e',
                        cursor: 'pointer',
                        fontSize: '12px',
                        fontFamily: "'Bookman Old Style', 'Garamond', serif",
                        width: '100%',
                        textAlign: 'left',
                        margin: '2px 0',
                        minWidth: '140px'
                      }}
                      onMouseEnter={() => {
                        setHoveredMenuItem(index);
                      }}
                      onClick={(e) => {
                        e.stopPropagation();
                        if (item.submenu) {
                          // Don't close on submenu items, just keep submenu open
                          return;
                        }
                        if (item.onClick) {
                          item.onClick(e);
                        }
                        if (!item.submenu) {
                          setShowContextMenu(false);
                        }
                      }}
                      disabled={item.disabled}
                      title={item.title}
                    >
                      {item.icon}
                      <span>{item.label}</span>
                      {item.submenu && <i className="fas fa-chevron-right" style={{ marginLeft: 'auto', fontSize: '10px' }} />}
                    </button>
                  )}
                </React.Fragment>
              ))}
            </div>

            {/* Submenu - always rendered but only visible when hovering */}
            {menuItems[hoveredMenuItem]?.submenu && (
              <div
                style={{
                  display: 'flex',
                  flexDirection: 'column',
                  backgroundColor: '#f0e6d2',
                  border: '1px solid #a08c70',
                  borderLeft: 'none',
                  borderRadius: '0 4px 4px 0',
                  padding: '8px 4px',
                  minWidth: '130px',
                  marginLeft: '4px',
                  opacity: hoveredMenuItem !== null ? 1 : 0,
                  visibility: hoveredMenuItem !== null ? 'visible' : 'hidden',
                  transition: 'opacity 0.1s ease, visibility 0.1s ease'
                }}
              >
                {menuItems[hoveredMenuItem].submenu.map((subItem, subIndex) => (
                  <React.Fragment key={subIndex}>
                    {subItem.type === 'separator' ? (
                      <hr style={{
                        border: 'none',
                        borderTop: '1px solid #a08c70',
                        margin: '2px 0',
                        width: '100%'
                      }} />
                    ) : (
                      <button
                        className="context-menu-button"
                        style={{
                          pointerEvents: 'auto',
                          display: 'flex',
                          alignItems: 'center',
                          gap: '6px',
                          padding: '4px 8px',
                          border: '1px solid #a08c70',
                          borderRadius: '3px',
                          backgroundColor: subItem.className === 'danger' ? '#ffebee' : subItem.className === 'heal' ? '#e8f5e9' : '#d4c4a8',
                          color: '#7a3b2e',
                          cursor: 'pointer',
                          fontSize: '11px',
                          fontFamily: "'Bookman Old Style', 'Garamond', serif",
                          width: '100%',
                          textAlign: 'left',
                          margin: '1px 0'
                        }}
                        onClick={(e) => {
                          e.stopPropagation();
                          if (subItem.onClick) {
                            subItem.onClick(e);
                          }
                          setShowContextMenu(false);
                        }}
                      >
                        {subItem.icon}
                        <span>{subItem.label}</span>
                      </button>
                    )}
                  </React.Fragment>
                ))}
              </div>
            )}
          </div>
        );
      })()}
      {/* Condition Duration Modal */}
      {showDurationModal && durationModalCondition && (
        <ConditionDurationModal
          show={showDurationModal}
          onClose={() => {
            setShowDurationModal(false);
            setDurationModalCondition(null);
          }}
          onApply={handleDurationModalApply}
          conditionName={durationModalCondition.name || ''}
          initialDurationType={durationModalCondition.initialDurationType || 'minutes'}
          initialDurationValue={durationModalCondition.initialDurationValue || 10}
        />
      )}
      {/* Condition Tooltip */}
      {tooltip.show && (
        <div
          ref={tooltipRef}
          className="equipment-slot-tooltip"
          style={{
            position: 'fixed',
            left: adjustedPosition.x,
            top: adjustedPosition.y,
            zIndex: 10000,
            pointerEvents: 'none',
            backgroundColor: '#2c1810',
            backgroundImage: 'url("https://www.transparenttextures.com/patterns/parchment.png")',
            border: '2px solid #8b6f47',
            borderRadius: '6px',
            padding: '10px 14px',
            minWidth: '200px',
            maxWidth: '320px',
            boxShadow: '0 4px 16px rgba(0, 0, 0, 0.6)',
            fontFamily: "'Bookman Old Style', 'Garamond', serif",
          }}
        >
          <div style={{
            display: 'flex',
            alignItems: 'center',
            gap: '8px',
            marginBottom: '6px',
            paddingBottom: '6px',
            borderBottom: `2px solid ${tooltip.content.color || '#8b6f47'}`,
          }}>
            <div style={{
              width: '10px',
              height: '10px',
              borderRadius: '50%',
              backgroundColor: tooltip.content.color || '#8b6f47',
              flexShrink: 0,
            }}></div>
            <div style={{
              fontSize: '14px',
              fontWeight: 'bold',
              color: '#f0e6d2',
              textTransform: 'uppercase',
              letterSpacing: '0.5px',
            }}>
              {tooltip.content.title}
            </div>
            <div style={{
              fontSize: '10px',
              color: tooltip.content.color || '#8b6f47',
              marginLeft: 'auto',
              fontStyle: 'italic',
              textTransform: 'uppercase',
            }}>
              {tooltip.content.type}
            </div>
          </div>
          {tooltip.content.description && (
            <div style={{
              fontSize: '12px',
              color: '#d4c5b9',
              marginBottom: '8px',
              lineHeight: '1.4',
              fontStyle: 'italic',
            }}>
              {tooltip.content.description}
            </div>
          )}
          {tooltip.content.effectSummary && (
            <div style={{
              fontSize: '12px',
              color: '#a0d995',
              fontWeight: '600',
              marginBottom: '8px',
              padding: '6px 10px',
              backgroundColor: 'rgba(122, 59, 46, 0.15)',
              borderRadius: '4px',
              borderLeft: '3px solid #7a3b2e',
              lineHeight: '1.5',
            }}>
              {tooltip.content.effectSummary}
            </div>
          )}
          {tooltip.content.effects && typeof tooltip.content.effects === 'object' && !tooltip.content.effectSummary && (
            <div style={{
              fontSize: '11px',
              color: '#a0d995',
              marginBottom: '6px',
            }}>
              {Object.entries(tooltip.content.effects).map(([stat, val]) => {
                if (!val) return null;
                const statName = stat.replace(/([A-Z])/g, ' $1').replace(/_/g, ' ')
                  .split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ').trim();
                const isPositive = Number(val) > 0;
                return (
                  <div key={stat} style={{ color: isPositive ? '#a0d995' : '#e57373' }}>
                    {isPositive ? '+' : ''}{val} {statName}
                  </div>
                );
              })}
            </div>
          )}
          <div style={{
            marginTop: '6px',
            fontSize: '11px',
            color: '#8b6f47',
            fontWeight: 'bold',
            display: 'flex',
            alignItems: 'center',
            gap: '4px',
          }}>
            <i className="fas fa-hourglass-half" style={{ fontSize: '10px' }}></i>
            {tooltip.content.remainingSeconds <= 0 ? 'Expired' : `Duration: ${tooltip.content.duration}`}
          </div>
        </div>
      )}
      {/* Condition Context Menu */}
      {conditionContextMenu.show && (
        <>
          <div
            className="context-menu-overlay"
            onClick={() => setConditionContextMenu({ show: false, condition: null, position: { x: 0, y: 0 } })}
          />
          <div
            className={`unified-context-menu small condition-context-menu ${conditionContextMenu.condition?.type === 'buff' ? 'buff-context-menu' : 'debuff-context-menu'}`}
            style={{
              left: conditionContextMenu.position.x,
              top: conditionContextMenu.position.y
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <div className="context-menu-main">
              <div
                className="context-menu-item"
                onClick={(e) => {
                  e.stopPropagation();
                  handleAdjustConditionTime();
                }}
              >
                <i className="fas fa-clock" style={{ marginRight: '8px' }}></i>
                Adjust Duration
              </div>
              <div
                className="context-menu-item danger"
                onClick={(e) => {
                  e.stopPropagation();
                  handleRemoveCondition(conditionContextMenu.condition, conditionContextMenu.condition?.type);
                }}
              >
                <i className="fas fa-times" style={{ marginRight: '8px' }}></i>
                Remove Condition
              </div>
            </div>
          </div>
        </>
      )}
      {/* Creature Inspection Window */}
      {showCreatureInspect && targetType === 'creature' && inspectCreatureData && (
        <EnhancedCreatureInspectView
          creature={inspectCreatureData}
          token={inspectToken}
          isOpen={showCreatureInspect}
          onClose={() => {
            setShowCreatureInspect(false);
            setInspectCreatureData(null);
            setInspectToken(null);
          }}
        />
      )}
      {/* Overheal Confirmation Modal */}
      {showOverhealModal && overhealData && createPortal(
        <div
          className="modal-overlay"
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: 'rgba(0, 0, 0, 0.5)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 10001
          }}
          onClick={() => {
            setShowOverhealModal(false);
            setOverhealData(null);
          }}
        >
          <div
            className="overheal-modal"
            style={{
              backgroundColor: '#f0e6d2',
              backgroundImage: 'url("https://www.transparenttextures.com/patterns/parchment.png")',
              border: '3px solid #8b4513',
              borderRadius: '12px',
              padding: '24px',
              boxShadow: '0 10px 30px rgba(0, 0, 0, 0.5), inset 0 0 60px rgba(139, 69, 19, 0.1)',
              fontFamily: "'Cinzel', serif",
              color: '#1a0f08',
              minWidth: '400px',
              maxWidth: '500px',
              textAlign: 'center',
              position: 'relative'
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <h3 style={{ 
              margin: '0 0 20px 0', 
              fontSize: '22px', 
              color: '#7a3b2e',
              borderBottom: '2px solid #8b4513',
              paddingBottom: '10px',
              textTransform: 'uppercase',
              letterSpacing: '1px'
            }}>
              Overheal Detected
            </h3>
            <p style={{ margin: '0 0 15px 0', fontSize: '16px', color: '#4a3728' }}>
              {getTargetName()} is being healed for <strong>{overhealData.adjustment}</strong> points of {overhealData.resourceType}, which exceeds their maximum.
              <br />
              <strong style={{ color: '#7a3b2e' }}>{overhealData.overhealAmount}</strong> would exceed the maximum.
            </p>
            
            <div style={{ 
              display: 'flex', 
              gap: '12px', 
              justifyContent: 'center', 
              marginTop: '25px',
              paddingTop: '20px',
              borderTop: '1px solid rgba(139, 69, 19, 0.2)'
            }}>
              <Button
                variant="game-secondary"
                onClick={() => {
                  setShowOverhealModal(false);
                  setOverhealData(null);
                }}
              >
                Cancel
              </Button>
              <Button
                variant="game-secondary"
                onClick={() => {
                  applyResourceAdjustment(overhealData.resourceType, overhealData.adjustment, false);
                  setShowOverhealModal(false);
                  setOverhealData(null);
                }}
              >
                Cap at Max
              </Button>
              <Button
                variant="game-primary"
                onClick={() => {
                  applyResourceAdjustment(overhealData.resourceType, overhealData.adjustment, true);
                  setShowOverhealModal(false);
                  setOverhealData(null);
                }}
              >
                Add Temporary
              </Button>
            </div>
          </div>
        </div>,
        document.body
      )}
    </>
  );
};

export default TargetHUD;

import React from 'react';
import ReactDOM from 'react-dom';

const ThreadsOfDestinyResourceBar = ({
  fateWeaverState,
  setFateWeaverState,
  uiState,
  setUiState,
  finalClassResource,
  finalConfig,
  character,
  isOwner,
  onClassResourceUpdate,
  size,
  context,
  modifiedConfig,
  threadsBarRef,
  renderStatusFlavor,
  logClassResourceChange,
  getThreadLevel,
}) => {
  const {
      localThreads,
      showThreadsMenu,
      selectedFateWeaverSpec
  } = fateWeaverState;

  const {} = uiState;

  const setShowTooltip = (value) => setUiState(prev => ({ ...prev, showTooltip: value }));
  const setTooltipPosition = (value) => setUiState(prev => ({ ...prev, tooltipPosition: value }));
  const setTooltipPlacement = (value) => setUiState(prev => ({ ...prev, tooltipPlacement: value }));
  const setLocalThreads = (value) => setFateWeaverState(prev => ({ ...prev, localThreads: value }));
  const setShowThreadsMenu = (value) => setFateWeaverState(prev => ({ ...prev, showThreadsMenu: value }));
  const setFateWeaverHoverSection = (value) => setFateWeaverState(prev => ({ ...prev, fateWeaverHoverSection: value }));
  const setSelectedFateWeaverSpec = (value) => setFateWeaverState(prev => ({ ...prev, selectedFateWeaverSpec: value }));

        // Use local state for demo, fallback to classResource
        const currentThreads = localThreads ?? finalClassResource?.current ?? 0;
        const maxThreads = modifiedConfig.mechanics?.max ?? 13;

        const threadLevel = getThreadLevel(currentThreads);

        // Get card suit symbol for segment (cycles through specialization-specific symbols)
        const getCardSuit = (index) => {
            const spec = selectedFateWeaverSpec;
            if (spec === 'fortune-teller') {
                const crystalSymbols = modifiedConfig.visual.crystalSymbols || ['\u25C6', '\u25C8', '\u2736', '\u2605'];
                return crystalSymbols[index % crystalSymbols.length];
            } else if (spec === 'card-master') {
                const cardSymbols = modifiedConfig.visual.cardSymbols || ['card', '?', '?', '?', '?'];
                return cardSymbols[index % cardSymbols.length];
            } else if (spec === 'thread-weaver') {
                const webSymbols = modifiedConfig.visual.webSymbols || ['\u29B7', '\u2736', '\u2605', '\u25C8'];
                return webSymbols[index % webSymbols.length];
            } else {
                const suits = modifiedConfig.visual.cardSuits || ['?', '?', '?', '?'];
                return suits[index % suits.length];
            }
        };

        // Get segment color based on specialization
        const getSegmentColor = (index) => {
            const spec = selectedFateWeaverSpec;
            switch (spec) {
                case 'fortune-teller':
                    const crystalProgress = index / maxThreads;
                    if (crystalProgress < 0.25) return '#9370DB'; // Medium purple
                    if (crystalProgress < 0.5) return '#BA55D3'; // Medium orchid
                    if (crystalProgress < 0.75) return '#8A2BE2'; // Blue violet
                    return '#DA70D6'; // Orchid
                case 'card-master':
                    const cardProgress = index / maxThreads;
                    if (cardProgress < 0.25) return '#FFD700'; // Gold
                    if (cardProgress < 0.5) return '#F0E68C'; // Pale goldenrod
                    if (cardProgress < 0.75) return '#DAA520'; // Goldenrod
                    return '#FFA500'; // Orange
                case 'thread-weaver':
                    const webProgress = index / maxThreads;
                    if (webProgress < 0.25) return '#FF1493'; // Deep pink
                    if (webProgress < 0.5) return '#FF69B4'; // Hot pink
                    if (webProgress < 0.75) return '#DC143C'; // Crimson
                    return '#FF6347'; // Tomato
                default:
                    const progress = index / maxThreads;
                    if (progress < 0.25) return '#9370DB'; // Medium purple
                    if (progress < 0.5) return '#B8860B'; // Dark goldenrod
                    if (progress < 0.75) return '#FFD700'; // Gold
                    return '#FFA500'; // Orange-gold
            }
        };

        // Adjustment functions
        const gainThreads = (amount) => {
            const newValue = Math.min(maxThreads, currentThreads + amount);
            const actualAmount = newValue - currentThreads;
            setLocalThreads(newValue);
            if (actualAmount > 0) {
                logClassResourceChange('Thread', actualAmount, true, 'threads');
                if (onClassResourceUpdate) onClassResourceUpdate('current', newValue);
            }
        };

        const spendThreads = (amount) => {
            const newValue = Math.max(0, currentThreads - amount);
            const actualAmount = currentThreads - newValue;
            setLocalThreads(newValue);
            if (actualAmount > 0) {
                logClassResourceChange('Thread', actualAmount, false, 'threads');
                if (onClassResourceUpdate) onClassResourceUpdate('current', newValue);
            }
        };

        const resetThreads = () => {
            setLocalThreads(0);
        };

        const setToMax = () => {
            const maxThreads = modifiedConfig.mechanics?.max ?? 13;
            setLocalThreads(maxThreads);
        };

        // Tooltip handlers
        const handleThreadsBarEnter = (e) => {
            setFateWeaverHoverSection('threads');
            const rect = threadsBarRef.current.getBoundingClientRect();
            const viewportHeight = window.innerHeight;
            const spaceBelow = viewportHeight - rect.bottom;
            const spaceAbove = rect.top;

            setTooltipPosition({ x: rect.left + rect.width / 2, y: rect.top });
            setTooltipPlacement(spaceBelow > 400 ? 'below' : (spaceAbove > 400 ? 'above' : 'below'));
            setShowTooltip(true);
        };

        const handleThreadsBarLeave = () => {
            setFateWeaverHoverSection(null);
            setShowTooltip(false);
        };

        const handleBarClick = () => {
            setShowThreadsMenu(!showThreadsMenu);
        };

        return (
            <div className={`class-resource-bar threads-of-destiny ${size}`}>
                <div className="threads-bar-wrapper">
                    <div
                        className="threads-bar-container"
                        ref={threadsBarRef}
                        onMouseEnter={handleThreadsBarEnter}
                        onMouseLeave={handleThreadsBarLeave}
                        onClick={handleBarClick}
                        style={{ cursor: 'pointer' }}
                    >
                        {/* Segmented threads bar with specialization symbols */}
                        <div className="threads-segments">
                            {Array.from({ length: maxThreads }, (_, index) => (
                                <div
                                    key={index}
                                    className={`thread-segment ${index < currentThreads ? 'woven' : 'empty'}`}
                                    style={{
                                        backgroundColor: index < currentThreads ? getSegmentColor(index) : modifiedConfig.visual.baseColor,
                                        borderColor: modifiedConfig.visual.segmentBorder,
                                        boxShadow: index < currentThreads ? `0 0 6px ${getSegmentColor(index)}` : 'none'
                                    }}
                                >
                                    {/* Card suit symbol */}
                                    <span className="card-suit-symbol" style={{
                                        color: index < currentThreads ? '#FFF' : 'rgba(147, 112, 219, 0.3)',
                                        opacity: index < currentThreads ? 0.6 : 0.3
                                    }}>
                                        {getCardSuit(index)}
                                    </span>
                                </div>
                            ))}
                        </div>

                        {/* Threads value label */}
                        <div className="threads-value-label">
                            {currentThreads} / {maxThreads}
                        </div>
                    </div>

                    {/* Adjustment Menu */}
                    {showThreadsMenu && threadsBarRef.current && ReactDOM.createPortal(
                        <div
                            className={`unified-context-menu compact context-menu-container ${context === 'party' ? 'chronarch-party' : ''}`}
                            onMouseDown={(e) => { e.stopPropagation(); if (e.nativeEvent && e.nativeEvent.stopImmediatePropagation) { e.nativeEvent.stopImmediatePropagation(); } }}
                                onClick={(e) => { e.stopPropagation(); if (e.nativeEvent && e.nativeEvent.stopImmediatePropagation) { e.nativeEvent.stopImmediatePropagation(); } }}
                            style={{
                                position: 'fixed',
                                top: (() => {
                                    if (!threadsBarRef.current) return '50%';
                                    const rect = threadsBarRef.current.getBoundingClientRect();
                                    // Find the HUD container to position menu below it
                                    let hudContainer = threadsBarRef.current.closest('.party-hud, .party-member-frame, .character-portrait-hud');
                                    let hudBottom = rect.bottom;
                                    if (hudContainer) {
                                        const hudRect = hudContainer.getBoundingClientRect();
                                        hudBottom = hudRect.bottom;
                                    }
                                    return hudBottom + 8;
                                })(),
                                left: (() => {
                                    if (!threadsBarRef.current) return '50%';
                                    const rect = threadsBarRef.current.getBoundingClientRect();
                                    return rect.left + (rect.width / 2);
                                })(),
                                transform: 'translateX(-50%)',
                                zIndex: 100000
                            }}
                        >
                            <div className="context-menu-main">
                                <div className="menu-title">Threads: {currentThreads}/{maxThreads}</div>
                                {renderStatusFlavor()}

                                <div className="fateweaver-actions">
                                    <div className="fateweaver-action-row">
                                        <button onClick={() => gainThreads(1)} className="context-menu-button gain" title="Gain 1 Thread (Minor Failure)">
                                            <i className="fas fa-plus"></i>
                                            <span>+1</span>
                                        </button>
                                        <button onClick={() => gainThreads(2)} className="context-menu-button gain" title="Gain 2 Threads (Major Failure)">
                                            <i className="fas fa-plus-circle"></i>
                                            <span>+2</span>
                                        </button>
                                        <button onClick={() => gainThreads(3)} className="context-menu-button gain" title="Gain 3 Threads (Destiny Weaver)">
                                            <i className="fas fa-star"></i>
                                            <span>+3</span>
                                        </button>
                                    </div>
                                    <div className="fateweaver-action-row">
                                        <button onClick={() => spendThreads(2)} className="context-menu-button spend" title="Call Card (-2 Threads)">
                                            <i className="fas fa-hand-sparkles"></i>
                                            <span>-2</span>
                                        </button>
                                        <button onClick={() => spendThreads(3)} className="context-menu-button spend" title="Force Failure (-3 Threads)">
                                            <i className="fas fa-times-circle"></i>
                                            <span>-3</span>
                                        </button>
