import React from 'react';
import ReactDOM from 'react-dom';

const TimeShardsStrainResourceBar = ({
  chronarchState,
  setChronarchState,
  finalClassResource,
  finalConfig,
  character,
  isOwner,
  onClassResourceUpdate,
  size,
  context,
  timeShardsBarRef,
  temporalStrainBarRef,
