        }
        updateCampaignData({
            selectedSpells: (campaignData.selectedSpells || []).filter(s => s.id !== itemId)
        });
    };

    const renderTabContent = () => {
        switch (activeTab) {
            case 'overview':
                return (
                    <div className="campaign-tab-content">
                        <div className="campaign-overview">
                            <div className="campaign-header-section">
                                <div className="campaign-field" style={{ marginBottom: '16px' }}>
                                    <label style={{ marginBottom: '6px' }}>Campaign</label>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap' }}>
                                        <select
                                            value={currentCampaignId || ''}
                                            onChange={(e) => {
                                                const newCampaignId = e.target.value;
                                                campaignService.setCurrentCampaign(newCampaignId);
                                                setCurrentCampaignId(newCampaignId);
                                                const campaign = campaignService.getCampaign(newCampaignId);
                                                // Load the campaign data or reset to defaults
                                                const defaultData = {
                                                    name: campaign?.name || 'New Campaign',
                                                    description: campaign?.description || '',
                                                    currentSession: 1,
                                                    players: [],
                                                    sessions: [],
                                                    npcs: [],
                                                    locations: [],
                                                    plotThreads: [],
                                                    quests: [],
                                                    homebrew: { items: [], monsters: [], spells: [], lore: [] },
                                                    selectedCreatures: [],
                                                    selectedItems: [],
                                                    selectedSpells: []
                                                };
                                                setCampaignData(campaign?.campaignData ? { ...defaultData, ...campaign.campaignData } : defaultData);
                                            }}
                                            className="campaign-input"
                                            style={{ minWidth: '150px', flex: '1 1 0%' }}
                                        >
                                            {campaigns.map(campaign => (
                                                <option key={campaign.id} value={campaign.id}>{campaign.name}</option>
                                            ))}
                                        </select>
                                        <button
                                            onClick={() => {
                                                const newCampaign = campaignService.createCampaign({ name: 'New Campaign' });
                                                setCampaigns(campaignService.getCampaigns());
                                                campaignService.setCurrentCampaign(newCampaign.id);
                                                setCurrentCampaignId(newCampaign.id);
                                                // Reset to fresh campaign data
                                                const freshData = {
                                                    name: 'New Campaign',
                                                    description: '',
                                                    currentSession: 1,
                                                    players: [],
                                                    sessions: [],
                                                    npcs: [],
                                                    locations: [],
                                                    plotThreads: [],
                                                    quests: [],
                                                    homebrew: { items: [], monsters: [], spells: [], lore: [] },
                                                    selectedCreatures: [],
                                                    selectedItems: [],
                                                    selectedSpells: []
                                                };
                                                setCampaignData(newCampaign.campaignData || freshData);
                                            }}
                                            className="campaign-input"
                                            style={{
                                                padding: '10px 12px',
                                                cursor: 'pointer',
                                                fontSize: '13px',
                                                display: 'flex',
                                                alignItems: 'center',
                                                justifyContent: 'center',
                                                flexShrink: 0,
                                                width: 'auto',
                                                minWidth: '80px',
                                                height: '42px',
                                                boxSizing: 'border-box'
                                            }}
                                        >
                                            + New
                                        </button>
                                        <button
                                            onClick={() => {
                                                if (currentCampaignId) {
                                                    // Convert to string for comparison to handle type mismatches
                                                    const idStr = String(currentCampaignId);
                                                    const campaignToDelete = campaigns.find(c => String(c.id) === idStr);
                                                    showConfirmModal(
                                                        'Delete Campaign',
                                                        `Are you sure you want to delete the campaign "${campaignToDelete?.name || 'this campaign'}"? This action cannot be undone.`,
                                                        () => {
                                                            // Delete the campaign
                                                            campaignService.deleteCampaign(currentCampaignId);

                                                            // Get updated campaigns list
                                                            const updatedCampaigns = campaignService.getCampaigns();

                                                            // If there are other campaigns, switch to the first one
                                                            // Otherwise, create a default campaign
                                                            let newCurrentId;
                                                            let newCampaignData;

                                                            if (updatedCampaigns.length > 0) {
                                                                newCurrentId = updatedCampaigns[0].id;
                                                                const campaign = campaignService.getCampaign(newCurrentId);
                                                                campaignService.setCurrentCampaign(newCurrentId);
                                                                const defaultData = {
                                                                    name: campaign?.name || 'New Campaign',
                                                                    description: campaign?.description || '',
                                                                    currentSession: 1,
                                                                    players: [],
                                                                    sessions: [],
                                                                    npcs: [],
                                                                    locations: [],
                                                                    plotThreads: [],
                                                                    quests: [],
                                                                    homebrew: { items: [], monsters: [], spells: [], lore: [] },
                                                                    selectedCreatures: [],
                                                                    selectedItems: [],
                                                                    selectedSpells: []
                                                                };
                                                                newCampaignData = campaign?.campaignData ? { ...defaultData, ...campaign.campaignData } : defaultData;
                                                            } else {
                                                                // No campaigns left, create a default one
                                                                const defaultCampaign = campaignService.createCampaign({ name: 'New Campaign' });
                                                                newCurrentId = defaultCampaign.id;
                                                                campaignService.setCurrentCampaign(newCurrentId);
                                                                updatedCampaigns.push(defaultCampaign);
                                                                newCampaignData = defaultCampaign.campaignData || {
                                                                    name: 'New Campaign',
                                                                    description: '',
                                                                    currentSession: 1,
                                                                    players: [],
                                                                    sessions: [],
                                                                    npcs: [],
                                                                    locations: [],
                                                                    plotThreads: [],
                                                                    quests: [],
                                                                    homebrew: { items: [], monsters: [], spells: [], lore: [] },
                                                                    selectedCreatures: [],
                                                                    selectedItems: [],
                                                                    selectedSpells: []
                                                                };
                                                            }

                                                            // Update state
                                                            setCampaigns(updatedCampaigns);
                                                            setCurrentCampaignId(newCurrentId);
                                                            setCampaignData(newCampaignData);
                                                        }
                                                    );
                                                }
                                            }}
                                            className="campaign-input"
                                            style={{
                                                padding: '10px 12px',
                                                cursor: 'pointer',
                                                fontSize: '13px',
                                                backgroundColor: campaigns.length <= 1 ? '#666' : '#dc3545',
                                                color: 'white',
                                                border: '1px solid #dc3545',
                                                display: 'flex',
                                                alignItems: 'center',
                                                justifyContent: 'center',
                                                flexShrink: 0,
                                                width: 'auto',
                                                minWidth: '80px',
                                                height: '42px',
                                                boxSizing: 'border-box'
                                            }}
                                            disabled={campaigns.length <= 1}
                                            title={campaigns.length <= 1 ? "Cannot delete the only campaign" : "Delete this campaign"}
                                        >
                                            <i className="fas fa-trash" style={{ fontSize: '12px', lineHeight: '1' }}></i>
                                        </button>
                                    </div>
                                </div>
                                <div className="campaign-field" style={{ marginBottom: '16px' }}>
                                    <label style={{ marginBottom: '6px' }}>Campaign Name</label>
                                    <input
                                        type="text"
                                        value={campaignData.name}
                                        onChange={(e) => {
                                            const newName = e.target.value;
                                            updateCampaignData({ name: newName });
                                            // Update campaign name in the service and dropdown
                                            if (currentCampaignId) {
                                                campaignService.updateCampaign(currentCampaignId, {
                                                    name: newName,
                                                    campaignData: { ...campaignData, name: newName }
                                                });
                                                // Update local campaigns state to refresh dropdown
                                                const idStr = String(currentCampaignId);
                                                setCampaigns(prev => prev.map(c =>
                                                    String(c.id) === idStr ? { ...c, name: newName } : c
                                                ));
                                            }
                                        }}
                                        className="campaign-input"
                                        placeholder="Enter campaign name..."
                                        style={{ width: '100%', backgroundColor: 'white' }}
                                    />
                                </div>
                                <div className="campaign-field">
                                    <label>Description</label>
                                    <textarea
                                        value={campaignData.description}
                                        onChange={(e) => updateCampaignData({ description: e.target.value })}
                                        className="campaign-textarea"
                                        placeholder="Describe your campaign setting, themes, and goals..."
                                        rows={4}
                                    />
                                </div>
                            </div>

                            <div className="campaign-stats-grid">
                                <div className="campaign-stat-card">
                                    <div className="stat-icon">
                                        <i className="fas fa-calendar-day"></i>
                                    </div>
                                    <div className="stat-content">
                                        <div className="stat-label">Current Session</div>
                                        <div className="stat-value">{campaignData.currentSession}</div>
                                    </div>
                                </div>
                                <div className="campaign-stat-card">
                                    <div className="stat-icon">
                                        <i className="fas fa-users"></i>
                                    </div>
                                    <div className="stat-content">
                                        <div className="stat-label">Active Players</div>
                                        <div className="stat-value">{campaignData.players.length}</div>
                                    </div>
                                </div>
                                <div className="campaign-stat-card">
                                    <div className="stat-icon">
                                        <i className="fas fa-map-marker-alt"></i>
                                    </div>
                                    <div className="stat-content">
                                        <div className="stat-label">Locations</div>
                                        <div className="stat-value">{campaignData.locations.length}</div>
                                    </div>
                                </div>
                                <div className="campaign-stat-card">
                                    <div className="stat-icon">
                                        <i className="fas fa-scroll"></i>
                                    </div>
                                    <div className="stat-content">
                                        <div className="stat-label">Plot Threads</div>
                                        <div className="stat-value">{campaignData.plotThreads.length}</div>
                                    </div>
                                </div>
                            </div>

                            <div className="campaign-players-section">
                                <div className="campaign-section-header">
                                    <h3>Player Roster</h3>
                                    <button className="campaign-add-btn" onClick={addPlayer}>
                                        <i className="fas fa-plus"></i>
                                        Add Player
                                    </button>
                                </div>
                                <div className="players-list">
                                    {(campaignData.players || []).length > 0 ? (
                                        (campaignData.players || []).map(player => (
                                            <div key={player.id} className="player-card-expanded">
                                                <div className="player-card-header">
                                                    <div className="player-avatar">
                                                        {(player.name || '?').charAt(0).toUpperCase()}
                                                    </div>
                                                    <div className="player-info">
                                                        <div className="player-header-row">
                                                            <input
                                                                type="text"
                                                                placeholder="Character name..."
                                                                value={player.name || ''}
                                                                onChange={(e) => updatePlayer(player.id, { name: e.target.value })}
                                                                className="player-name-input"
                                                            />
                                                            <button
                                                                className="player-remove-btn"
                                                                onClick={() => removePlayer(player.id)}
                                                                title="Remove player"
                                                            >
                                                                <i className="fas fa-times"></i>
                                                            </button>
                                                        </div>
                                                        <div className="player-details-row">
                                                            <input
                                                                type="text"
                                                                placeholder="Class..."
                                                                value={player.class || ''}
                                                                onChange={(e) => updatePlayer(player.id, { class: e.target.value })}
                                                                className="player-class-input"
                                                            />
                                                            <div className="player-level-group">
                                                                <span className="player-level-label">LVL</span>
                                                                <input
                                                                    type="number"
                                                                    min="1"
                                                                    max="20"
                                                                    value={player.level || 1}
                                                                    onChange={(e) => updatePlayer(player.id, { level: parseInt(e.target.value) || 1 })}
                                                                    className="player-level-input"
                                                                />
                                                            </div>
                                                            <select
                                                                value={player.status || 'active'}
                                                                onChange={(e) => updatePlayer(player.id, { status: e.target.value })}
                                                                className="player-status-select"
                                                            >
                                                                <option value="active">Active</option>
                                                                <option value="inactive">Inactive</option>
                                                                <option value="absent">Absent</option>
                                                            </select>
                                                        </div>
                                                    </div>
                                                </div>
                                                <div className="player-card-body">
                                                    <div className="player-fields-grid">
                                                        <div className="player-field">
                                                            <label>CHARACTER BACKGROUND</label>
                                                            <textarea
                                                                placeholder="Brief backstory, motivations..."
                                                                value={player.background || ''}
                                                                onChange={(e) => updatePlayer(player.id, { background: e.target.value })}
                                                                className="player-textarea"
                                                                rows={3}
                                                            />
                                                        </div>
                                                        <div className="player-field">
                                                            <label>PLAYER GOALS</label>
                                                            <textarea
                                                                placeholder="What the player wants to achieve..."
                                                                value={player.goals || ''}
                                                                onChange={(e) => updatePlayer(player.id, { goals: e.target.value })}
                                                                className="player-textarea"
                                                                rows={3}
                                                            />
                                                        </div>
                                                    </div>
                                                    <div className="player-field player-notes-field">
                                                        <label>GM NOTES (PRIVATE)</label>
                                                        <textarea
                                                            placeholder="Private notes about this player/character..."
                                                            value={player.notes || ''}
                                                            onChange={(e) => updatePlayer(player.id, { notes: e.target.value })}
                                                            className="player-textarea player-notes"
                                                            rows={3}
                                                        />
                                                    </div>
                                                </div>
                                            </div>
                                        ))
                                    ) : (
                                        <div className="players-placeholder">
                                            <i className="fas fa-users"></i>
                                            <p>No players added yet. Click "Add Player" to get started!</p>
                                        </div>
                                    )}
                                </div>
                            </div>

                        </div>
                    </div>
                );

            case 'sessions':
                return (
                    <div className="campaign-tab-content">
                        <div className="campaign-section-header">
                            <h3>Session Management</h3>
                            <button className="campaign-add-btn" onClick={addSession}>
                                <i className="fas fa-plus"></i>
                                New Session
                            </button>
                        </div>
                        <div className="sessions-list">
                            {(campaignData.sessions || []).length > 0 ? (
                                (campaignData.sessions || []).map(session => (
                                    <div key={session.id} className="session-card">
                                        <div className="session-header">
                                            <div className="session-title-section">
                                                <input
                                                    type="text"
                                                    value={session.title}
                                                    onChange={(e) => updateSession(session.id, { title: e.target.value })}
                                                    className="session-title-input"
                                                />
                                                <div className="session-meta">
                                                    <span className="session-number">#{session.number}</span>
                                                    <input
                                                        type="date"
                                                        value={session.date}
                                                        onChange={(e) => updateSession(session.id, { date: e.target.value })}
                                                        className="session-date-input"
                                                    />
                                                    <select
                                                        value={session.status}
                                                        onChange={(e) => updateSession(session.id, { status: e.target.value })}
                                                        className="session-status-select"
                                                    >
                                                        <option value="planned">Planned</option>
                                                        <option value="in-progress">In Progress</option>
                                                        <option value="completed">Completed</option>
                                                    </select>
                                                </div>
                                            </div>
                                            <button
                                                className="session-remove-btn"
                                                onClick={() => removeSession(session.id)}
                                                title="Delete session"
                                            >
                                                <i className="fas fa-trash"></i>
                                            </button>
                                        </div>
                                        <div className="session-content">
                                            <div className="session-field">
                                                <label>Session Notes</label>
                                                <textarea
                                                    value={session.notes}
                                                    onChange={(e) => updateSession(session.id, { notes: e.target.value })}
                                                    className="session-textarea"
                                                    placeholder="Plan objectives, encounters, plot points..."
                                                    rows={3}
                                                />
                                            </div>
                                            {session.status === 'completed' && (
                                                <div className="session-field">
                                                    <label>Session Summary</label>
                                                    <textarea
                                                        value={session.summary}
                                                        onChange={(e) => updateSession(session.id, { summary: e.target.value })}
                                                        className="session-textarea"
                                                        placeholder="What happened this session..."
                                                        rows={3}
                                                    />
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                ))
                            ) : (
                                <div className="session-placeholder">
                                    <i className="fas fa-calendar-plus"></i>
                                    <p>No sessions planned yet. Create your first session to get started!</p>
                                </div>
                            )}
                        </div>
                    </div>
                );

            case 'npcs':
                return (
                    <div className="campaign-tab-content">
                        <div className="campaign-section-header">
                            <h3>NPC Management</h3>
                            <button className="campaign-add-btn" onClick={addNPC}>
                                <i className="fas fa-plus"></i>
                                Add NPC
                            </button>
                        </div>
                        <div className="npcs-grid">
                            {(campaignData.npcs || []).length > 0 ? (
                                (campaignData.npcs || []).map(npc => (
                                    <div key={npc.id} className="npc-card">
                                        <div className="npc-header">
                                            <input
                                                type="text"
                                                value={npc.name}
                                                onChange={(e) => updateNPC(npc.id, { name: e.target.value })}
                                                className="npc-name-input"
                                            />
                                            <button
                                                className="npc-remove-btn"
                                                onClick={() => removeNPC(npc.id)}
                                                title="Remove NPC"
                                            >
                                                <i className="fas fa-times"></i>
                                            </button>
                                        </div>
                                        <div className="npc-content">
                                            <div className="npc-field">
                                                <label>Description</label>
                                                <textarea
                                                    value={npc.description}
                                                    onChange={(e) => updateNPC(npc.id, { description: e.target.value })}
                                                    className="npc-textarea"
                                                    placeholder="Physical description, personality..."
                                                    rows={2}
                                                />
                                            </div>
                                            <div className="npc-meta">
                                                <div className="npc-field">
                                                    <label>Location</label>
                                                    <input
                                                        type="text"
                                                        value={npc.location}
                                                        onChange={(e) => updateNPC(npc.id, { location: e.target.value })}
                                                        className="npc-input"
                                                        placeholder="Where they're found..."
                                                    />
                                                </div>
                                                <div className="npc-field">
                                                    <label>Relationship</label>
                                                    <select
                                                        value={npc.relationship}
                                                        onChange={(e) => updateNPC(npc.id, { relationship: e.target.value })}
                                                        className="npc-select"
                                                    >
                                                        <option value="ally">Ally</option>
                                                        <option value="neutral">Neutral</option>
                                                        <option value="enemy">Enemy</option>
                                                        <option value="unknown">Unknown</option>
                                                    </select>
                                                </div>
                                                <div className="npc-field">
                                                    <label>Plot Relevance</label>
                                                    <select
                                                        value={npc.plotRelevance}
                                                        onChange={(e) => updateNPC(npc.id, { plotRelevance: e.target.value })}
                                                        className="npc-select"
                                                    >
                                                        <option value="major">Major</option>
                                                        <option value="moderate">Moderate</option>
                                                        <option value="minor">Minor</option>
                                                        <option value="background">Background</option>
                                                    </select>
                                                </div>
                                            </div>
                                            <div className="npc-field">
                                                <label>Notes</label>
                                                <textarea
                                                    value={npc.notes}
                                                    onChange={(e) => updateNPC(npc.id, { notes: e.target.value })}
                                                    className="npc-textarea"
                                                    placeholder="Plot hooks, secrets, relationships..."
                                                    rows={2}
                                                />
                                            </div>
                                        </div>
                                    </div>
                                ))
                            ) : (
                                <div className="npc-placeholder">
                                    <i className="fas fa-user-plus"></i>
                                    <p>No NPCs created yet. Add NPCs to track relationships and story involvement!</p>
                                </div>
                            )}
                        </div>
                    </div>
                );

            case 'locations':
                return (
                    <div className="campaign-tab-content">
                        <div className="campaign-section-header">
                            <h3>Location Management</h3>
                            <button className="campaign-add-btn" onClick={addLocation}>
                                <i className="fas fa-plus"></i>
                                Add Location
                            </button>
                        </div>
                        <div className="locations-grid">
                            {(campaignData.locations || []).length > 0 ? (
                                (campaignData.locations || []).map(location => (
                                    <div key={location.id} className="location-card" style={{
                                        backgroundColor: '#f9f6f0',
                                        border: '2px solid #8b7355',
                                        borderRadius: '8px',
                                        padding: '15px',
                                        marginBottom: '15px'
                                    }}>
                                        <div className="location-header" style={{
                                            display: 'flex',
                                            justifyContent: 'space-between',
                                            alignItems: 'center',
                                            marginBottom: '12px'
                                        }}>
                                            <input
                                                type="text"
                                                value={location.name}
                                                onChange={(e) => updateLocation(location.id, { name: e.target.value })}
                                                className="location-name-input"
                                                style={{
                                                    flex: 1,
                                                    fontSize: '16px',
                                                    fontWeight: 'bold',
                                                    padding: '6px',
                                                    border: '2px solid #8b7355',
                                                    borderRadius: '4px',
                                                    fontFamily: 'inherit',
                                                    marginRight: '10px'
                                                }}
                                            />
                                            <button
                                                className="location-remove-btn"
                                                onClick={() => removeLocation(location.id)}
                                                title="Remove location"
                                                style={{
                                                    backgroundColor: '#8b0000',
                                                    color: 'white',
                                                    border: 'none',
                                                    borderRadius: '4px',
                                                    padding: '6px 10px',
                                                    cursor: 'pointer',
                                                    fontSize: '14px'
                                                }}
                                            >
                                                <i className="fas fa-times"></i>
                                            </button>
                                        </div>
                                        <div className="location-content">
                                            <div className="location-field" style={{ marginBottom: '10px' }}>
                                                <label style={{ display: 'block', marginBottom: '4px', fontWeight: 'bold', color: '#3a2f1a' }}>Description</label>
                                                <textarea
                                                    value={location.description}
                                                    onChange={(e) => updateLocation(location.id, { description: e.target.value })}
                                                    className="location-textarea"
                                                    placeholder="Describe the location..."
                                                    rows={2}
                                                    style={{
                                                        width: '100%',
                                                        padding: '6px',
                                                        border: '2px solid #8b7355',
                                                        borderRadius: '4px',
                                                        fontFamily: 'inherit',
                                                        boxSizing: 'border-box'
                                                    }}
                                                />
                                            </div>
                                            <div className="location-meta" style={{
                                                display: 'grid',
                                                gridTemplateColumns: '1fr 1fr',
                                                gap: '10px',
                                                marginBottom: '10px'
                                            }}>
                                                <div className="location-field">
                                                    <label style={{ display: 'block', marginBottom: '4px', fontWeight: 'bold', color: '#3a2f1a' }}>Type</label>
                                                    <select
                                                        value={location.type}
                                                        onChange={(e) => updateLocation(location.id, { type: e.target.value })}
                                                        className="location-select"
                                                        style={{
                                                            width: '100%',
                                                            padding: '6px',
                                                            border: '2px solid #8b7355',
                                                            borderRadius: '4px',
                                                            fontFamily: 'inherit'
                                                        }}
                                                    >
                                                        <option value="city">City</option>
                                                        <option value="town">Town</option>
                                                        <option value="village">Village</option>
                                                        <option value="dungeon">Dungeon</option>
                                                        <option value="landmark">Landmark</option>
                                                        <option value="wilderness">Wilderness</option>
                                                        <option value="other">Other</option>
                                                    </select>
                                                </div>
                                                <div className="location-field">
                                                    <label style={{ display: 'block', marginBottom: '4px', fontWeight: 'bold', color: '#3a2f1a' }}>Region</label>
                                                    <input
                                                        type="text"
                                                        value={location.region}
                                                        onChange={(e) => updateLocation(location.id, { region: e.target.value })}
                                                        className="location-input"
                                                        placeholder="Region..."
                                                        style={{
                                                            width: '100%',
                                                            padding: '6px',
                                                            border: '2px solid #8b7355',
                                                            borderRadius: '4px',
                                                            fontFamily: 'inherit',
                                                            boxSizing: 'border-box'
                                                        }}
                                                    />
                                                </div>
                                            </div>
                                            <div className="location-field" style={{ marginBottom: '10px' }}>
                                                <label style={{ display: 'block', marginBottom: '4px', fontWeight: 'bold', color: '#3a2f1a' }}>Notable Features</label>
                                                <textarea
                                                    value={location.notableFeatures}
                                                    onChange={(e) => updateLocation(location.id, { notableFeatures: e.target.value })}
                                                    className="location-textarea"
                                                    placeholder="Key features, landmarks, points of interest..."
                                                    rows={2}
                                                    style={{
                                                        width: '100%',
                                                        padding: '6px',
                                                        border: '2px solid #8b7355',
                                                        borderRadius: '4px',
                                                        fontFamily: 'inherit',
                                                        boxSizing: 'border-box'
                                                    }}
                                                />
                                            </div>
                                            <div className="location-field">
                                                <label style={{ display: 'block', marginBottom: '4px', fontWeight: 'bold', color: '#3a2f1a' }}>Notes</label>
                                                <textarea
                                                    value={location.notes}
                                                    onChange={(e) => updateLocation(location.id, { notes: e.target.value })}
                                                    className="location-textarea"
                                                    placeholder="Plot hooks, secrets, connections to other locations..."
                                                    rows={2}
                                                    style={{
                                                        width: '100%',
                                                        padding: '6px',
                                                        border: '2px solid #8b7355',
                                                        borderRadius: '4px',
                                                        fontFamily: 'inherit',
                                                        boxSizing: 'border-box'
                                                    }}
                                                />
                                            </div>
                                        </div>
                                    </div>
                                ))
                            ) : (
                                <div className="location-placeholder">
                                    <i className="fas fa-map-plus"></i>
                                    <p>No locations created yet. Build your world by adding important places!</p>
                                </div>
                            )}
                        </div>
                    </div>
                );

            case 'plots':
                return (
                    <div className="campaign-tab-content">
                        <div className="campaign-section-header">
                            <h3>Plot Thread Management</h3>
                            <button className="campaign-add-btn" onClick={addPlotThread}>
                                <i className="fas fa-plus"></i>
                                New Plot Thread
                            </button>
                        </div>
                        <div className="plots-list">
                            {(campaignData.plotThreads || []).length > 0 ? (
                                (campaignData.plotThreads || []).map(plotThread => (
                                    <div key={plotThread.id} className="plot-card" style={{
                                        backgroundColor: '#f9f6f0',
                                        border: '2px solid #8b7355',
                                        borderRadius: '8px',
                                        padding: '15px',
                                        marginBottom: '15px'
                                    }}>
                                        <div className="plot-header" style={{
                                            display: 'flex',
                                            justifyContent: 'space-between',
                                            alignItems: 'center',
                                            marginBottom: '12px'
                                        }}>
                                            <input
                                                type="text"
                                                value={plotThread.title}
                                                onChange={(e) => updatePlotThread(plotThread.id, { title: e.target.value })}
                                                className="plot-title-input"
                                                style={{
                                                    flex: 1,
                                                    fontSize: '16px',
                                                    fontWeight: 'bold',
                                                    padding: '6px',
                                                    border: '2px solid #8b7355',
                                                    borderRadius: '4px',
                                                    fontFamily: 'inherit',
                                                    marginRight: '10px'
                                                }}
                                            />
                                            <button
                                                className="plot-remove-btn"
                                                onClick={() => removePlotThread(plotThread.id)}
                                                title="Remove plot thread"
                                                style={{
                                                    backgroundColor: '#8b0000',
                                                    color: 'white',
                                                    border: 'none',
                                                    borderRadius: '4px',
                                                    padding: '6px 10px',
                                                    cursor: 'pointer',
                                                    fontSize: '14px'
                                                }}
                                            >
                                                <i className="fas fa-times"></i>
                                            </button>
                                        </div>
                                        <div className="plot-content">
                                            <div className="plot-field" style={{ marginBottom: '10px' }}>
                                                <label style={{ display: 'block', marginBottom: '4px', fontWeight: 'bold', color: '#3a2f1a' }}>Description</label>
                                                <textarea
                                                    value={plotThread.description}
                                                    onChange={(e) => updatePlotThread(plotThread.id, { description: e.target.value })}
                                                    className="plot-textarea"
                                                    placeholder="Describe the plot thread..."
                                                    rows={3}
                                                    style={{
                                                        width: '100%',
                                                        padding: '6px',
                                                        border: '2px solid #8b7355',
                                                        borderRadius: '4px',
                                                        fontFamily: 'inherit',
                                                        boxSizing: 'border-box'
                                                    }}
                                                />
                                            </div>
                                            <div className="plot-meta" style={{
                                                display: 'grid',
                                                gridTemplateColumns: '1fr 1fr',
                                                gap: '10px',
                                                marginBottom: '10px'
                                            }}>
                                                <div className="plot-field">
                                                    <label style={{ display: 'block', marginBottom: '4px', fontWeight: 'bold', color: '#3a2f1a' }}>Status</label>
                                                    <select
                                                        value={plotThread.status}
                                                        onChange={(e) => updatePlotThread(plotThread.id, { status: e.target.value })}
                                                        className="plot-select"
                                                        style={{
                                                            width: '100%',
                                                            padding: '6px',
                                                            border: '2px solid #8b7355',
                                                            borderRadius: '4px',
                                                            fontFamily: 'inherit'
                                                        }}
                                                    >
                                                        <option value="active">Active</option>
                                                        <option value="on-hold">On Hold</option>
                                                        <option value="resolved">Resolved</option>
                                                        <option value="abandoned">Abandoned</option>
                                                    </select>
                                                </div>
                                                <div className="plot-field">
                                                    <label style={{ display: 'block', marginBottom: '4px', fontWeight: 'bold', color: '#3a2f1a' }}>Priority</label>
                                                    <select
                                                        value={plotThread.priority}
                                                        onChange={(e) => updatePlotThread(plotThread.id, { priority: e.target.value })}
                                                        className="plot-select"
                                                        style={{
                                                            width: '100%',
                                                            padding: '6px',
                                                            border: '2px solid #8b7355',
                                                            borderRadius: '4px',
                                                            fontFamily: 'inherit'
                                                        }}
                                                    >
                                                        <option value="low">Low</option>
                                                        <option value="medium">Medium</option>
                                                        <option value="high">High</option>
                                                        <option value="critical">Critical</option>
                                                    </select>
                                                </div>
                                            </div>
                                            <div className="plot-field" style={{ marginBottom: '10px' }}>
                                                <label style={{ display: 'block', marginBottom: '4px', fontWeight: 'bold', color: '#3a2f1a' }}>Related NPCs</label>
                                                <input
                                                    type="text"
                                                    value={Array.isArray(plotThread.relatedNPCs) ? plotThread.relatedNPCs.join(', ') : (plotThread.relatedNPCs || '')}
                                                    onChange={(e) => updatePlotThread(plotThread.id, {
                                                        relatedNPCs: e.target.value ? e.target.value.split(',').map(n => n.trim()).filter(n => n) : []
                                                    })}
                                                    className="plot-input"
                                                    placeholder="NPC names (comma-separated)..."
                                                    style={{
                                                        width: '100%',
                                                        padding: '6px',
                                                        border: '2px solid #8b7355',
                                                        borderRadius: '4px',
                                                        fontFamily: 'inherit',
                                                        boxSizing: 'border-box'
                                                    }}
                                                />
                                            </div>
                                            <div className="plot-field" style={{ marginBottom: '10px' }}>
                                                <label style={{ display: 'block', marginBottom: '4px', fontWeight: 'bold', color: '#3a2f1a' }}>Related Locations</label>
                                                <input
                                                    type="text"
                                                    value={Array.isArray(plotThread.relatedLocations) ? plotThread.relatedLocations.join(', ') : (plotThread.relatedLocations || '')}
                                                    onChange={(e) => updatePlotThread(plotThread.id, {
                                                        relatedLocations: e.target.value ? e.target.value.split(',').map(l => l.trim()).filter(l => l) : []
                                                    })}
                                                    className="plot-input"
                                                    placeholder="Location names (comma-separated)..."
                                                    style={{
                                                        width: '100%',
                                                        padding: '6px',
                                                        border: '2px solid #8b7355',
                                                        borderRadius: '4px',
                                                        fontFamily: 'inherit',
                                                        boxSizing: 'border-box'
                                                    }}
                                                />
                                            </div>
                                            <div className="plot-field">
                                                <label style={{ display: 'block', marginBottom: '4px', fontWeight: 'bold', color: '#3a2f1a' }}>Notes</label>
                                                <textarea
                                                    value={plotThread.notes}
                                                    onChange={(e) => updatePlotThread(plotThread.id, { notes: e.target.value })}
                                                    className="plot-textarea"
                                                    placeholder="Progress, key events, connections to other plot threads..."
                                                    rows={3}
                                                    style={{
                                                        width: '100%',
                                                        padding: '6px',
                                                        border: '2px solid #8b7355',
                                                        borderRadius: '4px',
                                                        fontFamily: 'inherit',
                                                        boxSizing: 'border-box'
                                                    }}
                                                />
                                            </div>
                                        </div>
                                    </div>
                                ))
                            ) : (
                                <div className="plot-placeholder">
                                    <i className="fas fa-project-diagram"></i>
                                    <p>No plot threads tracked yet. Create storylines to keep your campaign organized!</p>
                                </div>
                            )}
                        </div>
                    </div>
                );

            case 'shareables':
                return (
                    <div className="campaign-tab-content">
                        <div className="shareables-workspace">
                            {/* Create New Shareable */}
                            <div className="shareables-creator">
                                <h3 className="section-title">
                                    <i className="fas fa-plus-circle"></i>
                                    Create Shareable Content
                                </h3>

                                <div className="shareable-form">
                                    <div className="form-row">
                                        <div className="form-group">
                                            <label>Type</label>
                                            <select
                                                value={newShareableType}
                                                onChange={(e) => setNewShareableType(e.target.value)}
                                                className="shareable-select"
                                            >
                                                <option value="text">Text Document</option>
                                                <option value="image">Image</option>
                                            </select>
                                        </div>

                                        <div className="form-group">
                                            <label>Title</label>
                                            <input
                                                type="text"
                                                value={newShareableTitle}
                                                onChange={(e) => setNewShareableTitle(e.target.value)}
                                                placeholder="Enter title..."
                                                className="shareable-input"
                                            />
                                        </div>

                                        {newShareableType === 'text' && (
                                            <div className="form-group">
                                                <label>Style</label>
                                                <select
                                                    value={newShareableBackground}
                                                    onChange={(e) => setNewShareableBackground(e.target.value)}
                                                    className="shareable-select"
                                                >
                                                    <option value="parchment">Parchment</option>
                                                    <option value="aged">Aged Paper</option>
                                                    <option value="bloodstained">Bloodstained</option>
                                                    <option value="dark">Dark Letter</option>
                                                </select>
                                            </div>
                                        )}
                                    </div>

                                    {newShareableType === 'text' ? (
                                        <div className="form-group">
                                            <label>Content</label>
                                            <textarea
                                                value={newShareableContent}
                                                onChange={(e) => setNewShareableContent(e.target.value)}
                                                placeholder="Write your document content here..."
                                                className="shareable-textarea"
                                                rows={6}
                                            />
                                        </div>
                                    ) : (
                                        <div className="form-group">
                                            <label>Image</label>
                                            <div className="shareable-image-input">
                                                <input
                                                    ref={shareableFileInputRef}
                                                    type="file"
                                                    accept="image/*"
                                                    onChange={(e) => {
                                                        const file = e.target.files?.[0];
                                                        if (file) {
                                                            const reader = new FileReader();
                                                            reader.onload = (event) => {
                                                                setNewShareableContent(event.target.result);
                                                            };
                                                            reader.readAsDataURL(file);
                                                        }
                                                    }}
                                                    style={{ display: 'none' }}
                                                />
                                                <button
                                                    className="upload-btn"
                                                    onClick={() => shareableFileInputRef.current?.click()}
                                                >
                                                    <i className="fas fa-upload"></i>
                                                    Choose Image
                                                </button>
                                                {newShareableContent && (
                                                    <img
                                                        src={newShareableContent}
                                                        alt="Preview"
                                                        className="shareable-preview"
                                                    />
                                                )}
                                            </div>
                                        </div>
                                    )}

                                    <button
                                        className="shareable-add-btn"
                                        onClick={() => {
                                            if (newShareableTitle && newShareableContent) {
                                                addShareable({
                                                    type: newShareableType,
                                                    title: newShareableTitle,
                                                    content: newShareableContent,
                                                    background: newShareableBackground
                                                });
                                                setNewShareableTitle('');
                                                setNewShareableContent('');
                                            }
                                        }}
                                        disabled={!newShareableTitle || !newShareableContent}
                                    >
                                        <i className="fas fa-plus"></i>
                                        Add to Library
                                    </button>
                                </div>
                            </div>

                            {/* Shareables Library */}
                            <div className="shareables-library">
                                <h3 className="section-title">
                                    <i className="fas fa-folder-open"></i>
                                    Shareable Library ({shareables.length})
                                </h3>

                                {shareables.length === 0 ? (
                                    <div className="shareables-empty">
                                        <i className="fas fa-share-alt"></i>
                                        <p>No shareables created yet</p>
                                        <span>Create documents and images to share with your players</span>
                                    </div>
                                ) : (
                                    <div className="shareables-grid">
                                        {shareables.map(shareable => (
                                            <div key={shareable.id} className={`shareable-card ${shareable.type}`}>
                                                <div className="shareable-preview-thumb">
                                                    {shareable.type === 'image' ? (
                                                        <img src={shareable.content} alt={shareable.title} />
                                                    ) : (
                                                        <div className={`document-preview ${shareable.background}`}>
                                                            <i className="fas fa-file-alt"></i>
                                                        </div>
                                                    )}
                                                </div>
                                                <div className="shareable-info">
                                                    <span className="shareable-title">{shareable.title}</span>
                                                    <span className="shareable-type">
                                                        {shareable.type === 'image' ? 'Image' : 'Document'}
                                                    </span>
                                                </div>
                                                <div className="shareable-actions">
                                                    <button
                                                        className="action-btn show"
                                                        onClick={() => showToPlayers({
                                                            type: shareable.type,
                                                            title: shareable.title,
                                                            content: shareable.content,
                                                            background: shareable.background,
                                                            description: ''
                                                        })}
                                                        title="Show to Players"
                                                    >
                                                        <i className="fas fa-eye"></i>
                                                    </button>
                                                    <button
                                                        className="action-btn delete"
                                                        onClick={() => removeShareable(shareable.id)}
                                                        title="Delete"
                                                    >
                                                        <i className="fas fa-trash"></i>
                                                    </button>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                );

            case 'homebrew':
                return (
                    <div className="campaign-tab-content">
                        <div className="homebrew-workspace">
                            {/* Homebrew Sub-navigation */}
                            <div className="homebrew-subtabs">
                                <button
                                    className={`homebrew-subtab ${homebrewSubTab === 'items' ? 'active' : ''}`}
                                    onClick={() => setHomebrewSubTab('items')}
                                >
                                    <i className="fas fa-sword"></i>
                                    Items ({((campaignData.selectedItems || []).length) + (Array.isArray(campaignData.homebrew?.items) ? campaignData.homebrew.items.length : (campaignData.homebrew?.items ? Object.keys(campaignData.homebrew.items).length : 0))})
                                </button>
                                <button
                                    className={`homebrew-subtab ${homebrewSubTab === 'monsters' ? 'active' : ''}`}
                                    onClick={() => setHomebrewSubTab('monsters')}
                                >
                                    <i className="fas fa-dragon"></i>
                                    Monsters ({((campaignData.selectedCreatures || []).length) + (Array.isArray(campaignData.homebrew?.monsters) ? campaignData.homebrew.monsters.length : (campaignData.homebrew?.monsters ? Object.keys(campaignData.homebrew.monsters).length : 0))})
                                </button>
                                <button
                                    className={`homebrew-subtab ${homebrewSubTab === 'spells' ? 'active' : ''}`}
                                    onClick={() => setHomebrewSubTab('spells')}
                                >
                                    <i className="fas fa-hat-wizard"></i>
                                    Spells ({((campaignData.selectedSpells || []).length) + (Array.isArray(campaignData.homebrew?.spells) ? campaignData.homebrew.spells.length : (campaignData.homebrew?.spells ? Object.keys(campaignData.homebrew.spells).length : 0))})
                                </button>
                                <button
                                    className={`homebrew-subtab ${homebrewSubTab === 'lore' ? 'active' : ''}`}
                                    onClick={() => setHomebrewSubTab('lore')}
                                >
                                    <i className="fas fa-book-open"></i>
                                    Lore ({Array.isArray(campaignData.homebrew?.lore) ? campaignData.homebrew.lore.length : (campaignData.homebrew?.lore ? Object.keys(campaignData.homebrew.lore).length : 0)})
                                </button>
                            </div>

                            {/* Homebrew Content */}
                            <div className="homebrew-content">
                                {homebrewSubTab === 'items' && (
                                    <div className="homebrew-section">
                                        <div className="campaign-section-header">
                                            <h3>Campaign Items</h3>
                                            <div className="homebrew-actions">
                                                <button className="campaign-add-btn library-btn" onClick={addItemFromLibrary}>
                                                    <i className="fas fa-book"></i>
                                                    Browse Library
                                                </button>
                                                <button className="campaign-add-btn homebrew-wizard-btn" onClick={addHomebrewItem}>
                                                    <i className="fas fa-plus"></i>
                                                    Create Custom
                                                </button>
                                            </div>
                                        </div>

                                        {/* Library Items */}
                                        {(campaignData.selectedItems || []).length > 0 && (
                                            <div className="library-section">
                                                <h4 className="library-section-title">
                                                    <i className="fas fa-book"></i> From Library
                                                </h4>
                                                <div className="homebrew-grid">
                                                    {(campaignData.selectedItems || []).map(item => (
                                                        <div
                                                            key={item.id}
                                                            className="homebrew-card library-card"
                                                            onMouseEnter={(e) => handleMouseEnter(e, item, null, null)}
                                                            onMouseMove={handleMouseMove}
                                                            onMouseLeave={handleMouseLeave}
                                                        >
                                                            <div className="homebrew-card-header">
                                                                <span className="library-badge"><i className="fas fa-link"></i></span>
                                                                <span className="homebrew-name-display">{item.name}</span>
                                                                <span className={`rarity-badge rarity-${item.quality}`}>{item.quality}</span>
                                                                <button className="homebrew-remove-btn" onClick={() => removeLibraryItem(item.id)}>
                                                                    <i className="fas fa-times"></i>
                                                                </button>
                                                            </div>
                                                            <div className="homebrew-card-body">
                                                                <div className="library-item-tags">
                                                                    <span className="library-tag">{formatTag(item.type)}</span>
                                                                    {item.subtype && <span className="library-tag">{formatTag(item.subtype)}</span>}
                                                                </div>
                                                                <textarea
                                                                    value={item.notes || ''}
                                                                    onChange={(e) => {
                                                                        const updated = (campaignData.selectedItems || []).map(i =>
                                                                            i.id === item.id ? { ...i, notes: e.target.value } : i
                                                                        );
                                                                        updateCampaignData({ selectedItems: updated });
                                                                    }}
                                                                    placeholder="Campaign notes for this item..."
                                                                    className="homebrew-textarea"
                                                                    rows={2}
                                                                />
                                                            </div>
                                                        </div>
                                                    ))}
                                                </div>
                                            </div>
                                        )}

                                        {/* Custom Homebrew Items */}
                                        {(campaignData.homebrew?.items || []).length > 0 && (
                                            <h4 className="library-section-title">
                                                <i className="fas fa-hammer"></i> Custom Homebrew
                                            </h4>
                                        )}
                                        <div className="homebrew-grid">
                                            {(campaignData.homebrew?.items || []).length > 0 ? (
                                                (campaignData.homebrew?.items || []).map(item => (
                                                    <div key={item.id} className="homebrew-card">
                                                        <div className="homebrew-card-header">
                                                            <input
                                                                type="text"
                                                                value={item.name}
                                                                onChange={(e) => updateHomebrewItem(item.id, { name: e.target.value })}
                                                                className="homebrew-name-input"
                                                            />
                                                            <span className={`rarity-badge rarity-${item.rarity}`}>{item.rarity}</span>
                                                            <button className="homebrew-remove-btn" onClick={() => removeHomebrewItem(item.id)}>
                                                                <i className="fas fa-times"></i>
                                                            </button>
                                                        </div>
                                                        <div className="homebrew-card-body">
                                                            <div className="homebrew-field-row">
                                                                <select
                                                                    value={item.type}
                                                                    onChange={(e) => updateHomebrewItem(item.id, { type: e.target.value })}
                                                                    className="homebrew-select"
                                                                >
                                                                    <option value="weapon">Weapon</option>
                                                                    <option value="armor">Armor</option>
                                                                    <option value="consumable">Consumable</option>
                                                                    <option value="accessory">Accessory</option>
                                                                    <option value="tool">Tool</option>
                                                                    <option value="wondrous">Wondrous Item</option>
                                                                </select>
                                                                <select
                                                                    value={item.rarity}
                                                                    onChange={(e) => updateHomebrewItem(item.id, { rarity: e.target.value })}
                                                                    className="homebrew-select"
                                                                >
                                                                    <option value="common">Common</option>
                                                                    <option value="uncommon">Uncommon</option>
                                                                    <option value="rare">Rare</option>
                                                                    <option value="epic">Epic</option>
                                                                    <option value="legendary">Legendary</option>
                                                                </select>
                                                            </div>
                                                            <textarea
                                                                value={item.description}
                                                                onChange={(e) => updateHomebrewItem(item.id, { description: e.target.value })}
                                                                placeholder="Item description and effects..."
                                                                className="homebrew-textarea"
                                                                rows={3}
                                                            />
                                                        </div>
                                                    </div>
                                                ))
                                            ) : (
                                                <div className="homebrew-placeholder">
                                                    <i className="fas fa-treasure-chest"></i>
                                                    <p>No custom items yet. Create homebrew items for your campaign!</p>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                )}

                                {homebrewSubTab === 'monsters' && (
                                    <div className="homebrew-section">
                                        <div className="campaign-section-header">
                                            <h3>Campaign Creatures</h3>
                                            <div className="homebrew-actions">
                                                <button className="campaign-add-btn library-btn" onClick={addCreatureFromLibrary}>
                                                    <i className="fas fa-book"></i>
                                                    Browse Library
                                                </button>
                                                <button className="campaign-add-btn homebrew-wizard-btn" onClick={addHomebrewMonster}>
                                                    <i className="fas fa-plus"></i>
                                                    Create Custom
                                                </button>
                                            </div>
                                        </div>

                                        {/* Library Creatures */}
                                        {(campaignData.selectedCreatures || []).length > 0 && (
                                            <div className="library-section">
                                                <h4 className="library-section-title">
                                                    <i className="fas fa-book"></i> From Library
                                                </h4>
                                                <div className="homebrew-grid">
                                                    {(campaignData.selectedCreatures || []).map(creature => (
                                                        <div
                                                            key={creature.id}
                                                            className="homebrew-card monster-card library-card"
                                                            onMouseEnter={(e) => handleMouseEnter(e, null, creature, null)}
                                                            onMouseMove={handleMouseMove}
                                                            onMouseLeave={handleMouseLeave}
                                                        >
                                                            <div className="homebrew-card-header">
                                                                <span className="library-badge"><i className="fas fa-link"></i></span>
                                                                <span className="homebrew-name-display">{creature.name}</span>
                                                                <button className="homebrew-remove-btn" onClick={() => removeLibraryCreature(creature.id)}>
                                                                    <i className="fas fa-times"></i>
                                                                </button>
                                                            </div>
                                                            <div className="homebrew-card-body">
                                                                <div className="library-item-tags">
                                                                    <span className="library-tag">{formatTag(creature.type)}</span>
                                                                    <span className="library-tag">{formatTag(creature.size)}</span>
                                                                    {creature.hp > 0 && <span className="library-tag">HP {creature.hp}</span>}
                                                                </div>
                                                                <textarea
                                                                    value={creature.notes || ''}
                                                                    onChange={(e) => {
                                                                        const updated = (campaignData.selectedCreatures || []).map(c =>
                                                                            c.id === creature.id ? { ...c, notes: e.target.value } : c
                                                                        );
                                                                        updateCampaignData({ selectedCreatures: updated });
                                                                    }}
                                                                    placeholder="Campaign notes for this creature..."
                                                                    className="homebrew-textarea"
                                                                    rows={2}
                                                                />
                                                            </div>
                                                        </div>
                                                    ))}
                                                </div>
                                            </div>
                                        )}

                                        {/* Custom Homebrew Monsters */}
                                        {(campaignData.homebrew?.monsters || []).length > 0 && (
                                            <h4 className="library-section-title">
                                                <i className="fas fa-hammer"></i> Custom Homebrew
                                            </h4>
                                        )}
                                        <div className="homebrew-grid">
                                            {(campaignData.homebrew?.monsters || []).length > 0 ? (
                                                (campaignData.homebrew?.monsters || []).map(monster => (
                                                    <div key={monster.id} className="homebrew-card monster-card">
                                                        <div className="homebrew-card-header">
                                                            <input
                                                                type="text"
                                                                value={monster.name}
                                                                onChange={(e) => updateHomebrewMonster(monster.id, { name: e.target.value })}
                                                                className="homebrew-name-input"
                                                            />
                                                            <button className="homebrew-remove-btn" onClick={() => removeHomebrewMonster(monster.id)}>
                                                                <i className="fas fa-times"></i>
                                                            </button>
                                                        </div>
                                                        <div className="homebrew-card-body">
                                                            <div className="homebrew-field-row">
                                                                <select
                                                                    value={monster.size}
                                                                    onChange={(e) => updateHomebrewMonster(monster.id, { size: e.target.value })}
                                                                    className="homebrew-select"
                                                                >
                                                                    <option value="tiny">Tiny</option>
                                                                    <option value="small">Small</option>
                                                                    <option value="medium">Medium</option>
                                                                    <option value="large">Large</option>
                                                                    <option value="huge">Huge</option>
                                                                    <option value="gargantuan">Gargantuan</option>
                                                                </select>
                                                                <select
                                                                    value={monster.type}
                                                                    onChange={(e) => updateHomebrewMonster(monster.id, { type: e.target.value })}
                                                                    className="homebrew-select"
                                                                >
                                                                    <option value="beast">Beast</option>
                                                                    <option value="humanoid">Humanoid</option>
                                                                    <option value="undead">Undead</option>
                                                                    <option value="fiend">Fiend</option>
                                                                    <option value="dragon">Dragon</option>
                                                                    <option value="aberration">Aberration</option>
                                                                    <option value="construct">Construct</option>
                                                                    <option value="elemental">Elemental</option>
                                                                    <option value="fey">Fey</option>
                                                                    <option value="giant">Giant</option>
                                                                    <option value="monstrosity">Monstrosity</option>
                                                                    <option value="ooze">Ooze</option>
                                                                    <option value="plant">Plant</option>
                                                                    <option value="celestial">Celestial</option>
                                                                </select>
                                                            </div>
                                                            <div className="homebrew-field-row">
                                                                <input
                                                                    type="text"
                                                                    value={monster.hp || ''}
                                                                    onChange={(e) => updateHomebrewMonster(monster.id, { hp: e.target.value })}
                                                                    placeholder="HP (e.g., 45 or 6d10+12)"
                                                                    className="homebrew-input"
                                                                />
                                                                <input
                                                                    type="text"
                                                                    value={monster.ac || ''}
                                                                    onChange={(e) => updateHomebrewMonster(monster.id, { ac: e.target.value })}
                                                                    placeholder="Armor"
                                                                    className="homebrew-input-small"
                                                                />
                                                            </div>
                                                            <textarea
                                                                value={monster.description}
                                                                onChange={(e) => updateHomebrewMonster(monster.id, { description: e.target.value })}
                                                                placeholder="Description, abilities, tactics..."
                                                                className="homebrew-textarea"
                                                                rows={3}
                                                            />
                                                        </div>
                                                    </div>
                                                ))
                                            ) : (
                                                <div className="homebrew-placeholder">
                                                    <i className="fas fa-skull"></i>
                                                    <p>No custom monsters yet. Create fearsome foes for your party!</p>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                )}

                                {homebrewSubTab === 'spells' && (
                                    <div className="homebrew-section">
                                        <div className="campaign-section-header">
                                            <h3>Campaign Spells</h3>
                                            <div className="homebrew-actions">
                                                <button className="campaign-add-btn library-btn" onClick={addSpellFromLibrary}>
                                                    <i className="fas fa-book"></i>
                                                    Browse Library
                                                </button>
                                                <button className="campaign-add-btn homebrew-wizard-btn" onClick={addHomebrewSpell}>
                                                    <i className="fas fa-plus"></i>
                                                    Create Custom
                                                </button>
                                            </div>
                                        </div>

                                        {/* Library Spells */}
                                        {(campaignData.selectedSpells || []).length > 0 && (
                                            <div className="library-section">
                                                <h4 className="library-section-title">
                                                    <i className="fas fa-book"></i> From Library
                                                </h4>
                                                <div className="homebrew-grid">
                                                    {(campaignData.selectedSpells || []).map(spell => (
                                                        <div
                                                            key={spell.id}
                                                            className="homebrew-card spell-card library-card"
                                                            onMouseEnter={(e) => handleMouseEnter(e, null, null, spell)}
                                                            onMouseMove={handleMouseMove}
                                                            onMouseLeave={handleMouseLeave}
                                                        >
                                                            <div className="homebrew-card-header">
                                                                <span className="library-badge"><i className="fas fa-link"></i></span>
                                                                <span className="homebrew-name-display">{spell.name}</span>
                                                                <span className="spell-level-badge">
                                                                    {spell.level === 0 ? 'Cantrip' : `Lvl ${spell.level}`}
                                                                </span>
                                                                <button className="homebrew-remove-btn" onClick={() => removeLibrarySpell(spell.id)}>
                                                                    <i className="fas fa-times"></i>
                                                                </button>
                                                            </div>
                                                            <div className="homebrew-card-body">
                                                                <div className="library-item-tags">
                                                                    <span className="library-tag">{formatTag(spell.school || 'Spell')}</span>
                                                                </div>
                                                                <textarea
                                                                    value={spell.notes || ''}
                                                                    onChange={(e) => {
                                                                        const updated = (campaignData.selectedSpells || []).map(s =>
                                                                            s.id === spell.id ? { ...s, notes: e.target.value } : s
                                                                        );
                                                                        updateCampaignData({ selectedSpells: updated });
                                                                    }}
                                                                    placeholder="Campaign notes for this spell..."
                                                                    className="homebrew-textarea"
                                                                    rows={2}
                                                                />
                                                            </div>
                                                        </div>
                                                    ))}
                                                </div>
                                            </div>
                                        )}

                                        {/* Custom Homebrew Spells */}
                                        {(campaignData.homebrew?.spells || []).length > 0 && (
                                            <h4 className="library-section-title">
                                                <i className="fas fa-hammer"></i> Custom Homebrew
                                            </h4>
                                        )}
                                        <div className="homebrew-grid">
                                            {(campaignData.homebrew?.spells || []).length > 0 ? (
                                                (campaignData.homebrew?.spells || []).map(spell => (
                                                    <div key={spell.id} className="homebrew-card spell-card">
                                                        <div className="homebrew-card-header">
                                                            <input
                                                                type="text"
                                                                value={spell.name}
                                                                onChange={(e) => updateHomebrewSpell(spell.id, { name: e.target.value })}
                                                                className="homebrew-name-input"
                                                            />
                                                            <span className="spell-level-badge">Lvl {spell.level}</span>
                                                            <button className="homebrew-remove-btn" onClick={() => removeHomebrewSpell(spell.id)}>
                                                                <i className="fas fa-times"></i>
                                                            </button>
                                                        </div>
                                                        <div className="homebrew-card-body">
                                                            <div className="homebrew-field-row">
                                                                <select
                                                                    value={spell.level}
                                                                    onChange={(e) => updateHomebrewSpell(spell.id, { level: parseInt(e.target.value) })}
                                                                    className="homebrew-select"
                                                                >
                                                                    <option value="0">Cantrip</option>
                                                                    <option value="1">1st Level</option>
                                                                    <option value="2">2nd Level</option>
                                                                    <option value="3">3rd Level</option>
                                                                    <option value="4">4th Level</option>
                                                                    <option value="5">5th Level</option>
                                                                    <option value="6">6th Level</option>
                                                                    <option value="7">7th Level</option>
                                                                    <option value="8">8th Level</option>
                                                                    <option value="9">9th Level</option>
                                                                </select>
                                                                <select
                                                                    value={spell.school}
                                                                    onChange={(e) => updateHomebrewSpell(spell.id, { school: e.target.value })}
                                                                    className="homebrew-select"
                                                                >
                                                                    <option value="physical">Physical</option>
                                                                    <option value="ember">Ember</option>
                                                                    <option value="rime">Rime</option>
                                                                    <option value="storm">Storm</option>
                                                                    <option value="arcane">Arcane</option>
                                                                    <option value="primal">Primal</option>
                                                                    <option value="blight">Blight</option>
                                                                    <option value="wyrd">Wyrd</option>
                                                                     <option value="sacred">Sacred</option>
                                                                </select>
                                                            </div>
                                                            <div className="homebrew-field-row">
                                                                <input
                                                                    type="text"
                                                                    value={spell.castingTime}
                                                                    onChange={(e) => updateHomebrewSpell(spell.id, { castingTime: e.target.value })}
                                                                    placeholder="Casting Time"
                                                                    className="homebrew-input"
                                                                />
                                                                <input
                                                                    type="text"
                                                                    value={spell.range}
                                                                    onChange={(e) => updateHomebrewSpell(spell.id, { range: e.target.value })}
                                                                    placeholder="Range"
                                                                    className="homebrew-input"
                                                                />
                                                            </div>
                                                            <textarea
                                                                value={spell.description}
                                                                onChange={(e) => updateHomebrewSpell(spell.id, { description: e.target.value })}
                                                                placeholder="Spell effect description..."
                                                                className="homebrew-textarea"
                                                                rows={3}
                                                            />
                                                        </div>
                                                    </div>
                                                ))
                                            ) : (
                                                <div className="homebrew-placeholder">
                                                    <i className="fas fa-magic"></i>
                                                    <p>No custom spells yet. Craft unique magical abilities!</p>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                )}

                                {homebrewSubTab === 'lore' && (
                                    <div className="homebrew-section">
                                        <div className="campaign-section-header">
                                            <h3>World Lore & History</h3>
                                            <button className="campaign-add-btn" onClick={addLoreArticle}>
                                                <i className="fas fa-plus"></i>
                                                New Article
                                            </button>
                                        </div>
                                        <div className="lore-articles-list">
                                            {(campaignData.homebrew?.lore || []).length > 0 ? (
                                                (campaignData.homebrew?.lore || []).map(article => (
                                                    <div key={article.id} className="lore-article-card">
                                                        <div className="lore-article-header">
                                                            <input
                                                                type="text"
                                                                value={article.title}
                                                                onChange={(e) => updateLoreArticle(article.id, { title: e.target.value })}
                                                                className="lore-title-input"
                                                            />
                                                            <div className="lore-meta">
                                                                <select
                                                                    value={article.category}
                                                                    onChange={(e) => updateLoreArticle(article.id, { category: e.target.value })}
                                                                    className="lore-category-select"
                                                                >
                                                                    <option value="history">History</option>
                                                                    <option value="religion">Religion</option>
                                                                    <option value="faction">Faction</option>
                                                                    <option value="legend">Legend/Myth</option>
                                                                    <option value="culture">Culture</option>
                                                                    <option value="geography">Geography</option>
                                                                    <option value="magic">Magic System</option>
                                                                    <option value="other">Other</option>
                                                                </select>
                                                                <label className="secret-toggle">
                                                                    <input
                                                                        type="checkbox"
                                                                        checked={article.isSecret || false}
                                                                        onChange={(e) => updateLoreArticle(article.id, { isSecret: e.target.checked })}
                                                                    />
                                                                    <i className="fas fa-eye-slash"></i>
                                                                    Secret
                                                                </label>
                                                            </div>
                                                            <button className="lore-remove-btn" onClick={() => removeLoreArticle(article.id)}>
                                                                <i className="fas fa-times"></i>
                                                            </button>
                                                        </div>
                                                        <div className="lore-article-body">
                                                            <textarea
                                                                value={article.content}
                                                                onChange={(e) => updateLoreArticle(article.id, { content: e.target.value })}
                                                                placeholder="Write your lore article here... You can include details about history, legends, important events, cultural practices, etc."
                                                                className="lore-content-textarea"
                                                                rows={6}
                                                            />
                                                            <div className="lore-field">
                                                                <label>Tags (comma-separated)</label>
                                                                <input
                                                                    type="text"
                                                                    value={Array.isArray(article.tags) ? article.tags.join(', ') : ''}
                                                                    onChange={(e) => updateLoreArticle(article.id, {
                                                                        tags: e.target.value ? e.target.value.split(',').map(t => t.trim()).filter(t => t) : []
                                                                    })}
                                                                    placeholder="e.g., kingdom, war, ancient, forbidden..."
                                                                    className="lore-tags-input"
                                                                />
                                                            </div>
                                                        </div>
                                                    </div>
                                                ))
                                            ) : (
                                                <div className="lore-placeholder">
                                                    <i className="fas fa-scroll"></i>
                                                    <p>No lore articles yet. Start building your world's history and mythology!</p>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                );

            default:
                return <div>Content coming soon...</div>;
        }
    };

    // Handler for input modal
    const handleInputSubmit = () => {
        if (inputModalConfig.onSubmit && inputValue.trim()) {
            inputModalConfig.onSubmit(inputValue);
            setShowInputModal(false);
            setInputValue('');
        }
    };


    return (
        <>
            <MythrillWindow
                isOpen={isOpen}
                onClose={onClose}
                title="Campaign Manager"
                defaultSize={{ width: 1000, height: 700 }}
                defaultPosition={{ x: 100, y: 100 }}
                customHeader={
                    <div className="spellbook-tab-container">
                        {tabs.map(tab => (
                            <button
                                key={tab.id}
                                className={`spellbook-tab-button ${activeTab === tab.id ? 'active' : ''}`}
                                onClick={() => setActiveTab(tab.id)}
                            >
                                <span>{tab.label}</span>
                            </button>
                        ))}
                    </div>
                }
            >
                <div className="campaign-manager-content">
                    {renderTabContent()}
                </div>
            </MythrillWindow>

            {/* Input Modal */}
            {showInputModal && (
                <div
                    className="campaign-modal-overlay"
                    style={{
                        position: 'fixed',
                        top: 0,
                        left: 0,
                        right: 0,
                        bottom: 0,
                        backgroundColor: 'rgba(0, 0, 0, 0.7)',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        zIndex: 100000,
                        backdropFilter: 'blur(6px)',
                        WebkitBackdropFilter: 'blur(6px)'
                    }}
                    onClick={() => {
                        setShowInputModal(false);
                        setInputValue('');
                    }}
                >
                    <div
                        className="input-modal"
                        style={{
                            backgroundColor: '#f0e6d2',
                            border: '3px solid #8b7355',
                            borderRadius: '8px',
                            padding: '20px',
                            maxWidth: '400px',
                            width: '90%',
                            fontFamily: "'Bookman Old Style', 'Garamond', serif",
                            color: '#3a2f1a',
                            boxShadow: '0 4px 20px rgba(0, 0, 0, 0.5)'
                        }}
                        onClick={(e) => e.stopPropagation()}
                    >
                        <h3 style={{ margin: '0 0 15px 0', color: '#8b7355' }}>{inputModalConfig.title}</h3>
                        <input
                            type="text"
                            value={inputValue}
                            onChange={(e) => setInputValue(e.target.value)}
                            onKeyPress={(e) => {
                                if (e.key === 'Enter') {
                                    handleInputSubmit();
                                }
                            }}
                            placeholder={inputModalConfig.placeholder}
                            style={{
                                width: '100%',
                                padding: '8px',
                                fontSize: '14px',
                                border: '2px solid #8b7355',
                                borderRadius: '4px',
                                fontFamily: 'inherit',
                                marginBottom: '15px',
                                boxSizing: 'border-box'
                            }}
                            autoFocus
                        />
                        <div style={{ display: 'flex', gap: '10px', justifyContent: 'flex-end' }}>
                            <button
                                onClick={() => {
                                    setShowInputModal(false);
                                    setInputValue('');
                                }}
                                style={{
                                    padding: '8px 16px',
                                    backgroundColor: '#4a5d23',
                                    color: 'white',
                                    border: 'none',
                                    borderRadius: '4px',
                                    cursor: 'pointer',
                                    fontFamily: 'inherit'
                                }}
                            >
                                Cancel
                            </button>
                            <button
                                onClick={handleInputSubmit}
                                disabled={!inputValue.trim()}
                                style={{
                                    padding: '8px 16px',
                                    backgroundColor: inputValue.trim() ? '#8b7355' : '#cccccc',
                                    color: 'white',
                                    border: 'none',
                                    borderRadius: '4px',
                                    cursor: inputValue.trim() ? 'pointer' : 'not-allowed',
                                    fontFamily: 'inherit'
                                }}
                            >
                                Submit
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Confirm Modal */}
            {isConfirmModalOpen && (
                <div
                    className="campaign-modal-overlay"
                    style={{
                        position: 'fixed',
                        top: 0,
                        left: 0,
                        right: 0,
                        bottom: 0,
                        backgroundColor: 'rgba(0, 0, 0, 0.7)',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        zIndex: 100000,
                        backdropFilter: 'blur(6px)',
                        WebkitBackdropFilter: 'blur(6px)'
                    }}
                    onClick={() => {
                        setIsConfirmModalOpen(false);
                        setConfirmModalConfig({ message: '', onConfirm: null });
                    }}
                >
                    <div
                        className="confirm-modal"
                        style={{
                            backgroundColor: '#f0e6d2',
                            border: '3px solid #8b7355',
                            borderRadius: '8px',
                            padding: '20px',
                            maxWidth: '400px',
                            textAlign: 'center',
                            fontFamily: "'Bookman Old Style', 'Garamond', serif",
                            color: '#3a2f1a',
                            boxShadow: '0 4px 20px rgba(0, 0, 0, 0.5)'
                        }}
                        onClick={(e) => e.stopPropagation()}
                    >
                        <h3 style={{ margin: '0 0 15px 0', color: '#8b7355' }}>Confirm Action</h3>
                        <p style={{ margin: '0 0 20px 0', lineHeight: '1.4' }}>
                            {confirmModalConfig.message}
                        </p>
                        <div style={{ display: 'flex', gap: '10px', justifyContent: 'center' }}>
                            <button
                                onClick={() => {
                                    setIsConfirmModalOpen(false);
                                    setConfirmModalConfig({ message: '', onConfirm: null });
                                }}
                                style={{
                                    padding: '8px 16px',
                                    backgroundColor: '#4a5d23',
                                    color: 'white',
                                    border: 'none',
                                    borderRadius: '4px',
                                    cursor: 'pointer',
                                    fontFamily: 'inherit'
                                }}
                            >
                                Cancel
                            </button>
                            <button
                                onClick={() => {
                                    if (confirmModalConfig.onConfirm) {
                                        confirmModalConfig.onConfirm();
                                    }
                                    setIsConfirmModalOpen(false);
                                    setConfirmModalConfig({ message: '', onConfirm: null });
                                }}
                                style={{
                                    padding: '8px 16px',
                                    backgroundColor: '#8b7355',
                                    color: 'white',
                                    border: 'none',
                                    borderRadius: '4px',
                                    cursor: 'pointer',
                                    fontFamily: 'inherit'
                                }}
                            >
                                Confirm
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Confirm Modal */}
            <ConfirmModal
                isOpen={confirmModal.isOpen}
                title={confirmModal.title}
                message={confirmModal.message}
                onConfirm={handleConfirm}
                onCancel={hideConfirmModal}
            />

            {/* Library Browser Modal */}
            <LibraryBrowserModal
                isOpen={libraryBrowser.isOpen}
                onClose={closeLibraryBrowser}
                libraryType={libraryBrowser.libraryType}
                title={libraryBrowser.title}
                onSelect={libraryBrowser.onSelect}
                multiSelect={true}
            />

            {/* Tooltips */}
            {hoveredItem && (
                <TooltipPortal>
                    <div
                        ref={positionTooltipRef}
                        style={{
                            position: 'fixed',
                            left: adjustedPosition.x,
                            top: adjustedPosition.y,
                            pointerEvents: 'none',
                            zIndex: 999999999
                        }}
                    >
                        <ItemTooltip item={hoveredItem} />
                    </div>
                </TooltipPortal>
            )}
            {hoveredCreature && (
                <TooltipPortal>
                    <div
                        ref={positionTooltipRef}
                        className="campaign-creature-tooltip-portal"
                        style={{
                            position: 'fixed',
                            left: adjustedPosition.x,
                            top: adjustedPosition.y,
                            zIndex: 999999999,
                            width: '280px'
                        }}
                    >
                        <div
                            ref={tooltipRef}
                            className="campaign-creature-tooltip-interactive"
                            onWheel={(e) => {
                                // Stop propagation to prevent background scrolling when scrolling tooltip
                                e.stopPropagation();
                            }}
                            onMouseEnter={() => {
                                // Keep tooltip visible when hovering over it
                                setHoveredCreature(hoveredCreature);
                            }}
                            onMouseLeave={() => {
                                // Hide tooltip when leaving it
                                setHoveredCreature(null);
                            }}
                        >
                            <SimpleCreatureTooltip creature={hoveredCreature} />
                        </div>
                    </div>
                </TooltipPortal>
            )}
            {hoveredSpell && (
                <SpellTooltip
                    spell={hoveredSpell}
                    position={adjustedPosition}
                />
            )}
        </>
    );
}

export default CampaignManagerWindow;

import React, { useState, useEffect, useRef, Suspense } from 'react';
import lazy from '../../utils/lazyWithRetry';
import { createPortal } from 'react-dom';
import useChatStore from '../../store/chatStore';

// Lazy load the ItemTooltip component
const ItemTooltip = lazy(() => import('../item-generation/ItemTooltip'));

// Helper function to format timestamps
const formatTimestamp = (timestamp) => {
  const date = new Date(timestamp);
  return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
};

// Helper function to get class color
const getClassColor = (className) => {
  const classColors = {
    mystic: '#0070DE',
    arcanist: '#69CCF0',
    trickster: '#FFF569',
    zealot: '#FFFFFF',
    harrow: '#9482C9',
    hexer: '#FF7D0A',
    reaver: '#C41F3B',
    mercenary: '#C79C6E',
    sentinel: '#F58CBA'
  };

  return classColors[className.toLowerCase()] || '#FFFFFF';
};

const ChatWindow = () => {
  const {
    activeTab,
    notifications,
    sendMessage,
    clearNotifications
  } = useChatStore(state => ({
    activeTab: state.activeTab,
    setActiveTab: state.setActiveTab,
    notifications: state.notifications,
    unreadCounts: state.unreadCounts,
    sendMessage: state.sendMessage,
    clearNotifications: state.clearNotifications
  }));

  const [messageInput, setMessageInput] = useState('');
  const [isLoaded, setIsLoaded] = useState(false);
  const messagesEndRef = useRef(null);

  // Set isLoaded to true after component mounts
  useEffect(() => {
    const timer = setTimeout(() => {
      setIsLoaded(true);
    }, 300); // Small delay for smoother transition

    return () => clearTimeout(timer);
  }, []);

  // Scroll to bottom when notifications change
  useEffect(() => {
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [notifications, activeTab]);

  // Handle sending a message
  const handleSendMessage = (e) => {
    e.preventDefault();

    if (messageInput.trim() === '') return;

    sendMessage(activeTab, messageInput);
    setMessageInput('');
  };

  // State for item tooltip
  const [tooltipItem, setTooltipItem] = useState(null);
  const [tooltipPosition, setTooltipPosition] = useState({ x: 0, y: 0 });
  const tooltipRef = useRef(null);

  // Get quality color for styling
  const getQualityColor = (quality) => {
    const qualityColors = {
      poor: '#9d9d9d',
      common: '#ffffff',
      uncommon: '#1eff00',
      rare: '#0070dd',
      epic: '#a335ee',
      legendary: '#ff8000',
      artifact: '#e6cc80'
    };
    return qualityColors[quality?.toLowerCase()] || qualityColors.common;
  };

  // Handle mouse enter to show tooltip
  const handleItemMouseEnter = (e, item) => {
    if (!item) return;

    // Calculate position for tooltip - position above the chat window
    const rect = e.currentTarget.getBoundingClientRect();
    const windowWidth = window.innerWidth;
    const windowHeight = window.innerHeight;

    // Get the chat window container to position tooltip above it
    const chatWindow = e.currentTarget.closest('.draggable-window') || e.currentTarget.closest('.chat-window');
    const chatWindowRect = chatWindow ? chatWindow.getBoundingClientRect() : rect;

    // Position tooltip above the entire chat window, centered horizontally
    let x = chatWindowRect.left + (chatWindowRect.width / 2) - 150; // Center tooltip on chat window
    let y = chatWindowRect.top - 420; // Position well above the chat window (tooltip height ~400px)

    // Ensure tooltip doesn't go off screen horizontally
    const tooltipWidth = 300;
    if (x < 10) x = 10;
    if (x + tooltipWidth > windowWidth - 10) x = windowWidth - tooltipWidth - 10;

    // If tooltip would go above screen, position it to the right of the chat window instead
    if (y < 10) {
      x = chatWindowRect.right + 10;
      y = chatWindowRect.top + 50;

      // If that goes off screen too, position it to the left
      if (x + tooltipWidth > windowWidth - 10) {
        x = chatWindowRect.left - tooltipWidth - 10;
      }
    }

    setTooltipPosition({ x, y });
    setTooltipItem(item);
  };

  // Handle mouse leave to hide tooltip
  const handleItemMouseLeave = () => {
    setTooltipItem(null);
  };

  // Render the message content
  const renderMessage = (notification) => {
    const { type, timestamp } = notification;

    switch (type) {
      case 'item_looted':
        return (
          <div
            className="friend-entry"
            data-loot-entry="true"
            data-item-quality={(notification.item.quality || 'common').toLowerCase()}
            onMouseEnter={(e) => handleItemMouseEnter(e, notification.item)}
            onMouseLeave={handleItemMouseLeave}
          >
            <div className="friend-status online"></div>
            <div className="friend-name">
              <span style={{ color: getQualityColor(notification.item.quality) }}>
                {String(notification.item.name || 'Unknown Item')}
              </span>
              {notification.quantity > 1 && <span style={{ color: '#666', fontWeight: 'normal' }}> x{notification.quantity}</span>}
            </div>
            <div className="friend-info">
              <div>
                <span style={{ fontWeight: '700', color: '#1a1a1a', textShadow: '0 1px 2px rgba(0, 0, 0, 0.2), 0 0 1px rgba(255, 255, 255, 0.8)' }}>{notification.looter || 'Player'}</span>
                <span style={{ color: '#2a2a2a', marginLeft: '4px', fontWeight: '600' }}>looted</span>
              </div>
              <div className="friend-location">{notification.source || 'from world'}</div>
              <div className="timestamp">{formatTimestamp(timestamp)}</div>
            </div>
          </div>
        );

      case 'currency_looted':
        const formatCurrencyText = () => {
          const parts = [];

          if (notification.platinum > 0) {
            parts.push(
              <span key="platinum">
                <span className="currency-amount-white">
                  {notification.platinum}
                </span>
                <span className="currency-type-platinum">
                  Platinum
                </span>
              </span>
            );
          }

          if (notification.gold > 0) {
            if (parts.length > 0) parts.push(<span key="platinum-space" style={{ margin: '0 4px' }}> </span>);
            parts.push(
              <span key="gold">
                <span className="currency-amount-white">
                  {notification.gold}
                </span>
                <span className="currency-type-gold">
                  Gold
                </span>
              </span>
            );
          }

          if (notification.silver > 0) {
            if (parts.length > 0) parts.push(<span key="gold-space" style={{ margin: '0 4px' }}> </span>);
            parts.push(
              <span key="silver">
                <span className="currency-amount-white">
                  {notification.silver}
                </span>
                <span className="currency-type-silver">
                  Silver
                </span>
              </span>
            );
          }

          if (notification.copper > 0) {
            if (parts.length > 0) parts.push(<span key="silver-space" style={{ margin: '0 4px' }}> </span>);
            parts.push(
              <span key="copper">
                <span className="currency-amount-white">
                  {notification.copper}
                </span>
                <span className="currency-type-copper">
                  Copper
                </span>
              </span>
            );
          }

          return parts;
        };

        return (
          <div
            className="friend-entry"
            data-loot-entry="true"
            data-item-quality="currency"
          >
            <div className="friend-status online"></div>
            <div className="friend-name">
              <span style={{ fontSize: '17px', fontWeight: '700' }}>
                {formatCurrencyText()}
              </span>
            </div>
            <div className="friend-info">
              <div>
                <span style={{ fontWeight: '700', color: '#1a1a1a', textShadow: '0 1px 2px rgba(0, 0, 0, 0.2), 0 0 1px rgba(255, 255, 255, 0.8)' }}>{notification.looter || 'Player'}</span>
                <span style={{ color: '#2a2a2a', marginLeft: '4px', fontWeight: '600' }}>looted currency</span>
              </div>
              <div className="friend-location">{notification.source || 'from world'}</div>
              <div className="timestamp">{formatTimestamp(timestamp)}</div>
            </div>
          </div>
        );

      case 'combat_hit':
        return (
          <div className="friend-entry">
            <div className="friend-status" style={{ backgroundColor: '#c9323b' }}></div>
            <div className="friend-name">
              <span style={{
                fontWeight: '800',
                textShadow: '0 2px 4px rgba(255, 255, 255, 0.9), 0 0 2px rgba(255, 255, 255, 0.8)',
                color: '#1a0f08',
                fontSize: '16px',
                fontFamily: "'Cinzel', serif"
              }}>
                {notification.attacker}
              </span>
              <span style={{ color: '#5a4a3a', margin: '0 6px', fontSize: '15px', fontWeight: '600' }}>hit</span>
              <span style={{
                fontWeight: '800',
                textShadow: '0 2px 4px rgba(255, 255, 255, 0.9), 0 0 2px rgba(255, 255, 255, 0.8)',
                color: '#1a0f08',
                fontSize: '16px',
                fontFamily: "'Cinzel', serif"
              }}>
                {notification.target}
              </span>
            </div>
            <div className="friend-info">
              <div style={{ color: '#c9323b' }}>{notification.damage} damage</div>
              <div className="timestamp">{formatTimestamp(timestamp)}</div>
            </div>
          </div>
        );

      case 'combat_heal':
        return (
          <div className="friend-entry">
            <div className="friend-status" style={{ backgroundColor: '#2dc937' }}></div>
            <div className="friend-name">
              <span style={{
                fontWeight: '800',
                textShadow: '0 2px 4px rgba(255, 255, 255, 0.9), 0 0 2px rgba(255, 255, 255, 0.8)',
                color: '#1a0f08',
                fontSize: '16px',
                fontFamily: "'Cinzel', serif"
              }}>
                {notification.healer}
              </span>
              <span style={{ color: '#5a4a3a', margin: '0 6px', fontSize: '15px', fontWeight: '600' }}>healed</span>
              <span style={{
                fontWeight: '800',
                textShadow: '0 2px 4px rgba(255, 255, 255, 0.9), 0 0 2px rgba(255, 255, 255, 0.8)',
                color: '#1a0f08',
                fontSize: '16px',
                fontFamily: "'Cinzel', serif"
              }}>
                {notification.target}
              </span>
            </div>
            <div className="friend-info">
              <div style={{ color: '#2dc937' }}>{notification.healing} healing</div>
              <div className="timestamp">{formatTimestamp(timestamp)}</div>
            </div>
          </div>
        );

      case 'initiative_roll':
        return (
          <div className="friend-entry">
            <div className="friend-status" style={{ backgroundColor: '#ffd700' }}></div>
            <div className="friend-name">
              <span style={{
                fontWeight: '800',
                textShadow: '0 2px 4px rgba(255, 255, 255, 0.9), 0 0 2px rgba(255, 255, 255, 0.8)',
                color: '#1a0f08',
                fontSize: '16px',
                fontFamily: "'Cinzel', serif"
              }}>
                {notification.creature}
              </span>
              <span style={{ color: '#5a4a3a', margin: '0 6px', fontSize: '15px', fontWeight: '600' }}>rolled initiative</span>
            </div>
            <div className="friend-info">
              <div style={{ color: '#ffd700' }}>
                d20: {notification.roll} + {notification.modifier} = {notification.total}
              </div>
              <div className="timestamp">{formatTimestamp(timestamp)}</div>
            </div>
          </div>
        );

      case 'message':
      default:
        return (
          <div className="friend-entry">
            <div className="friend-status online"></div>
            <div className="friend-name">
              <span
                style={{
                  color: notification.sender?.playerColor ||
                    (notification.sender?.class ? getClassColor(notification.sender.class) : '#1a0f08'),
                  fontWeight: '800',
                  textShadow: '0 2px 4px rgba(255, 255, 255, 0.9), 0 0 2px rgba(255, 255, 255, 0.8), 0 1px 0 rgba(255, 255, 255, 0.5)',
                  fontSize: '18px',
                  fontFamily: "'Cinzel', serif",
                  letterSpacing: '0.5px'
                }}
              >
                {notification.sender?.name || 'System'}
              </span>
            </div>
            <div className="friend-info">
              <div>{notification.content}</div>
              <div className="timestamp">{formatTimestamp(timestamp)}</div>
            </div>
          </div>
        );
    }
  };

  // Render the appropriate tab content
  const renderContent = () => {
    if (!isLoaded) {
      return (
        <div className="loading-wrapper">
          <div className="loading-text">Loading notifications...</div>
        </div>
      );
    }

    // Get notifications from the store
    const tabNotifications = notifications[activeTab] || [];

    if (tabNotifications.length === 0) {
      return (
        <div className="empty-state">
          <div className="empty-state-icon">
            <i className={`fas ${
              activeTab === 'social' ? 'fa-comments' :
              activeTab === 'combat' ? 'fa-sword' :
              'fa-coins'
            }`}></i>
          </div>
          <div className="empty-state-text">No notifications yet</div>
          <div className="empty-state-subtext">
            {activeTab === 'social' && 'Social interactions will appear here'}
            {activeTab === 'combat' && 'Combat events will appear here'}
            {activeTab === 'loot' && 'Loot items will appear here'}
          </div>
        </div>
      );
    }

    return (
      <div className="friends-list-container">
        <div className="friends-list-header">
          <div className="friends-list-title">
            {activeTab === 'social' ? 'Social Messages' :
             activeTab === 'combat' ? 'Combat Events' :
             'Loot History'}
          </div>
          {tabNotifications.length > 0 && (
            <div className="friends-list-actions">
              <button
                className="compact-action-btn utility"
                onClick={() => clearNotifications(activeTab)}
                title="Clear History"
              >
                <i className="fas fa-trash"></i>
              </button>
            </div>
          )}
        </div>
        <div className="friends-list">
          {tabNotifications.map(notification => (
            <div key={notification.id}>
              {renderMessage(notification)}
            </div>
          ))}
          <div ref={messagesEndRef} />
        </div>

        {/* Item Tooltip */}
        {tooltipItem && createPortal(
          <Suspense fallback={<div>Loading...</div>}>
            <div
              ref={tooltipRef}
              style={{
                position: 'fixed',
                left: tooltipPosition.x,
                top: tooltipPosition.y,
                zIndex: 9999,
                pointerEvents: 'none'
              }}
            >
              <ItemTooltip item={tooltipItem} />
            </div>
          </Suspense>,
          document.body
        )}
      </div>
    );
  };

  return (
    <div className="social-window">
      {/* Tab Content - tabs are now in the window header */}
      <div className="social-content">
        {renderContent()}

        {/* Message Input (only for social tab) - positioned at bottom */}
        {activeTab === 'social' && (
          <div className="message-input-container">
            <form className="message-form" onSubmit={handleSendMessage}>
              <input
                type="text"
                className="message-input"
                value={messageInput}
                onChange={(e) => setMessageInput(e.target.value)}
                placeholder="Type a message..."
              />
              <button
                type="submit"
                className="send-button"
              >
                <i className="fas fa-paper-plane"></i>
              </button>
            </form>
          </div>
        )}
      </div>
    </div>
  );
};

export default ChatWindow;

import React, { useState } from 'react';
import MythrillWindow from './MythrillWindow';
import useCraftingStore, { PROFESSIONS, SKILL_LEVELS } from '../../store/craftingStore';
import ProfessionSelection from '../crafting/ProfessionSelection';
import AlchemyInterface from '../crafting/AlchemyInterface';
import FirstAidInterface from '../crafting/FirstAidInterface';
import BlacksmithingInterface from '../crafting/BlacksmithingInterface';
import useChatStore from '../../store/chatStore';
import useInventoryStore from '../../store/inventoryStore';
import useItemStore from '../../store/itemStore';

function CraftingWindow({ isOpen, onClose }) {
    const [activeTab, setActiveTab] = useState('recipes');
    const store = useCraftingStore();
    const {
        selectedProfession,
        setSelectedProfession,
        getProfessionLevel,
        getRecipesForProfession,
        learnRecipe,
        professionLevels,
        availableRecipes
    } = store;
    const { addLootNotification } = useChatStore();
    const { addItemFromLibrary } = useInventoryStore();
    const { items: itemLibrary } = useItemStore();

    // Note: Use the "Add Test Materials" button to populate inventory with crafting materials

    const getSkillLevelColor = (level) => {
        if (level === 0) return '#9d9d9d';
        if (level <= 2) return '#ffffff';
        if (level <= 4) return '#1eff00';
        if (level <= 6) return '#0070dd';
        if (level <= 8) return '#a335ee';
        return '#ff8000';
    };

    // Safe wrapper for setSelectedProfession with fallback
    const safeSetSelectedProfession = (professionId) => {
        if (typeof setSelectedProfession === 'function') {
            setSelectedProfession(professionId);
        } else {
            // Fallback: use store.setState directly
            useCraftingStore.setState({ selectedProfession: professionId });
        }
    };

    const handleProfessionSelect = (professionId) => {
        safeSetSelectedProfession(professionId);
    };

    const handleBackToProfessions = () => {
        safeSetSelectedProfession(null);
    };

    const renderContent = () => {
        // If a profession is selected, show its interface
        if (selectedProfession) {
            switch (selectedProfession) {
                case 'alchemy':
                    return <AlchemyInterface onBack={handleBackToProfessions} activeTab={activeTab} onTabChange={setActiveTab} />;
                case 'first-aid':
                    return <FirstAidInterface onBack={handleBackToProfessions} activeTab={activeTab} onTabChange={setActiveTab} />;
                case 'blacksmithing':
                    return <BlacksmithingInterface onBack={handleBackToProfessions} activeTab={activeTab} onTabChange={setActiveTab} />;
                default:
                    return (
                        <div className="profession-not-implemented">
                            <h3>Coming Soon</h3>
                            <p>This profession interface is under development.</p>
                            <button className="wow-button" onClick={handleBackToProfessions}>
                                Back to Professions
                            </button>
                        </div>
                    );
            }
        }

        // Otherwise show profession selection
        return (
            <ProfessionSelection
                onProfessionSelect={handleProfessionSelect}
                selectedProfession={selectedProfession}
            />
        );
    };

    // Handle learning all recipes for current profession
    const handleLearnAllRecipes = () => {
        if (!selectedProfession) {
            console.log('handleLearnAllRecipes: No selected profession');
            return;
        }

        console.log('handleLearnAllRecipes: selectedProfession =', selectedProfession);
        const allRecipes = (typeof getRecipesForProfession === 'function')
            ? getRecipesForProfession(selectedProfession)
            : ((availableRecipes || []).filter(recipe => recipe.profession === selectedProfession));
        console.log('handleLearnAllRecipes: Found recipes:', allRecipes.length, allRecipes.map(r => r.id));
        
        if (allRecipes.length === 0) {
            addLootNotification({
                type: 'crafting_failed',
                message: `No recipes found for ${selectedProfession}.`,
                timestamp: Date.now()
            });
            return;
        }

        let learnedCount = 0;
        allRecipes.forEach(recipe => {
            console.log('handleLearnAllRecipes: Learning recipe', recipe.id, 'for profession', selectedProfession);
            if (typeof learnRecipe === 'function') {
                learnRecipe(selectedProfession, recipe.id);
            } else {
                // Fallback: directly update the store
                const store = useCraftingStore.getState();
                const currentRecipes = store.knownRecipes?.[selectedProfession] || [];
                if (!currentRecipes.includes(recipe.id)) {
                    useCraftingStore.setState(state => ({
                        knownRecipes: {
                            ...state.knownRecipes,
                            [selectedProfession]: [...currentRecipes, recipe.id]
                        }
                    }));
                }
            }
            learnedCount++;
        });

        // Find profession by id since PROFESSIONS uses keys like ALCHEMY, FIRST_AID
        const profession = Object.values(PROFESSIONS).find(p => p.id === selectedProfession);

        console.log('handleLearnAllRecipes: Learned', learnedCount, 'recipes');

        addLootNotification({
            type: 'crafting_success',
            message: `Learned ${learnedCount} ${profession?.name || selectedProfession} recipe${learnedCount !== 1 ? 's' : ''}!`,
            timestamp: Date.now()
        });
    };

    // Add test materials for crafting (context-aware based on profession)
    const handleAddTestMaterials = () => {
        if (!selectedProfession) return;

        let testMaterials = [];
        let message = '';

        if (selectedProfession === 'alchemy') {
            testMaterials = [
                // Basic materials for all potions
                { id: 'peacebloom', quantity: 10 },
                { id: 'silverleaf', quantity: 10 },
                { id: 'earthroot', quantity: 10 },
                { id: 'mageroyal', quantity: 10 },
                { id: 'empty-vial', quantity: 5 },
                { id: 'crystal-vial', quantity: 3 },
                { id: 'distilled-water', quantity: 10 },
                { id: 'alchemical-catalyst', quantity: 2 }
            ];
            message = 'Added test alchemy crafting materials to inventory!';
        } else if (selectedProfession === 'first-aid') {
            testMaterials = [
                // Basic materials for first aid
                { id: 'linen-cloth', quantity: 20 },
                { id: 'healing-herb', quantity: 15 },
                { id: 'aloe-vera', quantity: 10 },
                { id: 'small-jar', quantity: 5 },
                { id: 'wooden-stick', quantity: 10 },
                { id: 'leather-strip', quantity: 8 },
                { id: 'medical-tools', quantity: 3 }
            ];
            message = 'Added test first aid crafting materials to inventory!';
        } else if (selectedProfession === 'blacksmithing') {
            testMaterials = [
                // Basic materials for blacksmithing
                { id: 'red-copper', quantity: 20 },
                { id: 'bog-iron', quantity: 20 },
                { id: 'copper-ingot', quantity: 10 },
                { id: 'iron-ingot', quantity: 10 },
                { id: 'metal-rivets', quantity: 10 }
            ];
            message = 'Added test blacksmithing crafting materials to inventory!';
        } else {
            return; // Unknown profession
        }

        testMaterials.forEach(material => {
            const itemData = itemLibrary.find(item => item.id === material.id);
            if (itemData) {
                for (let i = 0; i < material.quantity; i++) {
                    addItemFromLibrary(itemData, 1);
                }
            } else {
                console.log('Test material not found:', material.id);
            }
        });

        addLootNotification({
            type: 'item_received',
            message: message,
            timestamp: Date.now()
        });
    };

    return (
        <MythrillWindow
            title="Crafting"
            isOpen={isOpen}
            onClose={onClose}
            defaultSize={{ width: 1000, height: 700 }}
            defaultPosition={{ x: 200, y: 100 }}
            className="crafting-window"
            customHeader={
                <div className="spellbook-tab-container" style={{ width: '100%', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                    <div style={{ display: 'flex' }}>
                        <button className="spellbook-tab-button active">
                            <i className="fas fa-hammer" style={{ marginRight: '8px' }}></i>
                            <span>
                                {selectedProfession ? (
                                    (() => {
                                        const profession = Object.values(PROFESSIONS).find(p => p.id === selectedProfession);
                                        const professionLevel = (typeof getProfessionLevel === 'function') 
                                            ? getProfessionLevel(selectedProfession) 
                                            : (professionLevels?.[selectedProfession] ?? SKILL_LEVELS.UNTRAINED.level);
                                        const skillLevelInfo = Object.values(SKILL_LEVELS).find(skill => skill.level === professionLevel);
                                        const skillName = skillLevelInfo?.name || 'Untrained';
                                        return `${profession?.name || 'Profession'} (${skillName})`;
                                    })()
                                ) : (
                                    'CRAFTING'
                                )}
                            </span>
                        </button>
                    </div>

                    {selectedProfession && (
                        <div className="crafting-header-actions" style={{ display: 'flex', gap: '8px', marginRight: '48px' }}>
                            <button
                                className="wow-button crafting-action-button"
                                onClick={handleAddTestMaterials}
                                title={`Add test ${Object.values(PROFESSIONS).find(p => p.id === selectedProfession)?.name?.toLowerCase() || 'crafting'} materials to inventory`}
                            >
                                Add Test Materials
                            </button>
                            <button
                                className="wow-button crafting-action-button"
                                onClick={handleLearnAllRecipes}
                            >
                                Learn All Recipes
                            </button>
                            <button
                                className="wow-button crafting-action-button"
                                onClick={handleBackToProfessions}
                            >
                                Back to Professions
                            </button>
                        </div>
                    )}
                </div>
            }
        >
            <div className="crafting-window-content">
                {renderContent()}
            </div>
        </MythrillWindow>
    );
}

export default CraftingWindow;

import React, { useState, useEffect, useRef } from 'react';
import ReactDOM from 'react-dom';
import useInventoryStore from '../../store/inventoryStore';
import { WOW_ICON_BASE_URL } from '../item-generation/wowIcons';
import { CURRENCY_TYPES } from '../item-generation/itemConstants';
import '../../styles/currency-withdraw-modal.css';

const CurrencyWithdrawModal = ({ currencyType, onClose }) => {
    const { currency, updateCurrency, addItemFromLibrary } = useInventoryStore();
    const modalRef = useRef(null);
    const [amount, setAmount] = useState(1);
    const [error, setError] = useState('');
    const maxAmount = currency[currencyType] || 0;

    // Get currency icon and label
    const getCurrencyIcon = () => {
        switch (currencyType) {
            case 'platinum':
                return 'inv_misc_coin_04';
            case 'gold':
                return 'inv_misc_coin_01';
            case 'silver':
                return 'inv_misc_coin_03';
            case 'copper':
                return 'inv_misc_coin_05';
            default:
                return 'inv_misc_coin_01';
        }
    };

    const getCurrencyLabel = () => {
        return currencyType.charAt(0).toUpperCase() + currencyType.slice(1);
    };

    // Handle click outside to close modal
    useEffect(() => {
        const handleClickOutside = (event) => {
            if (modalRef.current && !modalRef.current.contains(event.target)) {
                onClose();
            }
        };

        document.addEventListener('mousedown', handleClickOutside);
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, [onClose]);

    // Handle amount change
    const handleAmountChange = (e) => {
        const value = parseInt(e.target.value);
        if (isNaN(value) || value < 1) {
            setAmount(1);
        } else if (value > maxAmount) {
            setAmount(maxAmount);
        } else {
            setAmount(value);
        }
        setError('');
    };

    // Handle withdraw
    const handleWithdraw = () => {
        if (amount <= 0) {
            setError('Amount must be greater than 0');
            return;
        }

        if (amount > maxAmount) {
            setError(`You only have ${maxAmount} ${currencyType}`);
            return;
        }

        // Deduct currency FIRST, then create item: prevents duplication
        updateCurrency({
            [currencyType]: currency[currencyType] - amount
        });

        // Create a currency item
        const currencyItem = createCurrencyItem(currencyType, amount);

        // Add the item to inventory
        addItemFromLibrary(currencyItem);

        // Close the modal
        onClose();
    };

    // Create a currency item based on type and amount
    const createCurrencyItem = (type, value) => {
        // Determine which currency preset to use based on amount
        let currencyKey = '';
        let displayName = '';

        if (type === 'copper') {
            if (value <= 10) currencyKey = 'HANDFUL_OF_COINS';
            else currencyKey = 'SMALL_POUCH';
            displayName = value === 1 ? 'Copper Coin' : `${value} Copper Coins`;
        } else if (type === 'silver') {
            if (value <= 10) currencyKey = 'MODEST_SUM';
            else currencyKey = 'MERCHANT_PURSE';
            displayName = value === 1 ? 'Silver Coin' : `${value} Silver Coins`;
        } else { // gold
            if (value <= 5) currencyKey = 'ADVENTURER_EARNINGS';
            else if (value <= 10) currencyKey = 'NOBLE_PAYMENT';
            else currencyKey = 'ROYAL_BOUNTY';
            displayName = value === 1 ? 'Gold Coin' : `${value} Gold Coins`;
        }

        const currencyInfo = CURRENCY_TYPES[currencyKey] || CURRENCY_TYPES.HANDFUL_OF_COINS;

        // Create a value object with the appropriate currency type
        const valueObj = { platinum: 0, gold: 0, silver: 0, copper: 0 };
        valueObj[type] = value;

        console.log("Creating currency item:", {
            type,
            value,
            currencyKey,
            displayName,
            valueObj
        });

        return {
            id: crypto.randomUUID(),
            name: displayName,
            quality: 'common',
            description: `${displayName} that can be spent or traded.`,
            type: 'currency',
            subtype: currencyKey,
            iconId: getCurrencyIcon(),
            imageUrl: `${WOW_ICON_BASE_URL}${getCurrencyIcon()}.jpg`,
            currencyType: type,
            currencyValue: valueObj, // Use the value object instead of just the number
            isCurrency: true,
            value: valueObj,
            width: 1,
            height: 1,
            rotation: 0
        };
    };

    return ReactDOM.createPortal(
        <div className="modal-overlay">
            <div ref={modalRef} className="currency-withdraw-modal">
                <div className="modal-header">
                    <h3>Withdraw {getCurrencyLabel()}</h3>
                    <button className="close-button" onClick={onClose}>´┐¢ - </button>
                </div>
                <div className="modal-content">
                    <div className="currency-info">
                        <img
                            src={`${WOW_ICON_BASE_URL}${getCurrencyIcon()}.jpg`}
                            alt={getCurrencyLabel()}
                            className="currency-icon"
                        />
                        <div className="currency-details">
                            <div className="currency-name">{getCurrencyLabel()}</div>
                            <div className="currency-available">Available: {maxAmount}</div>
                        </div>
                    </div>

                    <div className="amount-control">
                        <label htmlFor="amount">Amount to withdraw:</label>
                        <div className="amount-input-wrapper">
                            <button
                                className="amount-button"
                                onClick={() => setAmount(prev => Math.max(1, prev - 1))}
                                disabled={amount <= 1}
                            >-</button>
                            <input
                                id="amount"
                                type="number"
                                min="1"
                                max={maxAmount}
                                value={amount}
                                onChange={handleAmountChange}
                            />
                            <button
                                className="amount-button"
                                onClick={() => setAmount(prev => Math.min(maxAmount, prev + 1))}
                                disabled={amount >= maxAmount}
                            >+</button>
                        </div>
                    </div>

                    {error && <div className="error-message">{error}</div>}
                </div>
                <div className="modal-footer">
                    <button className="cancel-button" onClick={onClose}>Cancel</button>
                    <button
                        className="withdraw-button"
                        onClick={handleWithdraw}
                        disabled={amount <= 0 || amount > maxAmount}
                    >
                        Withdraw
                    </button>
                </div>
            </div>
        </div>,
        document.body
    );
};

export default CurrencyWithdrawModal;

import React, { useRef, useState, forwardRef, useImperativeHandle, useEffect, useCallback } from 'react';
import Draggable from 'react-draggable';
import useSettingsStore from '../../store/settingsStore';
import '../../styles/draggable-window.css';

const DraggableWindow = forwardRef(({
    children,
    isOpen,
    onClose,
    defaultPosition = { x: 100, y: 100 },
    defaultSize = null,
    className = '',
    handleClassName = 'draggable-window-handle',
    centered = false,
    bounds = "body",
    zIndex = 1000,
    onDrag = null,
    onDragStart = null,
    onDragStop = null,
    resetSignal = 0
}, ref) => {
    const windowScale = useSettingsStore(state => state.windowScale);

    const [isMobile, setIsMobile] = useState(() => {
        if (typeof window === 'undefined') return false;
        return window.innerWidth <= 768 || /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
    });

    useEffect(() => {
        const handleResize = () => {
            setIsMobile(window.innerWidth <= 768 || /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent));
        };
        // Initial check on mount to ensure we have the correct state
        handleResize();
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    const lastLoggedScale = useRef(windowScale);
    useEffect(() => {
        lastLoggedScale.current = windowScale;
    }, [windowScale]);

    const nodeRef = useRef(null);
    const windowRef = useRef(null);
    const rafHandleRef = useRef(null); // For RAF-throttled drag updates

    useEffect(() => {
        if (document && !document.getElementById('react-draggable-style-el')) {
            const styleEl = document.createElement('style');
            styleEl.type = 'text/css';
            styleEl.id = 'react-draggable-style-el';
            styleEl.innerHTML = '.react-draggable-transparent-selection *::-moz-selection {all: inherit;}\n.react-draggable-transparent-selection *::selection {all: inherit;}\n';
            document.head.appendChild(styleEl);
