                            width: '100%',
                            height: '100%',
                            objectFit: 'contain',
                            filter: 'drop-shadow(0 4px 6px rgba(0,0,0,0.5))'
                        }}
                        onError={(e) => {
                            e.target.onerror = null;
                            e.target.src = getIconUrl('Misc/Books/book-brown-teal-question-mark', 'items');
                        }}
                    />
                </div>,
                document.body
            )}

        </div>
    );
});

