    const handleSaveMapEdit = () => {
        if (editingMapId) {
            updateMap(editingMapId, {
                name: editMapName,
                description: editMapDescription
            });
            setEditingMapId(null);
            setEditMapName('');
            setEditMapDescription('');
        }
    };

    const handleCancelMapEdit = () => {
        setEditingMapId(null);
        setEditMapName('');
        setEditMapDescription('');
    };

    // Handle background assignment to existing maps
    const handleAssignBackground = (mapId) => {
        setShowBackgroundAssignment(mapId);
        // Trigger file input
        if (backgroundFileInputRef.current) {
            backgroundFileInputRef.current.click();
        }
    };

    // Handle Asset Selection
    const handleOpenAssetSelector = (type, mapId = null) => {
        setAssetSelectorType(type);
        setTargetMapForAsset(mapId);
        setShowAssetSelector(true);
    };

    const handleSelectAsset = (bgName) => {
        const bgUrl = getBackgroundUrl(bgName);

        if (assetSelectorType === 'wizard') {
            updateMapCreationWizard({ backgroundImage: bgUrl });
        } else if (assetSelectorType === 'assign' && targetMapForAsset) {
            const backgroundId = Date.now().toString();
            updateMap(targetMapForAsset, {
                backgrounds: [{
                    id: backgroundId,
                    url: bgUrl,
                    name: bgName.replace('.png', ''),
                    position: { x: 0, y: 0 },
                    scale: 1.0,
                    opacity: 1.0,
                    zIndex: 0
                }],
                activeBackgroundId: backgroundId,
                backgroundImage: null,
                backgroundImageUrl: ''
            });
        }

        setShowAssetSelector(false);
        setAssetSelectorType(null);
        setTargetMapForAsset(null);
    };

    const handleBackgroundUpload = async (event) => {
        const file = event.target.files[0];
        if (!file || !showBackgroundAssignment) return;

        // Validate file size
        if (file.size > MAX_FILE_SIZE) {
            alert(`File size too large! Please choose an image smaller than ${MAX_FILE_SIZE_MB}MB.\n\nCurrent file size: ${(file.size / (1024 * 1024)).toFixed(1)}MB\n\nLarge files can cause the application to crash due to browser storage limitations.`);
            // Reset file input and state
            if (backgroundFileInputRef.current) {
                backgroundFileInputRef.current.value = '';
            }
            setShowBackgroundAssignment(null);
            return;
        }

        // Validate file type
        if (!file.type.startsWith('image/')) {
            alert('Please select a valid image file.');
            if (backgroundFileInputRef.current) {
                backgroundFileInputRef.current.value = '';
            }
            setShowBackgroundAssignment(null);
            return;
        }

        try {
            // Import compression utility
            const { compressImage } = await import('../../utils/imageCompression');

            // Compress image before storing (max 1920px width for map backgrounds, quality 0.85)
            console.log('­ƒû╝´©Å Compressing background image... Original size:', (file.size / 1024).toFixed(1), 'KB');
            const compressedFile = await compressImage(file, 1920, null, 0.85);
            console.log('´┐¢ - ´┐¢´©Å Image compressed to:', (compressedFile.size / 1024).toFixed(1), 'KB');

            const reader = new FileReader();
            reader.onload = (e) => {
                const backgroundUrl = e.target.result;

                // Create background ID
                const backgroundId = Date.now().toString();

                // Update the map with the new background (replace all existing backgrounds)
                // NOTE: This is just for preview in the map library - it won't automatically apply to the grid
                // Users need to use the "Upload Background" button in the editor to actually set it as a grid background
                updateMap(showBackgroundAssignment, {
                    backgrounds: [{
                        id: backgroundId,
                        url: backgroundUrl,
                        name: 'Map Background',
                        position: { x: 0, y: 0 },
                        scale: 1.0,
                        opacity: 1.0,
                        zIndex: 0
                    }],
                    activeBackgroundId: backgroundId,
                    // Clear legacy background fields to prevent conflicts
                    backgroundImage: null,
                    backgroundImageUrl: ''
                });

                // DON'T automatically apply to gameStore - this is just a preview image
                // Users should use the editor's "Upload Background" feature to set grid backgrounds

                setShowBackgroundAssignment(null);

                // Reset file input
                if (backgroundFileInputRef.current) {
                    backgroundFileInputRef.current.value = '';
                }
            };
            reader.onerror = () => {
                alert('Error reading file. Please try again.');
                if (backgroundFileInputRef.current) {
                    backgroundFileInputRef.current.value = '';
                }
                setShowBackgroundAssignment(null);
            };
            reader.readAsDataURL(compressedFile);
        } catch (error) {
            console.error('ÔØî Image compression failed:', error);
            alert('Failed to compress image. Please try a different image or a smaller file.');
            if (backgroundFileInputRef.current) {
                backgroundFileInputRef.current.value = '';
            }
            setShowBackgroundAssignment(null);
        }
    };

    // Format date for display
    const formatDate = (timestamp) => {
        return new Date(timestamp).toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'short',
            day: 'numeric',
            hour: '2-digit',
            minute: '2-digit'
        });
    };

    const mapLibraryContent = (
                <div className="map-library-window">
                    {/* Map Grid with Create Button */}
                    <div
                        className="map-grid"
                        ref={mapGridRef}
                    >
                        {/* Create New Map card at the top of the grid */}
                        <div
                            className="create-map-container"
                            onClick={openMapCreationWizard}
                        >
                            <div className="create-map-content">
                                <div className="create-map-icon">+</div>
                                <div className="create-map-text">Create New Map</div>
                            </div>
                        </div>
                        {maps.map(map => {
                            const playersOnMap = getPlayersOnMap(map.id);
                            const isDropTarget = dropTargetMapId === map.id;

                            return (
                                <div
                                    key={map.id}
                                    className={`map-card ${map.id === currentMapId ? 'current' : ''} ${selectedMapId === map.id ? 'selected' : ''} ${isDropTarget ? 'drop-target' : ''}`}
                                    onClick={() => setSelectedMapId(map.id)}
                                    onDoubleClick={() => handleMapSwitchRequest(map.id)}
                                    onDragOver={(e) => handleMapDragOver(e, map.id)}
                                    onDragLeave={handleMapDragLeave}
                                    onDrop={(e) => handlePlayerDrop(e, map.id)}
                                >
                                    {/* Map thumbnail */}
                                    <div className="map-thumbnail">
                                        {(map.thumbnailUrl || (map.backgrounds && map.backgrounds.length > 0)) ? (
                                            <img
                                                src={map.thumbnailUrl || (map.backgrounds && map.backgrounds[0].url)}
                                                alt={map.name}
                                                onError={(e) => {
                                                    e.target.style.display = 'none';
                                                    e.target.nextSibling.style.display = 'flex';
                                                }}
                                            />
                                        ) : null}
                                        <div className="map-placeholder" style={{
                                            display: (map.backgrounds && map.backgrounds.length > 0) ? 'none' : 'flex'
                                        }}>
                                            <div className="map-icon"><FaImage /></div>
                                            <div className="map-placeholder-text">No Background</div>
                                        </div>

                                        {/* Player indicators overlay on thumbnail */}
                                        {isInMultiplayer && playersOnMap.length > 0 && (
                                            <div className="map-players-indicator">
                                                <FaUsers style={{ marginRight: '4px' }} />
                                                <span>{playersOnMap.length}</span>
                                            </div>
                                        )}
                                        {/* Player/GM Indicators */}
                                        {map.id === currentMapId && (
                                            <div className="map-view-indicator">
                                                <FaUserAlt style={{ marginRight: '4px' }} title="You are currently viewing this map" />
                                                <span>YOU ARE HERE</span>
                                            </div>
                                        )}

                                        {/* GM Location Indicator (for Players) */}
                                        {isInMultiplayer && !isGMMode && (() => {
                                            const gmMember = partyMembers.find(m => m.isGM || m.id === usePartyStore.getState().leaderId);
                                            const gmMapId = gmMember ? (playerMapAssignments[gmMember.id] || 'default') : null;
                                            return gmMapId === map.id && map.id !== currentMapId;
                                        })() && (
                                                <div className="map-view-indicator gm-indicator" style={{ backgroundColor: 'rgba(255, 215, 0, 0.8)', border: '1px solid #ffd700' }}>
                                                    <span style={{ color: '#000', fontWeight: 'bold' }}>GM VIEWING</span>
                                                </div>
                                            )}
                                    </div>

                                    {/* Map info */}
                                    <div className="map-info">
                                        <h3 className="map-name">{map.name}</h3>
                                        <div className="map-details">
                                            {map.description && (
                                                <div className="map-description">
                                                    {map.description}
                                                </div>
                                            )}
                                            <span className="map-date">
                                                Modified: {formatDate(map.lastModified)}
                                            </span>
                                        </div>
                                    </div>

                                    {/* Map actions */}
                                    <div className="map-actions">
                                        <button
                                            className="wow-button small"
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                handleMapSwitchRequest(map.id);
                                            }}
                                            disabled={map.id === currentMapId}
                                        >
                                            <FaExchangeAlt style={{ marginRight: '4px' }} />
                                            {map.id === currentMapId ? 'Viewing' : 'Switch'}
                                        </button>
                                        <button
                                            className="wow-button small"
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                handleEditMap(map.id);
                                            }}
                                            title="Edit Map Name & Description"
                                        >
                                            Edit
                                        </button>
                                        <button
                                            className="wow-button small"
                                            onClick={(e) => {
                                                e.preventDefault();
                                                e.stopPropagation();
                                                handleOpenAssetSelector('assign', map.id);
                                            }}
                                            title="Assign Background"
                                        >
                                            <FaImage style={{ marginRight: '4px' }} />
                                            Image
                                        </button>
                                        <button
                                            className="wow-button small"
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                duplicateMap(map.id);
                                            }}
                                        >
                                            <FaCopy style={{ marginRight: '4px' }} />
                                            Copy
                                        </button>
                                        <button
                                            className="wow-button small danger"
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                handleDeleteMap(map.id);
                                            }}
                                            disabled={maps.length <= 1}
                                        >
                                            <FaTrash style={{ marginRight: '4px' }} />
                                            Delete
                                        </button>
                                    </div>

                                    {/* Draggable player list (GM only, in multiplayer) */}
                                    {isInMultiplayer && isGMMode && playersOnMap.length > 0 && (
                                        <div className="map-players-list">
                                            {playersOnMap.map(player => (
                                                <div
                                                    key={player.id}
                                                    className="map-player-chip"
                                                    draggable
                                                    onDragStart={(e) => handlePlayerDragStart(e, player)}
                                                    title={`Drag to transfer ${player.name || player.characterName || 'Player'} to another map`}
                                                >
                                                    {player.id === usePartyStore.getState().leaderId ? (
                                                        <span style={{ color: '#ffd700', marginRight: '4px', fontSize: '10px' }}>­ƒææ</span>
                                                    ) : (
                                                        <FaUserAlt style={{ marginRight: '4px', fontSize: '10px' }} />
                                                    )}
                                                    <span>{player.name || player.characterName || 'Player'}</span>
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                </div>
            );

            return (
                <>
                    {contentOnly ? (
                        mapLibraryContent
                    ) : (
                        <MythrillWindow
                            isOpen={isOpen}
                            onClose={onClose}
                            defaultSize={{ width: 900, height: 700 }}
                            defaultPosition={{ x: 100, y: 100 }}
                            customHeader={
                                <div className="spellbook-tab-container">
                                    <button className="spellbook-tab-button active">
                                        <i className="fas fa-map" style={{ marginRight: '8px' }}></i>
                                        <span>MAP LIBRARY</span>
                                    </button>
                                </div>
                            }
                        >
                            {mapLibraryContent}
                        </MythrillWindow>
                    )}

            {/* Map Creation Wizard */}
            {mapCreationWizard.isOpen && (
                <MythrillWindow
                    title="Create New Map"
                    isOpen={true}
                    onClose={closeMapCreationWizard}
                    defaultSize={{ width: 500, height: 400 }}
                    defaultPosition={{ x: 200, y: 200 }}
                >
                    <div className="map-creation-wizard">
                        <div className="wizard-step">
                            <label className="wizard-label">
                                Map Name:
                                <input
                                    type="text"
                                    className="wow-input"
                                    value={mapCreationWizard.name}
                                    onChange={(e) => updateMapCreationWizard({ name: e.target.value })}
                                    placeholder="Enter map name..."
                                    autoFocus
                                />
                            </label>

                            <div className="wizard-label">
                                Background Image (Optional):
                                <input
                                    ref={fileInputRef}
                                    type="file"
                                    accept="image/*"
                                    onChange={handleImageUpload}
                                    style={{ display: 'none' }}
                                />
                                <div className="wizard-button-group">
                                    <button
                                        className="wow-button"
                                        onClick={(e) => {
                                            e.preventDefault();
                                            handleOpenAssetSelector('wizard');
                                        }}
                                        style={{ width: '100%' }}
                                    >
                                        <FaImage style={{ marginRight: '8px' }} />
                                        Select Image
                                    </button>
                                </div>
                                {mapCreationWizard.backgroundImage && (
                                    <div className="image-preview">
                                        <img
                                            src={mapCreationWizard.backgroundImage}
                                            alt="Preview"
                                            style={{ maxWidth: '200px', maxHeight: '150px' }}
                                        />
                                    </div>
                                )}
                            </div>
                        </div>

                        <div className="wizard-actions">
                            <button
                                className="wow-button"
                                onClick={closeMapCreationWizard}
                            >
                                Cancel
                            </button>
                            <button
                                className="wow-button primary"
                                onClick={handleCreateMap}
                                disabled={!mapCreationWizard.name.trim()}
                            >
                                Create Map
                            </button>
                        </div>
                    </div>
                </MythrillWindow>
            )}

            {/* Asset Selector Modal */}
            {showAssetSelector && ReactDOM.createPortal(
                <div
                    className="character-appearance-modal-overlay"
                    style={{ zIndex: 100000 }}
                    onClick={() => setShowAssetSelector(false)}
                >
                    <div
                        className="character-appearance-modal"
                        style={{ maxWidth: '800px', width: '90%' }}
                        onClick={e => e.stopPropagation()}
                    >
                        <div className="character-appearance-modal-header">
                            <h3>Select Background Asset</h3>
                            <button
                                className="character-appearance-modal-close"
                                onClick={() => setShowAssetSelector(false)}
                            >
                                ´┐¢ - 
                            </button>
                        </div>
                        <div className="character-appearance-modal-body">
                            <div className="appearance-tabs" style={{ marginBottom: '20px' }}>
                                <button
                                    className={`appearance-tab ${activeSelectionTab === 'assets' ? 'active' : ''}`}
                                    onClick={() => setActiveSelectionTab('assets')}
                                >
                                    <i className="fas fa-images"></i> Assets Library
                                </button>
                                <button
                                    className={`appearance-tab ${activeSelectionTab === 'upload' ? 'active' : ''}`}
                                    onClick={() => setActiveSelectionTab('upload')}
                                >
                                    <i className="fas fa-upload"></i> Upload Custom
                                </button>
                            </div>

                            {activeSelectionTab === 'assets' ? (
                                <div className="appearance-background-grid" style={{ maxHeight: '50vh', overflowY: 'auto' }}>
                                    {ALL_BACKGROUND_ASSETS.map(bg => (
                                        <div
                                            key={bg}
                                            className="appearance-background-option"
                                            style={{ backgroundImage: `url(/assets/backgrounds/${bg})`, height: '120px' }}
                                            onClick={() => handleSelectAsset(bg)}
                                            title={bg.replace('.png', '')}
                                        />
                                    ))}
                                </div>
                            ) : (
                                <div className="appearance-upload-tab" style={{ padding: '20px', textAlign: 'center' }}>
                                    <label
                                        htmlFor="map-manual-upload"
                                        className="appearance-upload-area"
                                        style={{ border: '2px dashed var(--my-brown-medium)', padding: '40px', display: 'block', cursor: 'pointer', borderRadius: '12px' }}
                                    >
                                        <i className="fas fa-cloud-upload-alt" style={{ fontSize: '3rem', color: 'var(--my-gold)', marginBottom: '15px', display: 'block' }}></i>
                                        <span style={{ fontSize: '1.2rem', fontWeight: 'bold', color: 'var(--my-text-primary)' }}>Click to select a file from your device</span>
                                        <small style={{ display: 'block', marginTop: '10px', color: 'var(--my-text-secondary)' }}>Maximum file size: 10MB</small>
                                    </label>
                                    <input
                                        id="map-manual-upload"
                                        type="file"
                                        accept="image/*"
                                        onChange={(e) => {
                                            if (assetSelectorType === 'wizard') {
                                                handleImageUpload(e);
                                            } else {
                                                setShowBackgroundAssignment(targetMapForAsset);
                                                handleBackgroundUpload(e);
                                            }
                                            setShowAssetSelector(false);
                                        }}
                                        style={{ display: 'none' }}
                                    />
                                </div>
                            )}
                        </div>
                        <div className="character-appearance-modal-footer">
                            <button className="appearance-done-btn" onClick={() => setShowAssetSelector(false)}>
                                Cancel
                            </button>
                        </div>
                    </div>
                </div>,
                document.body
            )}

            {/* Hidden file input for background assignment */}
            <input
                ref={backgroundFileInputRef}
                type="file"
                accept="image/*"
                onChange={handleBackgroundUpload}
                style={{ display: 'none' }}
            />

            {/* Map Switch Confirmation Dialog */}
            <MapSwitchConfirmDialog
                isOpen={showSwitchConfirm}
                onClose={() => setShowSwitchConfirm(false)}
                onConfirm={handleConfirmSwitch}
                onStay={handleStayOnCurrentMap}
                newMapName={pendingMapSwitch?.newMapName || ''}
                thumbnail={pendingMapSwitch?.thumbnail || null}
                position={{ x: 450, y: 250 }}
            />

            {/* Map Delete Confirmation Dialog */}
            <MapDeleteConfirmDialog
                isOpen={showDeleteConfirm}
                onClose={cancelDeleteMap}
                onConfirm={confirmDeleteMap}
                mapName={pendingMapDelete?.name || ''}
                position={{ x: 450, y: 250 }}
            />

            {/* Map Edit Dialog */}
            {editingMapId && (
                <MythrillWindow
                    title="Edit Map"
                    isOpen={true}
                    onClose={handleCancelMapEdit}
                    defaultSize={{ width: 500, height: 350 }}
                    defaultPosition={{ x: 400, y: 200 }}
                    isModal={true}
                >
                    <div className="map-edit-dialog">
                        <div className="edit-field">
                            <label className="edit-label">Map Name</label>
                            <input
                                type="text"
                                className="wow-input"
                                value={editMapName}
                                onChange={(e) => setEditMapName(e.target.value)}
                                placeholder="Enter map name..."
                            />
                        </div>

                        <div className="edit-field">
                            <label className="edit-label">Description</label>
                            <textarea
                                className="wow-textarea"
                                value={editMapDescription}
                                onChange={(e) => setEditMapDescription(e.target.value)}
                                placeholder="Enter map description..."
                                rows={6}
                            />
                        </div>

                        <div className="edit-actions">
                            <button
                                className="wow-button secondary"
                                onClick={handleCancelMapEdit}
                            >
                                Cancel
                            </button>
                            <button
                                className="wow-button primary"
                                onClick={handleSaveMapEdit}
                                disabled={!editMapName.trim()}
                            >
                                Save Changes
                            </button>
                        </div>
                    </div>
                </MythrillWindow>
            )}
        </>
    );
};

export default MapLibraryWindow;

import React, { useRef, useState, forwardRef, useImperativeHandle, useEffect, useCallback } from 'react';
import { Resizable } from 'react-resizable';
import { createPortal } from 'react-dom';
import DraggableWindow from './DraggableWindow';
import useSettingsStore from '../../store/settingsStore';
import useWindowManagerStore from '../../store/windowManagerStore';
import { getSafePortalTarget } from '../../utils/portalUtils';
import { getIconUrl } from '../../utils/assetManager';
import '../../styles/wow-window.css';
import '../../styles/draggable-window.css';
import 'react-resizable/css/styles.css';

const MythrillWindow = forwardRef((props, ref) => {
    const {
        title,
        children,
        isOpen,
        onClose,
        defaultPosition = { x: 100, y: 100 },
        defaultSize = { width: 400, height: 600 },
        customHeader,
        headerTabs = [],
        activeTab,
        onTabChange,
        centered = false,
        bounds = "body",
        onDrag = null,
        onResize = null,
        className = "",
        resizable = true,
        minConstraints = [300, 400],
        maxConstraints = [2560, 1600],
        modal = false,
        backdrop = true,
        centerTitle = false
    } = props;

    // Ensure title is always defined
    const safeTitle = title || 'Window';

    // Create refs for components (hooks must be called before early returns)
    const draggableRef = useRef(null);
    const windowElementRef = useRef(null);

    // Generate unique window ID (stable across re-renders)
    const windowId = useRef(`wow-window-${Date.now()}-${Math.random()}`).current;

    // Get window scale from store
    const windowScale = useSettingsStore(state => state.windowScale);

    // Window manager store actions
    const registerWindow = useWindowManagerStore(state => state.registerWindow);
    const bringToFront = useWindowManagerStore(state => state.bringToFront);
    const unregisterWindow = useWindowManagerStore(state => state.unregisterWindow);
    const layoutVersion = useWindowManagerStore(state => state.layoutVersion);

    // Compute a cascade offset once on mount so successive windows don't pile
    // at the same (x, y). Centered windows skip this (they self-position).
    const cascadedPosition = useState(() => {
        if (centered) return defaultPosition;
        const offset = useWindowManagerStore.getState().getCascadeOffset();
        return { x: defaultPosition.x + offset.x, y: defaultPosition.y + offset.y };
    })[0];

    // State for window size
    const [windowSize, setWindowSize] = useState({
        width: defaultSize.width,
        height: defaultSize.height
    });

    // Listen for window scale changes - DraggableWindow now handles scaling properly
    useEffect(() => {
        const handleWindowScaleChange = () => {
            // DraggableWindow handles all scaling with proper hit detection
        };

        window.addEventListener('windowScaleChanged', handleWindowScaleChange);
        return () => window.removeEventListener('windowScaleChanged', handleWindowScaleChange);
    }, [windowScale]);

    // Expose methods to parent component
    useImperativeHandle(ref, () => ({
        getElement: () => windowElementRef.current,
        centerWindow: () => {
            if (draggableRef.current) {
                draggableRef.current.centerWindow();
            }
        }
    }));

    const hasBeenCentered = useRef(false);
    const prevCentered = useRef(centered);

    // Effect to handle window centering
    useEffect(() => {
        // Center the window on mount if centered is true, but only once
        if (centered && draggableRef.current && !hasBeenCentered.current) {
            // Use a timeout to ensure the window has rendered with its actual size
            const timer = setTimeout(() => {
                if (draggableRef.current) {
                    draggableRef.current.centerWindow();
                    hasBeenCentered.current = true;
                }
            }, 100);

            return () => clearTimeout(timer);
        }
    }, [centered]);

    // Reset centering flag if centered prop changes or window re-opens
    useEffect(() => {
        if (centered && !prevCentered.current) {
            hasBeenCentered.current = false;
        }
        prevCentered.current = centered;
    }, [centered]);

    // Effect to handle window resize for centered windows
    useEffect(() => {
        if (centered) {
            const handleResize = () => {
                if (draggableRef.current) {
                    draggableRef.current.centerWindow();
                }
            };

            window.addEventListener('resize', handleResize);
            return () => window.removeEventListener('resize', handleResize);
        }
    }, [centered]);

    // Track if window is being dragged or resized to prevent conflicts
    const [isDragging, setIsDragging] = useState(false);
    const [isResizing, setIsResizing] = useState(false);
    const [zIndex, setZIndex] = useState(1000);

    // Register window with window manager on mount
    useEffect(() => {
        const windowType = modal ? 'modal' : 'window';
        const initialZIndex = registerWindow(windowId, windowType, onClose);
        setZIndex(initialZIndex);

        return () => {
            unregisterWindow(windowId);
        };
    }, [windowId, registerWindow, unregisterWindow, modal]); // onClose intentionally omitted ÔÇô it's kept fresh via updateWindowOnClose below

    // Keep the latest onClose in a ref so we can register a STABLE wrapper with
    // the window manager. This breaks an infinite loop: previously the effect
    // depended on `onClose`, and parent components (e.g. Navigation) frequently
    // pass a new inline onClose on every render. Each call to
    // updateWindowOnClose replaced the store's `windows` Map, which re-rendered
    // those parents, which produced yet another new onClose reference, etc.
    const onCloseRef = useRef(onClose);
    useEffect(() => {
        onCloseRef.current = onClose;
    }, [onClose]);

    // Register a stable wrapper once per window. The wrapper always invokes the
    // freshest onClose via the ref, so we never need to re-register.
    useEffect(() => {
        const updateWindowOnClose = useWindowManagerStore.getState().updateWindowOnClose;
        if (updateWindowOnClose) {
            const stableWrapper = () => {
                if (typeof onCloseRef.current === 'function') {
                    onCloseRef.current();
                }
            };
            updateWindowOnClose(windowId, stableWrapper);
        }
    }, [windowId]);

    // Bring window to front when it opens
    useEffect(() => {
        if (isOpen) {
            // Small delay to ensure the window is registered first
            const timer = setTimeout(() => {
                const newZIndex = bringToFront(windowId);
                if (newZIndex) {
                    setZIndex(newZIndex);
                }
            }, 0);
            return () => clearTimeout(timer);
        }
    }, [isOpen, windowId, bringToFront]);

    // Handle window click to bring to front
    const handleWindowClick = useCallback((e) => {
        e.stopPropagation();

        if (!windowElementRef.current) return;
        if (!windowElementRef.current.contains(e.target)) return;

        const target = e.target;
        if (target.tagName === 'BUTTON' ||
            target.tagName === 'INPUT' ||
            target.tagName === 'SELECT' ||
            target.tagName === 'TEXTAREA' ||
            target.closest('button') ||
            target.closest('input') ||
            target.closest('select') ||
            target.closest('textarea')) {
            return;
        }

        if (!isDragging) {
            const newZIndex = bringToFront(windowId);
            if (newZIndex) {
                setZIndex(newZIndex);
            }
        }
    }, [isDragging, windowId, bringToFront]);

    const handleWindowMouseDown = useCallback((e) => {
        if (!isDragging && windowElementRef.current && windowElementRef.current.contains(e.target)) {
            const target = e.target;
            if (target.tagName !== 'BUTTON' &&
                target.tagName !== 'INPUT' &&
                target.tagName !== 'SELECT' &&
                target.tagName !== 'TEXTAREA' &&
                !target.closest('button') &&
                !target.closest('input') &&
                !target.closest('select') &&
                !target.closest('textarea')) {
                const newZIndex = bringToFront(windowId);
                if (newZIndex) {
                    setZIndex(newZIndex);
                }
            }
        }
    }, [isDragging, windowId, bringToFront]);

    // Ref to track resize size without causing re-renders during resize
    const resizeSizeRef = useRef({ width: windowSize.width, height: windowSize.height });

    // Handle resize start - disable transitions for smooth resizing
    const handleResizeStart = useCallback((event) => {
        setIsResizing(true);
        // Sync resizing state to store
        useWindowManagerStore.getState().setResizingWindowId(windowId);
        
        // Store initial size
        resizeSizeRef.current = { width: windowSize.width, height: windowSize.height };
        // Bring window to front when resize starts
        const newZIndex = bringToFront(windowId);
        if (newZIndex) {
            setZIndex(newZIndex);
        }
    }, [windowId, bringToFront, windowSize.width, windowSize.height]);

    // Handle resize - update local state only for visual feedback
    // DON'T notify parent during resize to prevent expensive re-renders
    const handleResize = useCallback((event, { size }) => {
        // Update local state for immediate visual feedback
        setWindowSize({
            width: size.width,
            height: size.height
        });
        // Store in ref for final update
        resizeSizeRef.current = size;
        // Don't call onResize here - wait until resize stops
    }, []);

    // Handle resize stop - notify parent only once when done
    const handleResizeStop = useCallback((event, { size }) => {
        setIsResizing(false);
        // Clear resizing state in store
        useWindowManagerStore.getState().setResizingWindowId(null);
        
        // Final size update to local state
        setWindowSize({
            width: size.width,
            height: size.height
        });
        // NOW notify parent component of final size (only once!)
        if (onResize) {
            onResize(size);
        }
    }, [onResize]);

    // Handle drag start/stop to prevent resize conflicts
    const handleDragStart = useCallback(() => {
        // Don't allow window dragging if an item is being dragged
        if (window.isDraggingItem) {
            return;
        }

        setIsDragging(true);
        // Sync dragging state to store
        useWindowManagerStore.getState().setDraggingWindowId(windowId);
        
        // Bring window to front when drag starts
        const newZIndex = bringToFront(windowId);
        if (newZIndex) {
            setZIndex(newZIndex);
        }
    }, [windowId, bringToFront]);

    const handleDragStop = useCallback((position) => {
        setIsDragging(false);
        // Clear dragging state in store
        useWindowManagerStore.getState().setDraggingWindowId(null);
        
        if (onDrag) {
            onDrag(position);
        }
    }, [onDrag]);

    // Handle wheel events within window content to prevent conflicts with grid
    const handleWindowWheel = useCallback((e) => {
        // Allow wheel events to bubble normally within window content
        // This prevents the Grid component from intercepting wheel events
        // when they occur within WoW windows
        e.stopPropagation();
    }, []);

    useEffect(() => {
        if (!modal || !isOpen) return;
        const dialog = windowElementRef.current;
        if (!dialog) return;

        const previouslyFocused = document.activeElement;
        dialog.focus();

        const handleKeydown = (e) => {
            if (e.key === 'Tab') {
                const items = dialog.querySelectorAll(
                    'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
                );
                if (items.length === 0) return;
                const first = items[0];
                const last = items[items.length - 1];
                if (e.shiftKey && document.activeElement === first) {
                    e.preventDefault();
                    last.focus();
                } else if (!e.shiftKey && document.activeElement === last) {
                    e.preventDefault();
                    first.focus();
                }
            }
        };
        dialog.addEventListener('keydown', handleKeydown);

        return () => {
            dialog.removeEventListener('keydown', handleKeydown);
            if (previouslyFocused && typeof previouslyFocused.focus === 'function') {
                try { previouslyFocused.focus(); } catch (_) {}
            }
        };
    }, [modal, isOpen]);

    // Don't render if not open (early return after all hooks)
    if (!isOpen) return null;

    // Use createPortal to render the window at the document body level
    // This ensures it's not constrained by any parent containers
    const portalTarget = getSafePortalTarget();

    // Safety check - don't render if no portal target available
    if (!portalTarget) {
        console.error('MythrillWindow: No portal target available, cannot render');
        return null;
    }

    return createPortal(
        <React.Fragment>
            {modal && backdrop !== false && (
                <div
                    className="wow-window-modal-backdrop"
                    style={{ zIndex: zIndex - 1 }}
                    onClick={backdrop === 'static' ? undefined : () => { if (onClose) onClose(); }}
                    aria-hidden="true"
                />
            )}
        <DraggableWindow
            ref={draggableRef}
            isOpen={isOpen}
            defaultPosition={cascadedPosition}
            defaultSize={windowSize}
            centered={centered}
            bounds={bounds}
            handleClassName="window-header"
            zIndex={zIndex}
            onDragStart={handleDragStart}
            onDragStop={handleDragStop}
            className={isResizing ? 'resizing' : ''}
            resetSignal={layoutVersion}
        >
            <Resizable
                width={windowSize.width}
                height={windowSize.height}
                minConstraints={minConstraints}
                maxConstraints={maxConstraints}
                onResizeStart={handleResizeStart}
                onResize={handleResize}
                onResizeStop={handleResizeStop}
                resizeHandles={resizable ? ['se'] : []}
                transformScale={windowScale}
            >
                <div
                    className={`wow-window ${className}`}
                    style={{
                        width: windowSize.width,
                        height: windowSize.height
                    }}
                    ref={windowElementRef}
                    role="dialog"
                    aria-modal={modal ? true : undefined}
                    aria-label={safeTitle}
                    tabIndex={modal ? -1 : undefined}
                    onClick={handleWindowClick}
                    onMouseDown={handleWindowMouseDown}
                >
                    <div className="window-header draggable-window-handle dnd-theme-header">
                        <div style={{ display: 'flex', alignItems: 'center', width: '100%', position: 'relative' }}>
                            {customHeader ? (
                                <>
                                    <div style={{ display: 'flex', alignItems: 'center', width: '100%', position: 'relative' }}>
                                        {customHeader}
                                        <button
                                            className="window-close"
                                            aria-label="Close"
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                if (onClose) onClose();
                                            }}
                                            style={{
                                                position: 'absolute',
                                                right: '8px',
                                                top: '50%',
                                                transform: 'translateY(-50%)',
                                                zIndex: 10
                                            }}
                                        >
                                            ´┐¢ - 
                                        </button>
                                    </div>
                                </>
                            ) : (
                                <div className="window-header-content">
                                    {centerTitle ? (
                                        <>
                                            <button
                                                className="window-close"
                                                aria-label="Close"
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    if (onClose) onClose();
                                                }}
                                            >
                                                ´┐¢ - 
                                            </button>
                                            <div className="window-title centered">{safeTitle}</div>
                                            <div className="header-spacer"></div>
                                        </>
                                    ) : (
                                        <>
                                            <div className="window-title">{safeTitle}</div>

                                            {/* Header tabs */}
                                            {headerTabs.length > 0 && (
                                                <div className="window-header-tabs">
                                                    {headerTabs.map((tab) => (
                                                        <button
                                                            key={tab.id}
                                                            className={`window-header-tab ${activeTab === tab.id ? 'active' : ''}`}
                                                            onClick={(e) => {
                                                                e.stopPropagation();
                                                                if (onTabChange) onTabChange(tab.id);
                                                            }}
                                                            title={tab.tooltip || tab.name}
                                                        >
                                                            {tab.icon && (
                                                                <img
                                                                    src={tab.icon}
                                                                    alt={tab.name}
                                                                    className="tab-icon-img"
                                                                    onError={(e) => {
                                                                        e.target.onerror = null;
                                                                        e.target.src = getIconUrl('inv_misc_questionmark', 'items');
                                                                    }}
                                                                />
                                                            )}
                                                            {tab.label && <span>{tab.label}</span>}
                                                        </button>
                                                    ))}
                                                </div>
                                            )}
                                            <button
                                                className="window-close"
                                                aria-label="Close"
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    if (onClose) onClose();
                                                }}
                                            >
                                                ´┐¢ - 
                                            </button>
                                        </>
                                    )}
                                </div>
                            )}
                        </div>
                    </div>
                    <div className="window-content" onWheel={handleWindowWheel}>
                        {children}
                    </div>
                </div>
            </Resizable>
        </DraggableWindow>
        </React.Fragment>,
        portalTarget
    );
});

